export default JSON.parse('{"work":{"id":"guo-yu","schoolId":"histories","title":"《國語》","genreStrategy":"parallel","sourceNote":"版本來源自通行本及校勘附記。","chapterIds":["guo-yu_ch-1","guo-yu_ch-2"],"totalChars":9865},"chapters":[{"id":"guo-yu_ch-1","workId":"guo-yu","order":1,"title":"周語上","difficulty":4,"estimatedMinutes":16,"passageIds":["guo-yu_ch-1_p-1","guo-yu_ch-1_p-2","guo-yu_ch-1_p-3","guo-yu_ch-1_p-4","guo-yu_ch-1_p-5","guo-yu_ch-1_p-6","guo-yu_ch-1_p-7","guo-yu_ch-1_p-8","guo-yu_ch-1_p-9","guo-yu_ch-1_p-10","guo-yu_ch-1_p-11","guo-yu_ch-1_p-12","guo-yu_ch-1_p-13","guo-yu_ch-1_p-14","guo-yu_ch-1_p-15","guo-yu_ch-1_p-16","guo-yu_ch-1_p-17","guo-yu_ch-1_p-18","guo-yu_ch-1_p-19","guo-yu_ch-1_p-20","guo-yu_ch-1_p-21","guo-yu_ch-1_p-22","guo-yu_ch-1_p-23","guo-yu_ch-1_p-24","guo-yu_ch-1_p-25","guo-yu_ch-1_p-26","guo-yu_ch-1_p-27","guo-yu_ch-1_p-28","guo-yu_ch-1_p-29"],"tags":[]},{"id":"guo-yu_ch-2","workId":"guo-yu","order":2,"title":"周語中","difficulty":4,"estimatedMinutes":17,"passageIds":["guo-yu_ch-2_p-1","guo-yu_ch-2_p-2","guo-yu_ch-2_p-3","guo-yu_ch-2_p-4","guo-yu_ch-2_p-5","guo-yu_ch-2_p-6","guo-yu_ch-2_p-7","guo-yu_ch-2_p-8","guo-yu_ch-2_p-9","guo-yu_ch-2_p-10","guo-yu_ch-2_p-11","guo-yu_ch-2_p-12","guo-yu_ch-2_p-13","guo-yu_ch-2_p-14","guo-yu_ch-2_p-15","guo-yu_ch-2_p-16","guo-yu_ch-2_p-17","guo-yu_ch-2_p-18","guo-yu_ch-2_p-19","guo-yu_ch-2_p-20","guo-yu_ch-2_p-21","guo-yu_ch-2_p-22","guo-yu_ch-2_p-23","guo-yu_ch-2_p-24","guo-yu_ch-2_p-25","guo-yu_ch-2_p-26","guo-yu_ch-2_p-27","guo-yu_ch-2_p-28","guo-yu_ch-2_p-29","guo-yu_ch-2_p-30"],"tags":[]}],"passages":[{"id":"guo-yu_ch-1_p-1","chapterId":"guo-yu_ch-1","order":1,"canonicalText":"穆王將徵犬戎，祭公謀父諫曰：「不可。先王耀德不觀兵。夫兵戢而時動，動則威，觀則玩，玩則無震。是故周文公之《》曰：『』先王之於民也，懋正其德而厚其性，阜其財求而利其器用，明利害之鄉，以文修之，使務利而避害，懷德而畏威，故能保世以滋大。","sentenceIds":["guo-yu_ch-1_p-1_s-1","guo-yu_ch-1_p-1_s-2","guo-yu_ch-1_p-1_s-3","guo-yu_ch-1_p-1_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guo-yu/zh"}],"readingAid":{"translation":"用現代漢語來說：厲王虐，國家人們謗王。召公告說：「民不堪命了！」王怒，得衛巫，使監視謗的人。國人莫敢言，道路用目。","analysis":"【主題與背景】針對王國的現象，這段文獻「厲王虐，國人謗王。召公告...」提供了深刻的視角。其背後的歷史情境，凸顯了各方勢力對於國家治理的多元思考。\\n【詞義與名物】在此，我們必須特別注意「人謗」與「厲虐」的時代含義。這些字眼不僅僅是字面上的意思，更包含了傳統禮法與社會結構的深層內涵。\\n【史家寄託】這不僅是一段關於人謗的歷史記載，更體現了史學家對王國現象的深刻批判。字裡行間流露出對理想政治與社會秩序的嚮往。"}},{"id":"guo-yu_ch-1_p-2","chapterId":"guo-yu_ch-1","order":2,"canonicalText":"「昔我先王世后稷，以服事虞、夏。及夏之衰也，棄稷不務，我先王不窋用失其官，而自竄於戎、狄之間，不敢怠業，時序其德，纂修其緒，修其訓典，朝夕恪勤，守以敦篤，奉以忠信，奕世載德，不忝前人。至於武王，昭前之光明而加之以慈和，事神保民，莫弗欣喜。商王帝辛，大惡於民。庶民不忍，欣戴武王，以致戎於商牧。是先王非務武也，勤恤民隱而除其害也。","sentenceIds":["guo-yu_ch-1_p-2_s-1","guo-yu_ch-1_p-2_s-2","guo-yu_ch-1_p-2_s-3","guo-yu_ch-1_p-2_s-4","guo-yu_ch-1_p-2_s-5","guo-yu_ch-1_p-2_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guo-yu/zh"}],"readingAid":{"translation":"昔我先王世后稷，以服事虞、夏；及夏之衰也，棄稷不務，我先王不窋用失其官，而自竄於戎、狄之間，不敢怠業，時序其德，纂修其緒，修其訓典，朝夕恪勤，守以敦篤，奉以忠信，奕世載德，不忝前人；至於武王，昭前之光明而加之以慈和，事神保民，莫弗欣喜；商王帝辛，大惡於民；庶民不忍，欣戴武王，以致戎於商牧；是先王非務武也，勤恤民隱而除其害也。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《國語・晉語五》。提出著名的「防民之口，甚於防川」政治哲學，主張開言路、順民心。\\n【詞義與名物】「防民之口，甚於防川」：古今著名的政治民主與輿論疏導名言；「宣之使言」：引導百姓大膽說話言事。\\n【思想與篇章】召公將水利疏導比喻為政治溝通，強調統治者必須聽取民意、暢通言路方能長治久安。"}},{"id":"guo-yu_ch-1_p-3","chapterId":"guo-yu_ch-1","order":3,"canonicalText":"「夫先王之制：邦內甸服，邦外侯服，侯、衛賓服，蠻、夷要服，戎、狄荒服。甸服者祭，侯服者祀，賓服者享，要服者貢，荒服者王。日祭、月祀、時享、歲貢、終王，先王之訓也。有不祭則修意，有不祀則修言，有不享則修文，有不貢則脩名，有不王則修德，序成而有不至則修刑。於是乎有刑不祭，伐不祀，徵不享，讓不貢，告不王。於是乎有刑罰之闢，有攻伐之兵，有征討之備，有威讓之令，有文告之辭。布令陳辭而又不至，則增修於德而無勤民於遠，是以近無不聽，遠無不服。","sentenceIds":["guo-yu_ch-1_p-3_s-1","guo-yu_ch-1_p-3_s-2","guo-yu_ch-1_p-3_s-3","guo-yu_ch-1_p-3_s-4","guo-yu_ch-1_p-3_s-5","guo-yu_ch-1_p-3_s-6","guo-yu_ch-1_p-3_s-7"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guo-yu/zh"}],"readingAid":{"translation":"夫先王之制：邦內甸服，邦外侯服，侯、衛賓服，蠻、夷要服，戎、狄荒服；甸服者祭，侯服者祀，賓服者享，要服者貢，荒服者王；日祭、月祀、時享、歲貢、終王，先王之訓也；有不祭則修意，有不祀則修言，有不享則修文，有不貢則脩名，有不王則修德，序成而有不至則修刑；於是乎有刑不祭，伐不祀，徵不享，讓不貢，告不王；於是乎有刑罰之闢，有攻伐之兵，有徵討之備，有威讓之令，有文告之辭；布令陳辭而又不至，則增修於德而無勤民於遠，是以近無不聽，遠無不服。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《國語》〈周語上〉，記錄先秦秦漢經典思想與歷史實踐之精華。\\n【詞義與名物】文中包含關鍵詞彙如：「夫先王之、邦內甸服、邦外侯服、衛賓服」，展現古代漢語精練優雅之語法結構。\\n【思想與篇章】本篇體現了修德立身、順應天道與治國安民的深遠哲理，具有極高的學術考證與思想啟發價值。"}},{"id":"guo-yu_ch-1_p-4","chapterId":"guo-yu_ch-1","order":4,"canonicalText":"「今自大畢、伯士之終也，犬戎氏以其職來王。天子曰：『予必以不享徵之，且觀之兵。』其無乃廢先王之訓而王幾頓乎！吾聞夫犬戎樹惇，帥舊德而守終純固，其有以御我矣！」王不聽，遂徵之，得四白狼，四白鹿以歸。自是荒服者不至。","sentenceIds":["guo-yu_ch-1_p-4_s-1","guo-yu_ch-1_p-4_s-2","guo-yu_ch-1_p-4_s-3","guo-yu_ch-1_p-4_s-4","guo-yu_ch-1_p-4_s-5","guo-yu_ch-1_p-4_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guo-yu/zh"}],"readingAid":{"translation":"今自大畢、伯士之終也，犬戎氏以其職來王；天孔子說：予必以不享徵之，且觀之兵；其無乃廢先王之訓而王幾頓乎；吾聞夫犬戎樹惇，帥舊德而守終純固，其有以御我矣；王不聽，遂徵之，得四白狼，四白鹿以歸；自是荒服者不至。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【題解與背景】\\n本段選自《國語》〈周語上〉，為該經典著作之精華章節，呈現先秦兩漢時期深刻的思想觀點與歷史實踐。\\n【詞義與名物】\\n文中經典語句「「今自大畢、伯士之終也，犬戎氏以其職……」詞意凝練，包含古漢語重要名詞概念與語法句式。\\n【思想與史事脈絡】\\n全段旨在大致闡發道德修養、因時制宜與實踐致用之根本原則，對後世國學研究具備極高的參考價值。"}},{"id":"guo-yu_ch-1_p-5","chapterId":"guo-yu_ch-1","order":5,"canonicalText":"恭王遊於涇上，密康公從，有三女奔之。其母曰：「必致之於王。夫獸三為羣，人三為眾，女三為粲。王田不取羣，公行下眾，王御不參一族。夫粲，美之物也。眾以美物歸女，而何德以堪之？王猶不堪，況爾小醜乎？小醜備物，終必亡。」康公不獻。一年，王滅密。","sentenceIds":["guo-yu_ch-1_p-5_s-1","guo-yu_ch-1_p-5_s-2","guo-yu_ch-1_p-5_s-3","guo-yu_ch-1_p-5_s-4","guo-yu_ch-1_p-5_s-5","guo-yu_ch-1_p-5_s-6","guo-yu_ch-1_p-5_s-7","guo-yu_ch-1_p-5_s-8","guo-yu_ch-1_p-5_s-9","guo-yu_ch-1_p-5_s-10"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guo-yu/zh"}],"readingAid":{"translation":"恭王遊於涇上，密康公從，有三女奔之；其母說：必致之於王；夫獸三為羣，人三為眾，女三為粲；王田不取羣，公行下眾，王御不參一族；夫粲，美之物也；眾以美物歸女，而何德以堪之；王猶不堪，況爾小醜乎；小醜備物，終必亡。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【題解與背景】\\n本段選自《國語》〈周語上〉，為該經典著作之精華章節，呈現先秦兩漢時期深刻的思想觀點與歷史實踐。\\n【詞義與名物】\\n文中經典語句「恭王遊於涇上，密康公從，有三女奔之。……」詞意凝練，包含古漢語重要名詞概念與語法句式。\\n【思想與史事脈絡】\\n全段旨在大致闡發道德修養、因時制宜與實踐致用之根本原則，對後世國學研究具備極高的參考價值。"}},{"id":"guo-yu_ch-1_p-6","chapterId":"guo-yu_ch-1","order":6,"canonicalText":"厲王虐，國人謗王。邵公告曰：「民不堪命矣！」王怒，得衛巫，使監謗者，以告，則殺之。國人莫敢言，道路以目。王喜，告邵公曰：「吾能弭謗矣，乃不敢言。」邵公曰：「是障之也，防民之口，甚於防川。川壅而潰，傷人必多，民亦如之。是故為川者決之使導，為民者宣之使言。故天子聽政，使公卿至於列士獻詩，瞽獻曲，史獻書，師箴，瞍賦，矇誦，百工諫，庶人傳語，近臣盡規，親戚補察，瞽、史教誨，耆、艾修之，而後王斟酌焉，是以事行而不悖。民之有口，猶土之有山川也，財用於是乎出，猶其原隰之有衍沃也，衣食於是乎生。口之宣言也，善敗於是乎興，行善而備敗，其所以阜財用、衣食者也。夫民慮之於心而宣之於口，成而行之，胡可壅也？若壅其口，其與能幾何？」王不聽，於是國莫敢出言，三年，乃流王於彘。","sentenceIds":["guo-yu_ch-1_p-6_s-1","guo-yu_ch-1_p-6_s-2","guo-yu_ch-1_p-6_s-3","guo-yu_ch-1_p-6_s-4","guo-yu_ch-1_p-6_s-5","guo-yu_ch-1_p-6_s-6","guo-yu_ch-1_p-6_s-7","guo-yu_ch-1_p-6_s-8","guo-yu_ch-1_p-6_s-9","guo-yu_ch-1_p-6_s-10","guo-yu_ch-1_p-6_s-11","guo-yu_ch-1_p-6_s-12","guo-yu_ch-1_p-6_s-13","guo-yu_ch-1_p-6_s-14"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guo-yu/zh"}],"readingAid":{"translation":"厲王虐，國人謗王；邵公告說：民不堪命矣；王怒，得衛巫，使監謗者，以告，則殺之；國人莫敢言，道路以目；王喜，告邵公說：吾能弭謗矣，乃不敢言；邵公說：是障之也，防民之口，甚於防川；川壅而潰，傷人必多，民亦如之；是故為川者決之使導，為民者宣之使言。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《國語》〈周語上〉，記錄先秦秦漢經典思想與歷史實踐之精華。\\n【詞義與名物】文中包含關鍵詞彙如：「厲王虐、國人謗王、邵公告曰、民不堪命」，展現古代漢語精練優雅之語法結構。\\n【思想與篇章】本篇體現了修德立身、順應天道與治國安民的深遠哲理，具有極高的學術考證與思想啟發價值。"}},{"id":"guo-yu_ch-1_p-7","chapterId":"guo-yu_ch-1","order":7,"canonicalText":"厲王說榮夷公，芮良夫曰：「王室其將卑乎！夫榮公好專利而不知大難。夫利，百物之所生也，天地之所載也，而或專之，其害多矣。天地百物，皆將取焉，胡可專也？所怒甚多，而不備大難，以是教王，王能久乎？夫王人者，將導利而布之上下者也，使神人百物無不得其極，猶曰怵惕，懼怨之來也。故《》曰：『思文后稷，克配彼天。立我蒸民，莫匪爾極。』《》曰：『陳錫載周。』是不布利而懼難乎？故能載周，以至於今。今王學專利，其可乎？匹夫專利，猶謂之盜，王而行之，其歸鮮矣。榮公若用，周必敗。既，榮公為卿士，諸侯不享，王流於彘。","sentenceIds":["guo-yu_ch-1_p-7_s-1","guo-yu_ch-1_p-7_s-2","guo-yu_ch-1_p-7_s-3","guo-yu_ch-1_p-7_s-4","guo-yu_ch-1_p-7_s-5","guo-yu_ch-1_p-7_s-6","guo-yu_ch-1_p-7_s-7","guo-yu_ch-1_p-7_s-8","guo-yu_ch-1_p-7_s-9","guo-yu_ch-1_p-7_s-10","guo-yu_ch-1_p-7_s-11","guo-yu_ch-1_p-7_s-12","guo-yu_ch-1_p-7_s-13","guo-yu_ch-1_p-7_s-14","guo-yu_ch-1_p-7_s-15"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guo-yu/zh"}],"readingAid":{"translation":"厲王說榮夷公，芮良夫說：王室其將卑乎；夫榮公好專利而不知大難；夫利，百物之所生也，天地之所載也，而或專之，其害多矣；天地百物，皆將取焉，胡可專也；所怒甚多，而不備大難，以是教王，王能久乎；夫王人者，將導利而布之上下者也，使神人百物無不得其極，猶說：怵惕，懼怨之來也；故《》說：思文后稷，克配彼天；立我蒸民，莫匪爾極。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《國語》〈周語上〉，記錄先秦秦漢經典思想與歷史實踐之精華。\\n【詞義與名物】文中包含關鍵詞彙如：「厲王說榮、夷公、芮良夫曰、王室其將」，展現古代漢語精練優雅之語法結構。\\n【思想與篇章】本篇體現了修德立身、順應天道與治國安民的深遠哲理，具有極高的學術考證與思想啟發價值。"}},{"id":"guo-yu_ch-1_p-8","chapterId":"guo-yu_ch-1","order":8,"canonicalText":"彘之亂，宣王在邵公之宮，國人圍之，邵公曰：「昔吾驟諫王，王不從，是以及此難。今殺王子，王其以我為懟而怒乎！夫事君者險而不懟，怨而不怒，況事王乎？」乃以其子代宣王，宣王長而立之。","sentenceIds":["guo-yu_ch-1_p-8_s-1","guo-yu_ch-1_p-8_s-2","guo-yu_ch-1_p-8_s-3","guo-yu_ch-1_p-8_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guo-yu/zh"}],"readingAid":{"translation":"彘之亂，宣王在邵公之宮，國人圍之，邵公說：昔吾驟諫王，王不從，是以及此難；今殺王子，王其以我為懟而怒乎；夫事君者險而不懟，怨而不怒，況事王乎；乃以其子代宣王，宣王長而立之。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【題解與背景】\\n本段選自《國語》〈周語上〉，為該經典著作之精華章節，呈現先秦兩漢時期深刻的思想觀點與歷史實踐。\\n【詞義與名物】\\n文中經典語句「彘之亂，宣王在邵公之宮，國人圍之，邵……」詞意凝練，包含古漢語重要名詞概念與語法句式。\\n【思想與史事脈絡】\\n全段旨在大致闡發道德修養、因時制宜與實踐致用之根本原則，對後世國學研究具備極高的參考價值。"}},{"id":"guo-yu_ch-1_p-9","chapterId":"guo-yu_ch-1","order":9,"canonicalText":"宣王即位，不籍千畝。虢文公諫曰：「不可。夫民之大事在農，上帝之粢盛於是乎出，民之蕃庶於是乎生，事之供給於是乎在，和協輯睦於是乎興，財用蕃殖於是乎始，敦庬純固於是乎成，是故稷為大官。古者，太史順時覛土，陽癉憤盈，土氣震發，農祥晨正，日月底於天廟，土乃脈發。","sentenceIds":["guo-yu_ch-1_p-9_s-1","guo-yu_ch-1_p-9_s-2","guo-yu_ch-1_p-9_s-3","guo-yu_ch-1_p-9_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guo-yu/zh"}],"readingAid":{"translation":"宣王即位，不籍千畝；虢文公諫說：不可；夫民之大事在農，上帝之粢盛於是乎出，民之蕃庶於是乎生，事之供給於是乎在，和協輯睦於是乎興，財用蕃殖於是乎始，敦庬純固於是乎成，是故稷為大官；古者，太史順時覛土，陽癉憤盈，土氣震發，農祥晨正，日月底於天廟，土乃脈發。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《國語》〈周語上〉，記錄先秦秦漢經典思想與歷史實踐之精華。\\n【詞義與名物】文中包含關鍵詞彙如：「宣王即位、不籍千畝、虢文公諫、不可」，展現古代漢語精練優雅之語法結構。\\n【思想與篇章】本篇體現了修德立身、順應天道與治國安民的深遠哲理，具有極高的學術考證與思想啟發價值。"}},{"id":"guo-yu_ch-1_p-10","chapterId":"guo-yu_ch-1","order":10,"canonicalText":"「先時九日，太史告稷曰：『自今至於初吉，陽氣俱蒸，土膏其動。弗震弗渝，脈其滿眚，穀乃不殖。』稷以告王曰：『史帥陽官以命我司事曰：「距今九日，土其俱動，王其祗祓，監農不易。」』王乃使司徒鹹戒公卿、百吏、庶民，司空除壇於籍，命農大夫鹹戒農用。","sentenceIds":["guo-yu_ch-1_p-10_s-1","guo-yu_ch-1_p-10_s-2","guo-yu_ch-1_p-10_s-3","guo-yu_ch-1_p-10_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guo-yu/zh"}],"readingAid":{"translation":"先時九日，太史告稷說：自今至於初吉，陽氣俱蒸，土膏其動；弗震弗渝，脈其滿眚，穀乃不殖；稷以告王說：史帥陽官以命我司事說：距今九日，土其俱動，王其祗祓，監農不易；王乃使司徒鹹戒公卿、百吏、庶民，司空除壇於籍，命農大夫鹹戒農用。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《國語》〈周語上〉，記錄先秦秦漢經典思想與歷史實踐之精華。\\n【詞義與名物】文中包含關鍵詞彙如：「先時九日、太史告稷、自今至於、初吉」，展現古代漢語精練優雅之語法結構。\\n【思想與篇章】本篇體現了修德立身、順應天道與治國安民的深遠哲理，具有極高的學術考證與思想啟發價值。"}},{"id":"guo-yu_ch-1_p-11","chapterId":"guo-yu_ch-1","order":11,"canonicalText":"「先時五日，瞽告有協風至，王即齋宮，百官御事，各即其齋三日。王乃淳濯饗醴，及期，鬱人薦鬯，犧人薦醴，王祼鬯，饗醴乃行，百吏、庶民畢從。及籍，后稷監之，膳夫、農正陳籍禮，太史贊王，王敬從之。王耕一墢，班三之，庶民終於千畝，其后稷省功，太史監之；司徒省民，太師監之；畢，宰夫陳饗，膳宰監之。膳夫贊王，王歆大牢，班嘗之，庶人終食。","sentenceIds":["guo-yu_ch-1_p-11_s-1","guo-yu_ch-1_p-11_s-2","guo-yu_ch-1_p-11_s-3","guo-yu_ch-1_p-11_s-4","guo-yu_ch-1_p-11_s-5","guo-yu_ch-1_p-11_s-6","guo-yu_ch-1_p-11_s-7"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guo-yu/zh"}],"readingAid":{"translation":"先時五日，瞽告有協風至，王即齋宮，百官御事，各即其齋三日；王乃淳濯饗醴，及期，鬱人薦鬯，犧人薦醴，王祼鬯，饗醴乃行，百吏、庶民畢從；及籍，后稷監之，膳夫、農正陳籍禮，太史贊王，王敬從之；王耕一墢，班三之，庶民終於千畝，其後稷省功，太史監之；司徒省民，太師監之；畢，宰夫陳饗，膳宰監之；膳夫贊王，王歆大牢，班嘗之，庶人終食。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《國語》〈周語上〉，記錄先秦秦漢經典思想與歷史實踐之精華。\\n【詞義與名物】文中包含關鍵詞彙如：「先時五日、瞽告有協、風至、王即齋宮」，展現古代漢語精練優雅之語法結構。\\n【思想與篇章】本篇體現了修德立身、順應天道與治國安民的深遠哲理，具有極高的學術考證與思想啟發價值。"}},{"id":"guo-yu_ch-1_p-12","chapterId":"guo-yu_ch-1","order":12,"canonicalText":"「是日也，瞽帥、音官以風土。廩於籍東南，鍾而藏之，而時布之於農。稷則遍誡百姓，紀農協功，曰：『陰陽分佈，震雷出滯。』土不備墾，闢在司寇。乃命其旅曰：『徇，農師一之，農正再之，后稷三之，司空四之，司徒五之，太保六之，太師七之，太史八之，宗伯九之，王則大徇，耨獲亦如之。』民用莫不震動，恪恭於農，修其疆畔，日服其鎛，不解於時，財用不乏，民用和同。","sentenceIds":["guo-yu_ch-1_p-12_s-1","guo-yu_ch-1_p-12_s-2","guo-yu_ch-1_p-12_s-3","guo-yu_ch-1_p-12_s-4","guo-yu_ch-1_p-12_s-5","guo-yu_ch-1_p-12_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guo-yu/zh"}],"readingAid":{"translation":"是日也，瞽帥、音官以風土；廩於籍東南，鍾而藏之，而時布之於農；稷則遍誡百姓，紀農協功，說：陰陽分佈，震雷出滯；土不備墾，闢在司寇；乃命其旅說：徇，農師一之，農正再之，后稷三之，司空四之，司徒五之，太保六之，太師七之，太史八之，宗伯九之，王則大徇，耨獲亦如之；民用莫不震動，恪恭於農，修其疆畔，日服其鎛，不解於時，財用不乏，民用和同。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《國語》〈周語上〉，記錄先秦秦漢經典思想與歷史實踐之精華。\\n【詞義與名物】文中包含關鍵詞彙如：「是日也、瞽帥、音官以風、廩於籍東」，展現古代漢語精練優雅之語法結構。\\n【思想與篇章】本篇體現了修德立身、順應天道與治國安民的深遠哲理，具有極高的學術考證與思想啟發價值。"}},{"id":"guo-yu_ch-1_p-13","chapterId":"guo-yu_ch-1","order":13,"canonicalText":"「是時也，王事唯農是務，無有求利於其官，以幹農功，三時務農而一時講武，故徵則有威，守則有財。若是，乃能媚於神而和於民矣，則享祀時至而佈施優裕也。今天子欲修先王之緒而棄其大功，匱神乏祀而困民之財，將何以求福用民？」王不聽。三十九年，戰於千畝，王師敗績於姜氏之戎。","sentenceIds":["guo-yu_ch-1_p-13_s-1","guo-yu_ch-1_p-13_s-2","guo-yu_ch-1_p-13_s-3","guo-yu_ch-1_p-13_s-4","guo-yu_ch-1_p-13_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guo-yu/zh"}],"readingAid":{"translation":"是時也，王事唯農是務，無有求利於其官，以幹農功，三時務農而一時講武，故徵則有威，守則有財；若是，乃能媚於神而和於民矣，則享祀時至而佈施優裕也；今天子欲修先王之緒而棄其大功，匱神乏祀而困民之財，將憑藉什麼求福用民；王不聽；三十九年，戰於千畝，王師敗績於姜氏之戎。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【題解與背景】\\n本段選自《國語》〈周語上〉，為該經典著作之精華章節，呈現先秦兩漢時期深刻的思想觀點與歷史實踐。\\n【詞義與名物】\\n文中經典語句「「是時也，王事唯農是務，無有求利於其……」詞意凝練，包含古漢語重要名詞概念與語法句式。\\n【思想與史事脈絡】\\n全段旨在大致闡發道德修養、因時制宜與實踐致用之根本原則，對後世國學研究具備極高的參考價值。"}},{"id":"guo-yu_ch-1_p-14","chapterId":"guo-yu_ch-1","order":14,"canonicalText":"魯武公以括與戲見王，王立戲，樊仲山父諫曰：「不可立也！不順必犯，犯王命必誅，故出令不可不順也。令之不行，政之不立。行而不順，民將棄上。夫下事上，少事長，所以為順也。今天子立諸侯而建其少，是教逆也。若魯從之而諸侯效之，王命將有所壅，若不從而誅之，是自誅王命也。是事也，誅亦失，不誅亦失，天子其圖之！」王卒立之。魯侯歸而卒，及魯人殺懿公而立伯御。","sentenceIds":["guo-yu_ch-1_p-14_s-1","guo-yu_ch-1_p-14_s-2","guo-yu_ch-1_p-14_s-3","guo-yu_ch-1_p-14_s-4","guo-yu_ch-1_p-14_s-5","guo-yu_ch-1_p-14_s-6","guo-yu_ch-1_p-14_s-7","guo-yu_ch-1_p-14_s-8","guo-yu_ch-1_p-14_s-9","guo-yu_ch-1_p-14_s-10"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guo-yu/zh"}],"readingAid":{"translation":"魯武公以括與戲見王，王立戲，樊仲山父諫說：不可立也；不順必犯，犯王命必誅，故出令不可不順也；令之不行，政之不立；行而不順，民將棄上；夫下事上，少事長，所以為順也；今天子立諸侯而建其少，是教逆也；若魯從之而諸侯效之，王命將有所壅，若不從而誅之，是自誅王命也；是事也，誅亦失，不誅亦失，天子其圖之。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【題解與背景】\\n本段選自《國語》〈周語上〉，為該經典著作之精華章節，呈現先秦兩漢時期深刻的思想觀點與歷史實踐。\\n【詞義與名物】\\n文中經典語句「魯武公以括與戲見王，王立戲，樊仲山父……」詞意凝練，包含古漢語重要名詞概念與語法句式。\\n【思想與史事脈絡】\\n全段旨在大致闡發道德修養、因時制宜與實踐致用之根本原則，對後世國學研究具備極高的參考價值。"}},{"id":"guo-yu_ch-1_p-15","chapterId":"guo-yu_ch-1","order":15,"canonicalText":"三十二年春，宣王伐魯，立孝公，諸侯從是而不睦。宣王欲得國子之能導訓諸侯者，樊穆仲曰：「魯侯孝。」王曰：「何以知之？」對曰：「肅恭明神而敬事耇老，賦事行刑，必問於遺訓而諮於故實，不幹所問，不犯所諮。」王曰：「然則能訓治其民矣。」乃命魯孝公於夷宮。","sentenceIds":["guo-yu_ch-1_p-15_s-1","guo-yu_ch-1_p-15_s-2","guo-yu_ch-1_p-15_s-3","guo-yu_ch-1_p-15_s-4","guo-yu_ch-1_p-15_s-5","guo-yu_ch-1_p-15_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guo-yu/zh"}],"readingAid":{"translation":"三十二年春，宣王伐魯，立孝公，諸侯從是而不睦；宣王欲得國子之能導訓諸侯者，樊穆仲說：魯侯孝；王說：憑藉什麼知之；回答說：肅恭明神而敬事耇老，賦事行刑，必問於遺訓而諮於故實，不幹所問，不犯所諮；王說：然則能訓治其民矣；乃命魯孝公於夷宮。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【題解與背景】\\n本段選自《國語》〈周語上〉，為該經典著作之精華章節，呈現先秦兩漢時期深刻的思想觀點與歷史實踐。\\n【詞義與名物】\\n文中經典語句「三十二年春，宣王伐魯，立孝公，諸侯從……」詞意凝練，包含古漢語重要名詞概念與語法句式。\\n【思想與史事脈絡】\\n全段旨在大致闡發道德修養、因時制宜與實踐致用之根本原則，對後世國學研究具備極高的參考價值。"}},{"id":"guo-yu_ch-1_p-16","chapterId":"guo-yu_ch-1","order":16,"canonicalText":"宣王既喪南國之師，乃料民於太原。仲山父諫曰：「民不可料也！夫古者不料民而知其少多，司民協孤終，司商協民姓，司徒協旅，司寇協奸，牧協職，工協革，場協入，廩協出，是則少多、死生、出入、往來者皆可知也，於是乎又審之以事，王治農於籍，蒐於農隙，耨獲亦於籍，獮於既烝，狩於畢時，是皆習民數者也，又何料焉？不謂其少而大料之，是示少而惡事也。臨政示少，諸侯避之。治民惡事，無以賦令。且無故而料民，天之所惡也，害於政而妨於後嗣。」王卒料之，及幽王乃廢滅。","sentenceIds":["guo-yu_ch-1_p-16_s-1","guo-yu_ch-1_p-16_s-2","guo-yu_ch-1_p-16_s-3","guo-yu_ch-1_p-16_s-4","guo-yu_ch-1_p-16_s-5","guo-yu_ch-1_p-16_s-6","guo-yu_ch-1_p-16_s-7","guo-yu_ch-1_p-16_s-8"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guo-yu/zh"}],"readingAid":{"translation":"宣王既喪南國之師，乃料民於太原；仲山父諫說：民不可料也；夫古者不料民而知其少多，司民協孤終，司商協民姓，司徒協旅，司寇協奸，牧協職，工協革，場協入，廩協出，是則少多、死生、出入、往來者皆可知也，於是乎又審之以事，王治農於籍，蒐於農隙，耨獲亦於籍，獮於既烝，狩於畢時，是皆習民數者也，又何料焉；不謂其少而大料之，是示少而惡事也；臨政示少，諸侯避之；治民惡事，無以賦令；且無故而料民，天之所惡也，害於政而妨於後嗣；王去世料之，及幽王乃廢滅。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《國語》〈周語上〉，記錄先秦秦漢經典思想與歷史實踐之精華。\\n【詞義與名物】文中包含關鍵詞彙如：「宣王既喪、南國之師、乃料民於、太原」，展現古代漢語精練優雅之語法結構。\\n【思想與篇章】本篇體現了修德立身、順應天道與治國安民的深遠哲理，具有極高的學術考證與思想啟發價值。"}},{"id":"guo-yu_ch-1_p-17","chapterId":"guo-yu_ch-1","order":17,"canonicalText":"幽王二年，西周三川皆震。伯陽父曰：「周將亡矣！夫天地之氣，不失其序；若過其序，民亂之也。陽伏而不能出，陰迫而不能烝，於是有地震。今三川實震，是陽失其所而鎮陰也。陽失而在陰，川源必塞；源塞，國必亡。夫水土演而民用也。水土無所演，民乏財用，不亡何待？昔伊、洛竭而夏亡，河竭而商亡。今周德若二代之季矣，其川源又塞，塞必竭。夫國必依山川，山崩川竭，亡之徵也。川竭，山必崩。若國亡不過十年，數之紀也。夫天之所棄，不過其紀。」是歲也，三川竭，岐山崩。十一年，幽王乃滅，周乃東遷。","sentenceIds":["guo-yu_ch-1_p-17_s-1","guo-yu_ch-1_p-17_s-2","guo-yu_ch-1_p-17_s-3","guo-yu_ch-1_p-17_s-4","guo-yu_ch-1_p-17_s-5","guo-yu_ch-1_p-17_s-6","guo-yu_ch-1_p-17_s-7","guo-yu_ch-1_p-17_s-8","guo-yu_ch-1_p-17_s-9","guo-yu_ch-1_p-17_s-10","guo-yu_ch-1_p-17_s-11","guo-yu_ch-1_p-17_s-12","guo-yu_ch-1_p-17_s-13","guo-yu_ch-1_p-17_s-14","guo-yu_ch-1_p-17_s-15","guo-yu_ch-1_p-17_s-16","guo-yu_ch-1_p-17_s-17","guo-yu_ch-1_p-17_s-18"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guo-yu/zh"}],"readingAid":{"translation":"幽王二年，西周三川皆震；伯陽父說：周將亡矣；夫天地之氣，不失其序；若過其序，民亂之也；陽伏而不能出，陰迫而不能烝，於是有地震；今三川實震，是陽失其所而鎮陰也；陽失而在陰，川源必塞；源塞，國必亡；夫水土演而民用也；水土無所演，民乏財用，不亡何待。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《國語》〈周語上〉，記錄先秦秦漢經典思想與歷史實踐之精華。\\n【詞義與名物】文中包含關鍵詞彙如：「幽王二年、西周三川、皆震、伯陽父曰」，展現古代漢語精練優雅之語法結構。\\n【思想與篇章】本篇體現了修德立身、順應天道與治國安民的深遠哲理，具有極高的學術考證與思想啟發價值。"}},{"id":"guo-yu_ch-1_p-18","chapterId":"guo-yu_ch-1","order":18,"canonicalText":"惠王三年，邊伯、石速、蒍國出王而立子頹。王處於鄭三年。王子頹飲三大夫酒，子國為客，樂及遍舞。鄭厲公見虢叔，曰：「吾聞之，司寇行戮，君為之不舉，而況敢樂禍乎！今吾聞子頹歌舞不息，樂禍也。夫出王而代其位，禍孰大焉！臨禍忘憂，是謂樂禍，禍必及之，盍納王乎？」虢叔許諾。鄭伯將王自圉門入，虢叔自北門入，殺子頹及三大夫，王乃入也。","sentenceIds":["guo-yu_ch-1_p-18_s-1","guo-yu_ch-1_p-18_s-2","guo-yu_ch-1_p-18_s-3","guo-yu_ch-1_p-18_s-4","guo-yu_ch-1_p-18_s-5","guo-yu_ch-1_p-18_s-6","guo-yu_ch-1_p-18_s-7","guo-yu_ch-1_p-18_s-8","guo-yu_ch-1_p-18_s-9"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guo-yu/zh"}],"readingAid":{"translation":"惠王三年，邊伯、石速、蒍國出王而立子頹；王處於鄭三年；王子頹飲三大夫酒，子國為客，樂及遍舞；鄭厲公見虢叔，說：吾聞之，司寇行戮，君為之不舉，而況敢樂禍乎；今吾聞子頹歌舞不息，樂禍也；夫出王而代其位，禍孰大焉；臨禍忘憂，是謂樂禍，禍必及之，盍納王乎；虢叔許諾。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《國語》〈周語上〉，記錄先秦秦漢經典思想與歷史實踐之精華。\\n【詞義與名物】文中包含關鍵詞彙如：「惠王三年、邊伯、石速、蒍國出王」，展現古代漢語精練優雅之語法結構。\\n【思想與篇章】本篇體現了修德立身、順應天道與治國安民的深遠哲理，具有極高的學術考證與思想啟發價值。"}},{"id":"guo-yu_ch-1_p-19","chapterId":"guo-yu_ch-1","order":19,"canonicalText":"十五年，有神降於莘，王問於內史過，曰：「是何故？固有之乎？」對曰：「有之。國之將興，其君齊明、衷正、精潔、惠和，其德足以昭其馨香，其惠足以同其民人。神饗而民聽，民神無怨，故明神降之，觀其政德而均布福焉。國之將亡，其君貪冒、辟邪、淫佚、荒怠、粗穢、暴虐；其政腥臊，馨香不登；其刑矯誣，百姓攜貳。明神不蠲而民有遠志，民神怨痛，無所依懷，故神亦往焉，觀其苛慝而降之禍。是以或見神以興，亦或以亡。昔夏之興也，融降於崇山；其亡也，回祿信於耹隧。商之興也，檮杌次於丕山，其亡也，夷羊在牧。周之興也，鸑鷟鳴於岐山；其衰也，杜伯射王於鄗。是皆明神之志者也。」","sentenceIds":["guo-yu_ch-1_p-19_s-1","guo-yu_ch-1_p-19_s-2","guo-yu_ch-1_p-19_s-3","guo-yu_ch-1_p-19_s-4","guo-yu_ch-1_p-19_s-5","guo-yu_ch-1_p-19_s-6","guo-yu_ch-1_p-19_s-7","guo-yu_ch-1_p-19_s-8","guo-yu_ch-1_p-19_s-9","guo-yu_ch-1_p-19_s-10","guo-yu_ch-1_p-19_s-11","guo-yu_ch-1_p-19_s-12","guo-yu_ch-1_p-19_s-13","guo-yu_ch-1_p-19_s-14","guo-yu_ch-1_p-19_s-15","guo-yu_ch-1_p-19_s-16","guo-yu_ch-1_p-19_s-17"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guo-yu/zh"}],"readingAid":{"translation":"十五年，有神降於莘，王問於內史過，說：是何故；固有之乎；回答說：有之；國之將興，其君齊明、衷正、精潔、惠和，其德足以昭其馨香，其惠足以同其民人；神饗而民聽，民神無怨，故明神使其全軍投降，觀其政德而均布福焉；國之將亡，其君貪冒、辟邪、淫佚、荒怠、粗穢、暴虐；其政腥臊，馨香不登；其刑矯誣，百姓攜貳；明神不蠲而民有遠志，民神怨痛，無所依懷，故神亦往焉，觀其苛慝而使其全軍投降禍；是以或見神以興，亦或以亡。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《國語》〈周語上〉，記錄先秦秦漢經典思想與歷史實踐之精華。\\n【詞義與名物】文中包含關鍵詞彙如：「十五年、有神降於、王問於內、史過」，展現古代漢語精練優雅之語法結構。\\n【思想與篇章】本篇體現了修德立身、順應天道與治國安民的深遠哲理，具有極高的學術考證與思想啟發價值。"}},{"id":"guo-yu_ch-1_p-20","chapterId":"guo-yu_ch-1","order":20,"canonicalText":"王曰：「今是何神也？」對曰：「昔昭王娶於房，曰房後，實有爽德，協于丹朱，丹朱憑身以儀之，生穆王焉。是實臨照周之子孫而禍福之。夫神壹不遠徙遷，若由是觀之，其丹朱之神乎？」王曰：「其誰受之？」對曰：「在虢土。」王曰：「然則何為？」對曰：「臣聞之：道而得神，是謂逢福；淫而得神，是謂貪禍。今虢少荒，其亡乎？」王曰：「吾其若之何？」對曰：「使太宰以祝，史帥貍姓，奉犧牲、粢盛、玉帛往獻焉，無有祈也。」","sentenceIds":["guo-yu_ch-1_p-20_s-1","guo-yu_ch-1_p-20_s-2","guo-yu_ch-1_p-20_s-3","guo-yu_ch-1_p-20_s-4","guo-yu_ch-1_p-20_s-5","guo-yu_ch-1_p-20_s-6","guo-yu_ch-1_p-20_s-7","guo-yu_ch-1_p-20_s-8","guo-yu_ch-1_p-20_s-9","guo-yu_ch-1_p-20_s-10","guo-yu_ch-1_p-20_s-11","guo-yu_ch-1_p-20_s-12","guo-yu_ch-1_p-20_s-13"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guo-yu/zh"}],"readingAid":{"translation":"王說：今是何神也；回答說：昔昭王娶於房，說：房後，實有爽德，協于丹朱，丹朱憑身以儀之，生穆王焉；是實臨照周之子孫而禍福之；夫神壹不遠徙遷，若由是觀之，其丹朱之神乎；王說：其誰受之；回答說：在虢土；王說：然則做什麼；回答說：臣聞之：道而得神，是謂逢福；淫而得神，是謂貪禍。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【題解與背景】\\n本段選自《國語》〈周語上〉，為該經典著作之精華章節，呈現先秦兩漢時期深刻的思想觀點與歷史實踐。\\n【詞義與名物】\\n文中經典語句「王曰：「今是何神也？」對曰：「昔昭王……」詞意凝練，包含古漢語重要名詞概念與語法句式。\\n【思想與史事脈絡】\\n全段旨在大致闡發道德修養、因時制宜與實踐致用之根本原則，對後世國學研究具備極高的參考價值。"}},{"id":"guo-yu_ch-1_p-21","chapterId":"guo-yu_ch-1","order":21,"canonicalText":"王曰：「虢其幾何？」對曰：「昔堯臨民以五，今其胄見，神之見也，不過其物。若由是觀之，不過五年。」王使太宰忌父帥傅氏及祝、史奉犧牲、玉鬯往獻焉。內史過從至虢，虢公亦使祝、史請土焉。內史過歸，以告王曰：「虢必亡矣，不禋於神而求福焉，神必禍之；不親於民而求用焉，人必違之。精意以享，禋也；慈保庶民，親也。今虢公動匱百姓以逞其違，離民怒神而求利焉，不亦難乎！」十九年，晉取虢。","sentenceIds":["guo-yu_ch-1_p-21_s-1","guo-yu_ch-1_p-21_s-2","guo-yu_ch-1_p-21_s-3","guo-yu_ch-1_p-21_s-4","guo-yu_ch-1_p-21_s-5","guo-yu_ch-1_p-21_s-6","guo-yu_ch-1_p-21_s-7","guo-yu_ch-1_p-21_s-8","guo-yu_ch-1_p-21_s-9","guo-yu_ch-1_p-21_s-10","guo-yu_ch-1_p-21_s-11"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guo-yu/zh"}],"readingAid":{"translation":"王說：虢其幾何；回答說：昔堯臨民以五，今其胄見，神之見也，不過其物；若由是觀之，不過五年；王使太宰忌父帥傅氏及祝、史奉犧牲、玉鬯往獻焉；內史過從至虢，虢公亦使祝、史請土焉；內史過歸，以告王說：虢必亡矣，不禋於神而求福焉，神必禍之；不親於民而求用焉，人必違之；精意以享，禋也；慈保庶民，親也；今虢公動匱百姓以逞其違，離民怒神而求利焉，不亦難乎。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《國語》〈周語上〉，記錄先秦秦漢經典思想與歷史實踐之精華。\\n【詞義與名物】文中包含關鍵詞彙如：「王曰、虢其幾何、對曰、昔堯臨民」，展現古代漢語精練優雅之語法結構。\\n【思想與篇章】本篇體現了修德立身、順應天道與治國安民的深遠哲理，具有極高的學術考證與思想啟發價值。"}},{"id":"guo-yu_ch-1_p-22","chapterId":"guo-yu_ch-1","order":22,"canonicalText":"襄王使邵公過及內史過賜晉惠公命，呂甥、郤芮相晉侯不敬，晉侯執玉卑，拜不稽首。內史過歸，以告王曰：「晉不亡，其君必無後。且呂、郤將不免。」王曰：「何故？」對曰：「《》有之曰：『眾非元後，何戴？後非眾，無與守邦。』在《》曰：『餘一人有罪，無以萬夫；萬夫有罪，在餘一人。』在《》曰：『國之臧，則惟女眾。國之不臧，則惟餘一人，是有逸罰。』如是則長眾使民，不可不慎也。民之所急在大事，先王知大事之必以眾濟也，是故祓除其心，以和惠民。考中度衷以蒞之，昭明物則以訓之，制義庶孚以行之。祓除其心，精也；考中度衷，忠也；昭明物則，禮也；制義庶孚，信也。然則長眾使民之道，非精不和，非忠不立，非禮不順，非信不行。今晉侯即位而背外內之賂，虐其處者，棄其信也；不敬王命，棄其禮也；施其所惡，棄其忠也；以惡實心，棄其精也。四者皆棄，則遠不至而近不和矣，將何以守國？","sentenceIds":["guo-yu_ch-1_p-22_s-1","guo-yu_ch-1_p-22_s-2","guo-yu_ch-1_p-22_s-3","guo-yu_ch-1_p-22_s-4","guo-yu_ch-1_p-22_s-5","guo-yu_ch-1_p-22_s-6","guo-yu_ch-1_p-22_s-7","guo-yu_ch-1_p-22_s-8","guo-yu_ch-1_p-22_s-9","guo-yu_ch-1_p-22_s-10","guo-yu_ch-1_p-22_s-11","guo-yu_ch-1_p-22_s-12","guo-yu_ch-1_p-22_s-13","guo-yu_ch-1_p-22_s-14","guo-yu_ch-1_p-22_s-15","guo-yu_ch-1_p-22_s-16","guo-yu_ch-1_p-22_s-17","guo-yu_ch-1_p-22_s-18","guo-yu_ch-1_p-22_s-19","guo-yu_ch-1_p-22_s-20","guo-yu_ch-1_p-22_s-21","guo-yu_ch-1_p-22_s-22","guo-yu_ch-1_p-22_s-23"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guo-yu/zh"}],"readingAid":{"translation":"襄王使邵公過及內史過賜晉惠公命，呂甥、郤芮相晉侯不敬，晉侯執玉卑，拜不稽首；內史過歸，以告王說：晉不亡，其君必無後；且呂、郤將不免；王說：何故；回答說：《》有之說：眾非元後，何戴；後非眾，無與守邦；在《》說：餘一人有罪，無以萬夫；萬夫有罪，在餘一人；在《》說：國之臧，則惟女眾。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《國語》〈周語上〉，記錄先秦秦漢經典思想與歷史實踐之精華。\\n【詞義與名物】文中包含關鍵詞彙如：「襄王使邵、公過及內、史過賜晉、惠公命」，展現古代漢語精練優雅之語法結構。\\n【思想與篇章】本篇體現了修德立身、順應天道與治國安民的深遠哲理，具有極高的學術考證與思想啟發價值。"}},{"id":"guo-yu_ch-1_p-23","chapterId":"guo-yu_ch-1","order":23,"canonicalText":"「古者，先王既有天下，又崇立上帝、明神而敬事之，於是乎有朝日、夕月以教民事君。諸侯春秋受職於王以臨其民，大夫、士日恪位著以儆其官，庶人、工、商各守其業以共其上。猶恐其有墜失也，故為車服、旗章以旌之，為贄幣、瑞節以鎮之，為班爵、貴賤以列之，為令聞嘉譽以聲之。猶有散、遷、懈慢而著在刑辟，流在裔土，於是乎有蠻、夷之國，有斧鉞、刀墨之民，而況可以淫縱其身乎？","sentenceIds":["guo-yu_ch-1_p-23_s-1","guo-yu_ch-1_p-23_s-2","guo-yu_ch-1_p-23_s-3","guo-yu_ch-1_p-23_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guo-yu/zh"}],"readingAid":{"translation":"古者，先王既有天下，又崇立上帝、明神而敬事之，於是乎有朝日、夕月以教民事君；諸侯春秋受職於王以臨其民，大夫、士日恪位著以儆其官，庶人、工、商各守其業以共其上；猶恐其有墜失也，故為車服、旗章以旌之，為贄幣、瑞節以鎮之，為班爵、貴賤以列之，為令聞嘉譽以聲之；猶有散、遷、懈慢而著在刑辟，流在裔土，於是乎有蠻、夷之國，有斧鉞、刀墨之民，而況可以淫縱其身乎。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《國語》〈周語上〉，記錄先秦秦漢經典思想與歷史實踐之精華。\\n【詞義與名物】文中包含關鍵詞彙如：「古者、先王既有、天下、又崇立上」，展現古代漢語精練優雅之語法結構。\\n【思想與篇章】本篇體現了修德立身、順應天道與治國安民的深遠哲理，具有極高的學術考證與思想啟發價值。"}},{"id":"guo-yu_ch-1_p-24","chapterId":"guo-yu_ch-1","order":24,"canonicalText":"「夫晉侯非嗣也，而得其位，亹亹怵惕，保任戒懼，猶曰未也。若將廣其心而遠其鄰，陵其民而卑其上，將何以固守？","sentenceIds":["guo-yu_ch-1_p-24_s-1","guo-yu_ch-1_p-24_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guo-yu/zh"}],"readingAid":{"translation":"夫晉侯非嗣也，而得其位，亹亹怵惕，保任戒懼，猶說：未也；若將廣其心而遠其鄰，陵其民而卑其上，將憑藉什麼固守。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《國語》〈周語上〉，屬於典籍核心篇章，記錄古代思想家之智慧結晶。\\n【詞義與名物】文中字句對仗工整，包含「「夫晉侯非嗣」等關鍵文言名物與語法結構。\\n【思想與篇章】本段旨在闡述立身處世、修德行道與治國理政之根本哲理，具備深刻的思想啟發價值。"}},{"id":"guo-yu_ch-1_p-25","chapterId":"guo-yu_ch-1","order":25,"canonicalText":"「夫執玉卑，替其贄也；拜不稽首，誣其王也。替贄無鎮，誣王無民。夫天事恆象，任重享大者必速及，故晉侯誣王，人亦將誣之；欲替其鎮，人亦將替之。大臣享其祿，弗諫而阿之，亦必及焉。」","sentenceIds":["guo-yu_ch-1_p-25_s-1","guo-yu_ch-1_p-25_s-2","guo-yu_ch-1_p-25_s-3","guo-yu_ch-1_p-25_s-4","guo-yu_ch-1_p-25_s-5","guo-yu_ch-1_p-25_s-6","guo-yu_ch-1_p-25_s-7"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guo-yu/zh"}],"readingAid":{"translation":"夫執玉卑，替其贄也；拜不稽首，誣其王也；替贄無鎮，誣王無民；夫天事恆象，任重享大者必速及，故晉侯誣王，人亦將誣之；欲替其鎮，人亦將替之；大臣享其祿，弗諫而阿之，亦必及焉。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【題解與背景】\\n本段選自《國語》〈周語上〉，為該經典著作之精華章節，呈現先秦兩漢時期深刻的思想觀點與歷史實踐。\\n【詞義與名物】\\n文中經典語句「「夫執玉卑，替其贄也；拜不稽首，誣其……」詞意凝練，包含古漢語重要名詞概念與語法句式。\\n【思想與史事脈絡】\\n全段旨在大致闡發道德修養、因時制宜與實踐致用之根本原則，對後世國學研究具備極高的參考價值。"}},{"id":"guo-yu_ch-1_p-26","chapterId":"guo-yu_ch-1","order":26,"canonicalText":"襄王三年而立晉侯，八年而隕於韓，十六年而晉人殺懷公。懷公無胄，秦人殺子金、子公。","sentenceIds":["guo-yu_ch-1_p-26_s-1","guo-yu_ch-1_p-26_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guo-yu/zh"}],"readingAid":{"translation":"襄王三年而立晉侯，八年而隕於韓，十六年而晉人殺懷公；懷公無胄，秦人殺子金、子公。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【題解與背景】\\n本段選自《國語》〈周語上〉，為該經典著作之精華章節，呈現先秦兩漢時期深刻的思想觀點與歷史實踐。\\n【詞義與名物】\\n文中經典語句「襄王三年而立晉侯，八年而隕於韓，十六……」詞意凝練，包含古漢語重要名詞概念與語法句式。\\n【思想與史事脈絡】\\n全段旨在大致闡發道德修養、因時制宜與實踐致用之根本原則，對後世國學研究具備極高的參考價值。"}},{"id":"guo-yu_ch-1_p-27","chapterId":"guo-yu_ch-1","order":27,"canonicalText":"襄王使太宰文公及內史興賜晉文公命，上卿逆於境，晉侯郊勞，館諸宗廟，饋九牢，設庭燎。及期命於武宮，設桑主，布幾筵，太宰蒞之，晉侯端委以入。太宰以王命命冕服，內史贊之，三命而後即冕服。既畢，賓、饗、贈、餞如公命侯伯之禮，而加之以宴好。內史興歸，以告王曰：「晉，不可不善也。其君必霸，逆王命敬，奉禮義成。敬王命，順之道也；成禮義，德之則也。則德以導諸侯，諸侯必歸之。且禮所以觀忠、信、仁、義也，忠所以分也，仁所以行也，信所以守也，義所以節也。忠分則均，仁行則報，信守則固，義節則度。分均無怨，行報無匱，守固不偷，節度不攜。若民不怨而財不匱，令不偷而動不攜，其何事不濟！中能應外，忠也；施三服義，仁也；守節不淫，信也，行禮不疚，義也。臣入晉境，四者不失，臣故曰：『晉侯其能禮矣，王其善之！』樹於有禮，艾人必豐。」","sentenceIds":["guo-yu_ch-1_p-27_s-1","guo-yu_ch-1_p-27_s-2","guo-yu_ch-1_p-27_s-3","guo-yu_ch-1_p-27_s-4","guo-yu_ch-1_p-27_s-5","guo-yu_ch-1_p-27_s-6","guo-yu_ch-1_p-27_s-7","guo-yu_ch-1_p-27_s-8","guo-yu_ch-1_p-27_s-9","guo-yu_ch-1_p-27_s-10","guo-yu_ch-1_p-27_s-11","guo-yu_ch-1_p-27_s-12","guo-yu_ch-1_p-27_s-13","guo-yu_ch-1_p-27_s-14","guo-yu_ch-1_p-27_s-15","guo-yu_ch-1_p-27_s-16","guo-yu_ch-1_p-27_s-17","guo-yu_ch-1_p-27_s-18","guo-yu_ch-1_p-27_s-19"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guo-yu/zh"}],"readingAid":{"translation":"襄王使太宰文公及內史興賜晉文公命，上卿逆於境，晉侯郊勞，館諸宗廟，饋九牢，設庭燎；及期命於武宮，設桑主，布幾筵，太宰蒞之，晉侯端委以入；太宰以王命命冕服，內史贊之，三命而後即冕服；既畢，賓、饗、贈、餞如公命侯伯之禮，而加之以宴好；內史興歸，以告王說：晉，不可不善也；其君必霸，逆王命敬，奉禮義成；敬王命，順之道也；成禮義，德之則也；則德以導諸侯，諸侯必歸之。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《國語》〈周語上〉，記錄先秦秦漢經典思想與歷史實踐之精華。\\n【詞義與名物】文中包含關鍵詞彙如：「襄王使太、宰文公及、內史興賜、晉文公命」，展現古代漢語精練優雅之語法結構。\\n【思想與篇章】本篇體現了修德立身、順應天道與治國安民的深遠哲理，具有極高的學術考證與思想啟發價值。"}},{"id":"guo-yu_ch-1_p-28","chapterId":"guo-yu_ch-1","order":28,"canonicalText":"王從之，使於晉者，道相逮也。及惠後之難，王出在鄭，晉侯納之。","sentenceIds":["guo-yu_ch-1_p-28_s-1","guo-yu_ch-1_p-28_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guo-yu/zh"}],"readingAid":{"translation":"王從之，使於晉者，道相逮也；及惠後之難，王出在鄭，晉侯納之。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《國語》〈周語上〉，屬於典籍核心篇章，記錄古代思想家之智慧結晶。\\n【詞義與名物】文中字句對仗工整，包含「王從之，使於」等關鍵文言名物與語法結構。\\n【思想與篇章】本段旨在闡述立身處世、修德行道與治國理政之根本哲理，具備深刻的思想啟發價值。"}},{"id":"guo-yu_ch-1_p-29","chapterId":"guo-yu_ch-1","order":29,"canonicalText":"襄王十六年，立晉文公。二十一年，以諸侯朝王于衡雍，且獻楚捷，遂為踐土之盟，於是乎始霸。","sentenceIds":["guo-yu_ch-1_p-29_s-1","guo-yu_ch-1_p-29_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guo-yu/zh"}],"readingAid":{"translation":"襄王十六年，立晉文公；二十一年，以諸侯朝王于衡雍，且獻楚捷，遂為踐土之盟，於是乎始霸。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《國語》〈周語上〉，記錄先秦秦漢經典思想與歷史實踐之精華。\\n【詞義與名物】文中包含關鍵詞彙如：「襄王十六、立晉文公、二十一年、以諸侯朝」，展現古代漢語精練優雅之語法結構。\\n【思想與篇章】本篇體現了修德立身、順應天道與治國安民的深遠哲理，具有極高的學術考證與思想啟發價值。"}},{"id":"guo-yu_ch-2_p-1","chapterId":"guo-yu_ch-2","order":1,"canonicalText":"襄王十三年，鄭人伐滑。王使遊孫伯請滑，鄭人執之。王怒，將以狄伐鄭。富辰諫曰：「不可。古人有言曰：『兄弟讒鬩、侮人百里。』周文公之詩曰：『兄弟鬩於墻，外禦其侮。』若是則鬩乃內侮，而雖鬩不敗親也。鄭在天子，兄弟也。鄭武、莊有大勛力於平、桓；我周之東遷，晉、鄭是依；子頹之亂，又鄭之繇定。今以小忿棄之，是以小怨置大德也，無乃不可乎！且夫兄弟之怨，不徵於他，徵於他，利乃外矣。章怨外利，不義；棄親即狄，不祥；以怨報德，不仁。夫義所以生利也，祥所以事神也，仁所以保民也。不義則利不阜，不祥則福不降，不仁則民不至。古之明王不失此三德者，故能光有天下，而和寧百姓，令聞不忘。王其不可以棄之。」王不聽。十七年，王降狄師以伐鄭。","sentenceIds":["guo-yu_ch-2_p-1_s-1","guo-yu_ch-2_p-1_s-2","guo-yu_ch-2_p-1_s-3","guo-yu_ch-2_p-1_s-4","guo-yu_ch-2_p-1_s-5","guo-yu_ch-2_p-1_s-6","guo-yu_ch-2_p-1_s-7","guo-yu_ch-2_p-1_s-8","guo-yu_ch-2_p-1_s-9","guo-yu_ch-2_p-1_s-10","guo-yu_ch-2_p-1_s-11","guo-yu_ch-2_p-1_s-12","guo-yu_ch-2_p-1_s-13","guo-yu_ch-2_p-1_s-14","guo-yu_ch-2_p-1_s-15","guo-yu_ch-2_p-1_s-16","guo-yu_ch-2_p-1_s-17","guo-yu_ch-2_p-1_s-18","guo-yu_ch-2_p-1_s-19","guo-yu_ch-2_p-1_s-20","guo-yu_ch-2_p-1_s-21","guo-yu_ch-2_p-1_s-22"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guo-yu/zh"}],"readingAid":{"translation":"襄王十三年，鄭人伐滑；王使遊孫伯請滑，鄭人執之；王怒，將以狄伐鄭；富辰諫說：不可；古人有言說：兄弟讒鬩、侮人百里；周文公之詩說：兄弟鬩於墻，外禦其侮；若是則鬩乃內侮，而雖鬩不敗親也；鄭在天子，兄弟也。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】針對王國的現象，這段文獻「厲王虐，國人謗王。召公告...」提供了深刻的視角。其背後的歷史情境，凸顯了各方勢力對於國家治理的多元思考。\\n【詞義與名物】在此，我們必須特別注意「人謗」與「厲虐」的時代含義。這些字眼不僅僅是字面上的意思，更包含了傳統禮法與社會結構的深層內涵。\\n【史家寄託】透過對王國的描寫，作者寄寓了深沉的歷史反思。這段敘述不僅是客觀紀錄，更隱含了對國家興亡與人事變遷的警世意味。"}},{"id":"guo-yu_ch-2_p-2","chapterId":"guo-yu_ch-2","order":2,"canonicalText":"王德狄人，將以其女為後。富辰諫曰：「不可。夫婚姻，禍福之階也。由之利內則福，利外則取禍。今王外利矣，其無乃階禍乎？昔摯、疇之國也由大任，杞、繒由大姒，齊、許、申、呂由大姜，陳由大姬，是皆能內利親親者也。昔鄢之亡也由仲任，密須由伯姞，鄶由叔妘，聃由鄭姬，息由陳媯，鄧由楚曼，羅由季姬，盧由荊媯，是皆外利離親者也。」","sentenceIds":["guo-yu_ch-2_p-2_s-1","guo-yu_ch-2_p-2_s-2","guo-yu_ch-2_p-2_s-3","guo-yu_ch-2_p-2_s-4","guo-yu_ch-2_p-2_s-5","guo-yu_ch-2_p-2_s-6","guo-yu_ch-2_p-2_s-7","guo-yu_ch-2_p-2_s-8"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guo-yu/zh"}],"readingAid":{"translation":"王德狄人，將以其女為後；富辰諫說：不可；夫婚姻，禍福之階也；由之利內則福，利外則取禍；今王外利矣，其無乃階禍乎；昔摯、疇之國也由大任，杞、繒由大姒，齊、許、申、呂由大姜，陳由大姬，是皆能內利親親者也；昔鄢之亡也由仲任，密須由伯姞，鄶由叔妘，聃由鄭姬，息由陳媯，鄧由楚曼，羅由季姬，盧由荊媯，是皆外利離親者也。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《國語・晉語六》。記載周厲王實施專制暴政、嚴刑監控國人言論，導致朝野恐懼、人心離散的歷史教訓。\\n【詞義與名物】「道路以目」：形容高壓暴政下百姓不敢言說、只能以眼神傳達憤怒與無奈。\\n【思想與篇章】本段作為政治批判典範，揭露了防民之口與集權鎮壓對國家秩序的毀滅性破壞。"}},{"id":"guo-yu_ch-2_p-3","chapterId":"guo-yu_ch-2","order":3,"canonicalText":"王曰：「利何如而內，何如而外？」對曰：「尊貴、明賢、庸勛、長老、愛親、禮新、親舊。然則民莫不審固其心力以役上令，官不易方，而財不匱竭，求無不至，動無不濟。百姓兆民，夫人奉利而歸諸上，是利之內也，若七德離判，民乃攜貳，各以利退，上求不暨，是其外利也。夫狄無列於王室，鄭伯南也，王而卑之，是不尊貴也。狄，豺狼之德也，鄭未失周典，王而蔑之，是不明賢也。平、桓、莊、惠皆受鄭勞，王而棄之，是不庸勛也。鄭伯捷之齒長矣，王而弱之，是不長老也。狄，隗姓也，鄭出自宣王，王而虐之，是不愛親也。夫禮，新不間舊，王以狄女間姜、任，非禮且棄舊也。王一舉而棄七德，臣故曰利外矣。《》有之曰：『必有忍也，若能有濟也。』王不忍小忿而棄鄭，又登叔隗以階狄。狄，封豕豺狼也，不可厭也。」王不聽。","sentenceIds":["guo-yu_ch-2_p-3_s-1","guo-yu_ch-2_p-3_s-2","guo-yu_ch-2_p-3_s-3","guo-yu_ch-2_p-3_s-4","guo-yu_ch-2_p-3_s-5","guo-yu_ch-2_p-3_s-6","guo-yu_ch-2_p-3_s-7","guo-yu_ch-2_p-3_s-8","guo-yu_ch-2_p-3_s-9","guo-yu_ch-2_p-3_s-10","guo-yu_ch-2_p-3_s-11","guo-yu_ch-2_p-3_s-12","guo-yu_ch-2_p-3_s-13","guo-yu_ch-2_p-3_s-14","guo-yu_ch-2_p-3_s-15"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guo-yu/zh"}],"readingAid":{"translation":"王說：利何如而內，何如而外；回答說：尊貴、明賢、庸勛、長老、愛親、禮新、親舊；然則民莫不審固其心力以役上令，官不易方，而財不匱竭，求無不至，動無不濟；百姓兆民，夫人奉利而歸諸上，是利之內也，若七德離判，民乃攜貳，各以利退，上求不暨，是其外利也；夫狄無列於王室，鄭伯南也，王而卑之，是不尊貴也；狄，豺狼之德也，鄭未失周典，王而蔑之，是不明賢也；平、桓、莊、惠皆受鄭勞，王而棄之，是不庸勛也；鄭伯捷之齒長矣，王而弱之，是不長老也。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《國語》〈周語中〉，記錄先秦秦漢經典思想與歷史實踐之精華。\\n【詞義與名物】文中包含關鍵詞彙如：「王曰、利何如而、何如而外、對曰」，展現古代漢語精練優雅之語法結構。\\n【思想與篇章】本篇體現了修德立身、順應天道與治國安民的深遠哲理，具有極高的學術考證與思想啟發價值。"}},{"id":"guo-yu_ch-2_p-4","chapterId":"guo-yu_ch-2","order":4,"canonicalText":"十八年，王黜狄後。狄人來誅殺譚伯。富辰曰：「昔吾驟諫王，王弗從，以及此難。若我不出，王其以我為懟乎！」乃以其屬死之。","sentenceIds":["guo-yu_ch-2_p-4_s-1","guo-yu_ch-2_p-4_s-2","guo-yu_ch-2_p-4_s-3","guo-yu_ch-2_p-4_s-4","guo-yu_ch-2_p-4_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guo-yu/zh"}],"readingAid":{"translation":"十八年，王黜狄後；狄人來誅殺譚伯；富辰說：昔吾驟諫王，王弗從，以及此難；若我不出，王其以我為懟乎；乃以其屬死之。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《國語》〈周語中〉，屬於典籍核心篇章，記錄古代思想家之智慧結晶。\\n【詞義與名物】文中字句對仗工整，包含「十八年，王黜」等關鍵文言名物與語法結構。\\n【思想與篇章】本段旨在闡述立身處世、修德行道與治國理政之根本哲理，具備深刻的思想啟發價值。"}},{"id":"guo-yu_ch-2_p-5","chapterId":"guo-yu_ch-2","order":5,"canonicalText":"初，惠後欲立王子帶，故以其黨啟狄人。狄人遂入，周王乃出居於鄭，晉文公納之。","sentenceIds":["guo-yu_ch-2_p-5_s-1","guo-yu_ch-2_p-5_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guo-yu/zh"}],"readingAid":{"translation":"初，惠後欲立王子帶，故以其黨啟狄人；狄人遂入，周王乃出居於鄭，晉文公納之。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《國語》〈周語中〉，記錄先秦秦漢經典思想與歷史實踐之精華。\\n【詞義與名物】文中包含關鍵詞彙如：「惠後欲立、王子帶、故以其黨、啟狄人」，展現古代漢語精練優雅之語法結構。\\n【思想與篇章】本篇體現了修德立身、順應天道與治國安民的深遠哲理，具有極高的學術考證與思想啟發價值。"}},{"id":"guo-yu_ch-2_p-6","chapterId":"guo-yu_ch-2","order":6,"canonicalText":"晉文公既定襄王於郟，王勞之以地，辭，請隧焉。王不許，曰：「昔我先王之有天下也，規方千里以為甸服，以供上帝山川百神之祀，以備百姓兆民之用，以待不庭不虞之患。其餘以均分公侯伯子男，使各有寧宇，以順及天地，無逢其災害，先王豈有賴焉。內官不過九御，外官不過九品，足以供給神祇而已，豈敢厭縱其耳目心腹以亂百度？亦唯是死生之服物採章，以臨長百姓而輕重布之，王何異之有？今天降禍災於周室，餘一人僅亦守府，又不佞以勤叔父，而班先王之大物以賞私德，其叔父實應且憎，以非餘一人，餘一人豈敢有愛？先民有言曰：『改玉改行。』叔父若能光裕大德，更姓改物，以創制天下，自顯庸也，而縮取備物以鎮撫百姓，餘一人其流闢旅於裔土，何辭之有與？若由是姬姓也，尚將列為公侯，以復先王之職，大物其未可改也。叔父其懋昭明德，物將自至，餘何敢以私勞變前之大章，以忝天下，其若先王與百姓何？何政令之為也？若不然，叔父有地而隧焉，餘安能知之？」文公遂不敢請，受地而還。","sentenceIds":["guo-yu_ch-2_p-6_s-1","guo-yu_ch-2_p-6_s-2","guo-yu_ch-2_p-6_s-3","guo-yu_ch-2_p-6_s-4","guo-yu_ch-2_p-6_s-5","guo-yu_ch-2_p-6_s-6","guo-yu_ch-2_p-6_s-7","guo-yu_ch-2_p-6_s-8","guo-yu_ch-2_p-6_s-9","guo-yu_ch-2_p-6_s-10","guo-yu_ch-2_p-6_s-11","guo-yu_ch-2_p-6_s-12","guo-yu_ch-2_p-6_s-13"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guo-yu/zh"}],"readingAid":{"translation":"晉文公既定襄王於郟，王勞之以地，辭，請隧焉；王不許，說：昔我先王之有天下也，規方千里以為甸服，以供上帝山川百神之祀，以備百姓兆民之用，以待不庭不虞之患；其餘以均分公侯伯子男，使各有寧宇，以順及天地，無逢其災害，先王豈有賴焉；內官不過九御，外官不過九品，足以供給神祇而已，豈敢厭縱其耳目心腹以亂百度；亦唯是死生之服物採章，以臨長百姓而輕重布之，王何異之有；今天降禍災於周室，餘一人僅亦守府，又不佞以勤叔父，而班先王之大物以賞私德，其叔父實應且憎，以非餘一人，餘一人豈敢有愛；先民有言說：改玉改行；叔父若能光裕大德，更姓改物，以創制天下，自顯庸也，而縮取備物以鎮撫百姓，餘一人其流闢旅於裔土，何辭之有與。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《國語》〈周語中〉，記錄先秦秦漢經典思想與歷史實踐之精華。\\n【詞義與名物】文中包含關鍵詞彙如：「晉文公既、定襄王於、王勞之以、請隧焉」，展現古代漢語精練優雅之語法結構。\\n【思想與篇章】本篇體現了修德立身、順應天道與治國安民的深遠哲理，具有極高的學術考證與思想啟發價值。"}},{"id":"guo-yu_ch-2_p-7","chapterId":"guo-yu_ch-2","order":7,"canonicalText":"王至自鄭，以陽樊賜晉文公。陽人不服，晉侯圍之。倉葛呼曰：「王以晉君為能德，故勞之以陽樊，陽樊懷我王德，是以未從於晉。謂君其何德之布以懷柔之，使無有遠志？今將大泯其宗祊，而蔑殺其民人，宜吾不敢服也！夫三軍之所尋，將蠻、夷、戎、狄之驕逸不虔，於是乎致武。此羸者陽也，未狎君政，故未承命。君若惠及之，唯官是徵，其敢逆命，何足以辱師！君之武震，無乃玩而頓乎？臣聞之曰：『武不可覿，文不可匿。覿武無烈，匿文不昭。』陽不承獲甸，而祗以覿武，臣是以懼。不然，其敢自愛也？且夫陽，豈有裔民哉？夫亦皆天子之父兄甥舅也，若之何其虐之也？」晉侯聞之，曰：「是君子之言也。」乃出陽民。","sentenceIds":["guo-yu_ch-2_p-7_s-1","guo-yu_ch-2_p-7_s-2","guo-yu_ch-2_p-7_s-3","guo-yu_ch-2_p-7_s-4","guo-yu_ch-2_p-7_s-5","guo-yu_ch-2_p-7_s-6","guo-yu_ch-2_p-7_s-7","guo-yu_ch-2_p-7_s-8","guo-yu_ch-2_p-7_s-9","guo-yu_ch-2_p-7_s-10","guo-yu_ch-2_p-7_s-11","guo-yu_ch-2_p-7_s-12","guo-yu_ch-2_p-7_s-13","guo-yu_ch-2_p-7_s-14","guo-yu_ch-2_p-7_s-15","guo-yu_ch-2_p-7_s-16","guo-yu_ch-2_p-7_s-17"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guo-yu/zh"}],"readingAid":{"translation":"王至自鄭，以陽樊賜晉文公；陽人不服，晉侯圍之；倉葛呼說：王以晉君為能德，故勞之以陽樊，陽樊懷我王德，是以未從於晉；謂君其何德之布以懷柔之，使無有遠志；今將大泯其宗祊，而蔑殺其民人，宜吾不敢服也；夫三軍之所尋，將蠻、夷、戎、狄之驕逸不虔，於是乎致武；此羸者陽也，未狎君政，故未承命；君若惠及之，唯官是徵，其敢逆命，何足以辱師。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《國語》〈周語中〉，記錄先秦秦漢經典思想與歷史實踐之精華。\\n【詞義與名物】文中包含關鍵詞彙如：「王至自鄭、以陽樊賜、晉文公、陽人不服」，展現古代漢語精練優雅之語法結構。\\n【思想與篇章】本篇體現了修德立身、順應天道與治國安民的深遠哲理，具有極高的學術考證與思想啟發價值。"}},{"id":"guo-yu_ch-2_p-8","chapterId":"guo-yu_ch-2","order":8,"canonicalText":"溫之會，晉人執衛成公歸之於周。晉侯請殺之，王曰：「不可。夫政自上下者也，上作政，而下行之不逆，故上下無怨。今叔父作政而不行，無乃不可乎？夫君臣無獄，今元咺雖直，不可聽也。君臣皆獄，父子將獄，是無上下也。而叔父聽之，一逆矣。又為臣殺其君，其安庸刑？布刑而不庸，再逆矣。一合諸侯，而有再逆政，餘懼其無後。不然，餘何私於衛侯？」晉人乃歸衛侯。","sentenceIds":["guo-yu_ch-2_p-8_s-1","guo-yu_ch-2_p-8_s-2","guo-yu_ch-2_p-8_s-3","guo-yu_ch-2_p-8_s-4","guo-yu_ch-2_p-8_s-5","guo-yu_ch-2_p-8_s-6","guo-yu_ch-2_p-8_s-7","guo-yu_ch-2_p-8_s-8","guo-yu_ch-2_p-8_s-9","guo-yu_ch-2_p-8_s-10","guo-yu_ch-2_p-8_s-11","guo-yu_ch-2_p-8_s-12"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guo-yu/zh"}],"readingAid":{"translation":"溫之會，晉人執衛成公歸之於周；晉侯請殺之，王說：不可；夫政自上下者也，上作政，而下行之不逆，故上下無怨；今叔父作政而不行，無乃不可乎；夫君臣無獄，今元咺雖直，不可聽也；君臣皆獄，父子將獄，是無上下也；而叔父聽之，一逆矣；又為臣殺其君，其安庸刑。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《國語》〈周語中〉，屬於典籍核心篇章，記錄古代思想家之智慧結晶。\\n【詞義與名物】文中字句對仗工整，包含「溫之會，晉人」等關鍵文言名物與語法結構。\\n【思想與篇章】本段旨在闡述立身處世、修德行道與治國理政之根本哲理，具備深刻的思想啟發價值。"}},{"id":"guo-yu_ch-2_p-9","chapterId":"guo-yu_ch-2","order":9,"canonicalText":"二十四年，秦師將襲鄭，過周北門。左右皆免冑而下拜，超乘者三百乘。王孫滿觀之，言於王曰：「秦師必有謫。」王曰：「何故？」對曰：「師輕而驕，輕則寡謀，驕則無禮。無禮則脫，寡謀自陷。入險而脫，能無敗乎？秦師無謫，是道廢也。」是行也，秦師還，晉人敗諸崤，獲其三帥丙、術、視。","sentenceIds":["guo-yu_ch-2_p-9_s-1","guo-yu_ch-2_p-9_s-2","guo-yu_ch-2_p-9_s-3","guo-yu_ch-2_p-9_s-4","guo-yu_ch-2_p-9_s-5","guo-yu_ch-2_p-9_s-6","guo-yu_ch-2_p-9_s-7","guo-yu_ch-2_p-9_s-8","guo-yu_ch-2_p-9_s-9"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guo-yu/zh"}],"readingAid":{"translation":"二十四年，秦師將襲鄭，過周北門；左右皆免冑而下拜，超乘者三百乘；王孫滿觀之，言於王說：秦師必有謫；王說：何故；回答說：師輕而驕，輕則寡謀，驕則無禮；無禮則脫，寡謀自陷；入險而脫，能無敗乎；秦師無謫，是道廢也。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《國語》〈周語中〉，記錄先秦秦漢經典思想與歷史實踐之精華。\\n【詞義與名物】文中包含關鍵詞彙如：「二十四年、秦師將襲、過周北門、左右皆免」，展現古代漢語精練優雅之語法結構。\\n【思想與篇章】本篇體現了修德立身、順應天道與治國安民的深遠哲理，具有極高的學術考證與思想啟發價值。"}},{"id":"guo-yu_ch-2_p-10","chapterId":"guo-yu_ch-2","order":10,"canonicalText":"晉侯使隨會聘於周，定王享之餚烝，原公相禮。範子私於原公，曰：「吾聞王室之禮無毀折，今此何禮也？」王見其語，召原公而問之，原公以告。","sentenceIds":["guo-yu_ch-2_p-10_s-1","guo-yu_ch-2_p-10_s-2","guo-yu_ch-2_p-10_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guo-yu/zh"}],"readingAid":{"translation":"晉侯使隨會聘於周，定王享之餚烝，原公相禮；範子私於原公，說：吾聞王室之禮無毀折，今此何禮也；王見其語，召原公而問之，原公以告。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【題解與背景】\\n本段選自《國語》〈周語中〉，為該經典著作之精華章節，呈現先秦兩漢時期深刻的思想觀點與歷史實踐。\\n【詞義與名物】\\n文中經典語句「晉侯使隨會聘於周，定王享之餚烝，原公……」詞意凝練，包含古漢語重要名詞概念與語法句式。\\n【思想與史事脈絡】\\n全段旨在大致闡發道德修養、因時制宜與實踐致用之根本原則，對後世國學研究具備極高的參考價值。"}},{"id":"guo-yu_ch-2_p-11","chapterId":"guo-yu_ch-2","order":11,"canonicalText":"王召士季，曰：「子弗聞乎，禘郊之事，則有全烝；王公立飫，則有房烝；親戚宴饗，則有餚烝。今女非他也，而叔父使士季實來修舊德，以獎王室。唯是先王之宴禮，欲以貽女。餘一人敢設飫禘焉，忠非親禮，而幹舊職，以亂前好？且唯戎、狄則有體薦。夫戎、狄，冒沒輕儳，貪而不讓。其血氣不治，若禽獸焉。其適來班貢，不俟馨香嘉味，故坐諸門外，而使舌人體委與之。女今我王室之一二兄弟，以時相見，將和協典禮，以示民訓則，無亦擇其柔嘉，選其馨香，潔其酒醴，品其百籩，修其簠簋，奉其犧象，出其樽彝，陳其鼎俎，凈其巾羃，敬其祓除，體解節折而共飲食之。於是乎有折俎加豆，酬幣宴貨，以示容合好，胡有孑然其郊戎、狄也？","sentenceIds":["guo-yu_ch-2_p-11_s-1","guo-yu_ch-2_p-11_s-2","guo-yu_ch-2_p-11_s-3","guo-yu_ch-2_p-11_s-4","guo-yu_ch-2_p-11_s-5","guo-yu_ch-2_p-11_s-6","guo-yu_ch-2_p-11_s-7","guo-yu_ch-2_p-11_s-8","guo-yu_ch-2_p-11_s-9","guo-yu_ch-2_p-11_s-10","guo-yu_ch-2_p-11_s-11","guo-yu_ch-2_p-11_s-12"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guo-yu/zh"}],"readingAid":{"translation":"王召士季，說：子弗聞乎，禘郊之事，則有全烝；王公立飫，則有房烝；親戚宴饗，則有餚烝；今女非他也，而叔父使士季實來修舊德，以獎王室；唯是先王之宴禮，欲以貽女；餘一人敢設飫禘焉，忠非親禮，而幹舊職，以亂前好；且唯戎、狄則有體薦；夫戎、狄，冒沒輕儳，貪而不讓；其血氣不治，若禽獸焉；其適來班貢，不俟馨香嘉味，故坐諸門外，而使舌人體委與之。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《國語》〈周語中〉，記錄先秦秦漢經典思想與歷史實踐之精華。\\n【詞義與名物】文中包含關鍵詞彙如：「王召士季、子弗聞乎、禘郊之事、則有全烝」，展現古代漢語精練優雅之語法結構。\\n【思想與篇章】本篇體現了修德立身、順應天道與治國安民的深遠哲理，具有極高的學術考證與思想啟發價值。"}},{"id":"guo-yu_ch-2_p-12","chapterId":"guo-yu_ch-2","order":12,"canonicalText":"「夫王公諸侯之有飫也，將以講事成章，建大德、昭大物也，故立成禮烝而已。飫以顯物，宴以合好，故歲飫不倦，時宴不淫，月會、旬修，日完不忘。服物昭庸，採飾顯明，文章比象，周旋序順，容貌有崇，威儀有則，五味實氣，五色精心，五聲昭德，五義紀宜，飲食可饗，和同可觀，財用可嘉，則順而德建。古之善禮者，將焉用全烝？」","sentenceIds":["guo-yu_ch-2_p-12_s-1","guo-yu_ch-2_p-12_s-2","guo-yu_ch-2_p-12_s-3","guo-yu_ch-2_p-12_s-4","guo-yu_ch-2_p-12_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guo-yu/zh"}],"readingAid":{"translation":"夫王公諸侯之有飫也，將以講事成章，建大德、昭大物也，故立成禮烝而已；飫以顯物，宴以合好，故歲飫不倦，時宴不淫，月會、旬修，日完不忘；服物昭庸，採飾顯明，文章比象，周旋序順，容貌有崇，威儀有則，五味實氣，五色精心，五聲昭德，五義紀宜，飲食可饗，和同可觀，財用可嘉，則順而德建；古之善禮者，將焉用全烝。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【題解與背景】\\n本段選自《國語》〈周語中〉，為該經典著作之精華章節，呈現先秦兩漢時期深刻的思想觀點與歷史實踐。\\n【詞義與名物】\\n文中經典語句「「夫王公諸侯之有飫也，將以講事成章，……」詞意凝練，包含古漢語重要名詞概念與語法句式。\\n【思想與史事脈絡】\\n全段旨在大致闡發道德修養、因時制宜與實踐致用之根本原則，對後世國學研究具備極高的參考價值。"}},{"id":"guo-yu_ch-2_p-13","chapterId":"guo-yu_ch-2","order":13,"canonicalText":"武子遂不敢對而退。歸乃講聚三代之典禮，於是乎修執秩以為晉法。","sentenceIds":["guo-yu_ch-2_p-13_s-1","guo-yu_ch-2_p-13_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guo-yu/zh"}],"readingAid":{"translation":"武子遂不敢對而退；歸乃講聚三代之典禮，於是乎修執秩以為晉法。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《國語》〈周語中〉，屬於典籍核心篇章，記錄古代思想家之智慧結晶。\\n【詞義與名物】文中字句對仗工整，包含「武子遂不敢對」等關鍵文言名物與語法結構。\\n【思想與篇章】本段旨在闡述立身處世、修德行道與治國理政之根本哲理，具備深刻的思想啟發價值。"}},{"id":"guo-yu_ch-2_p-14","chapterId":"guo-yu_ch-2","order":14,"canonicalText":"定王使單襄公聘於宋。遂假道於陳，以聘於楚。火朝覿矣，道茀不可行，候不在疆，司空不視途，澤不陂，川不梁，野有庾積，場功未畢，道無列樹，墾田若蓺，膳宰不致餼，司裏不授館，國無寄寓，縣無施捨，民將築臺於夏氏。及陳，陳靈公與孔寧、儀行父南冠以如夏氏，留賓不見。","sentenceIds":["guo-yu_ch-2_p-14_s-1","guo-yu_ch-2_p-14_s-2","guo-yu_ch-2_p-14_s-3","guo-yu_ch-2_p-14_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guo-yu/zh"}],"readingAid":{"translation":"定王使單襄公聘於宋；遂假道於陳，以聘於楚；火朝覿矣，道茀不可行，候不在疆，司空不視途，澤不陂，川不梁，野有庾積，場功未畢，道無列樹，墾田若蓺，膳宰不致餼，司裡不授館，國無寄寓，縣無施捨，民將築臺於夏氏；及陳，陳靈公與孔寧、儀行父南冠以如夏氏，留賓不見。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《國語》〈周語中〉，記錄先秦秦漢經典思想與歷史實踐之精華。\\n【詞義與名物】文中包含關鍵詞彙如：「定王使單、襄公聘於、遂假道於、以聘於楚」，展現古代漢語精練優雅之語法結構。\\n【思想與篇章】本篇體現了修德立身、順應天道與治國安民的深遠哲理，具有極高的學術考證與思想啟發價值。"}},{"id":"guo-yu_ch-2_p-15","chapterId":"guo-yu_ch-2","order":15,"canonicalText":"單子歸，告王曰：「陳侯不有大咎，國必亡。」王曰：「何故？」對曰：「夫辰角見而雨畢，天根見而水涸，本見而草木節解，駟見而隕霜，火見而清風戒寒。故先王之教曰：『雨畢而除道，水涸而成梁，草木節解而備藏，隕霜而冬裘具，清風至而修城郭宮室。』故《夏令》曰：『九月除道，十月成梁。』其時儆曰：「收而場功，待而畚梮，營室之中，土功其始，火之初見，期於司裏。『此先王所以不用財賄，而廣施德於天下者也。今陳國火朝覿矣，而道路若塞，野場若棄，澤不陂障，川無舟梁，是廢先王之教也。」","sentenceIds":["guo-yu_ch-2_p-15_s-1","guo-yu_ch-2_p-15_s-2","guo-yu_ch-2_p-15_s-3","guo-yu_ch-2_p-15_s-4","guo-yu_ch-2_p-15_s-5","guo-yu_ch-2_p-15_s-6","guo-yu_ch-2_p-15_s-7","guo-yu_ch-2_p-15_s-8","guo-yu_ch-2_p-15_s-9"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guo-yu/zh"}],"readingAid":{"translation":"單子歸，告王說：陳侯不有大咎，國必亡；王說：何故；回答說：夫辰角見而雨畢，天根見而水涸，本見而草木節解，駟見而隕霜，火見而清風戒寒；故先王之教說：雨畢而除道，水涸而成梁，草木節解而備藏，隕霜而冬裘具，清風至而修城郭宮室；故《夏令》說：九月除道，十月成梁；其時儆說：收而場功，待而畚梮，營室之中，土功其始，火之初見，期於司裡；此先王所以不用財賄，而廣施德於天下者也；今陳國火朝覿矣，而道路若塞，野場若棄，澤不陂障，川無舟梁，是廢先王之教也。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《國語》〈周語中〉，記錄先秦秦漢經典思想與歷史實踐之精華。\\n【詞義與名物】文中包含關鍵詞彙如：「單子歸、告王曰、陳侯不有、大咎」，展現古代漢語精練優雅之語法結構。\\n【思想與篇章】本篇體現了修德立身、順應天道與治國安民的深遠哲理，具有極高的學術考證與思想啟發價值。"}},{"id":"guo-yu_ch-2_p-16","chapterId":"guo-yu_ch-2","order":16,"canonicalText":"「《周制》有之曰：『列樹以表道，立鄙食以守路，國有郊牧，疆有寓望，藪有圃草，囿有林池，所以御災也。其餘無非穀土，民無懸耜，野無奧草。不奪民時，不蔑民功。有優無匱，有逸無罷。國有班事，縣有序民。』今陳國道路不可知，田在草間，功成而不收，民罷於逸樂，是棄先王之法制也。","sentenceIds":["guo-yu_ch-2_p-16_s-1","guo-yu_ch-2_p-16_s-2","guo-yu_ch-2_p-16_s-3","guo-yu_ch-2_p-16_s-4","guo-yu_ch-2_p-16_s-5","guo-yu_ch-2_p-16_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guo-yu/zh"}],"readingAid":{"translation":"《周制》有之說：列樹以表道，立鄙食以守路，國有郊牧，疆有寓望，藪有圃草，囿有林池，所以御災也；其餘無非穀土，民無懸耜，野無奧草；不奪民時，不蔑民功；有優無匱，有逸無罷；國有班事，縣有序民；今陳國道路不可知，田在草間，功成而不收，民罷於逸樂，是棄先王之法制也。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《國語》〈周語中〉，記錄先秦秦漢經典思想與歷史實踐之精華。\\n【詞義與名物】文中包含關鍵詞彙如：「周制、有之曰、列樹以表、立鄙食以」，展現古代漢語精練優雅之語法結構。\\n【思想與篇章】本篇體現了修德立身、順應天道與治國安民的深遠哲理，具有極高的學術考證與思想啟發價值。"}},{"id":"guo-yu_ch-2_p-17","chapterId":"guo-yu_ch-2","order":17,"canonicalText":"「周之《秩官》有之曰：『敵國賓至，關尹以告，行理以節逆之，候人為導，卿出郊勞，門尹除門，宗祝執祀，司裏授館，司徒具徒，司空視途，司寇詰奸，虞人入材，甸人積薪，火師監燎，水師監濯，膳宰致饔，廩人獻餼，司馬陳芻，工人展車，百官以物至，賓入如歸。是故小大莫不懷愛。其貴國之賓至，則以班加一等，益虔。至於王吏，則皆官正蒞事，上卿監之。若王巡守，則君親監之。』今雖朝也不才，有分族於周，承王命以為過賓於陳，而司事莫至，是蔑先王之官也。","sentenceIds":["guo-yu_ch-2_p-17_s-1","guo-yu_ch-2_p-17_s-2","guo-yu_ch-2_p-17_s-3","guo-yu_ch-2_p-17_s-4","guo-yu_ch-2_p-17_s-5","guo-yu_ch-2_p-17_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guo-yu/zh"}],"readingAid":{"translation":"周之《秩官》有之說：敵國賓至，關尹以告，行理以節逆之，候人為導，卿出郊勞，門尹除門，宗祝執祀，司裡授館，司徒具徒，司空視途，司寇詰奸，虞人入材，甸人積薪，火師監燎，水師監濯，膳宰致饔，廩人獻餼，司馬陳芻，工人展車，百官以物至，賓入如歸；是故小大莫不懷愛；其貴國之賓至，則以班加一等，益虔；至於王吏，則皆官正蒞事，上卿監之；若王巡守，則君親監之；今雖朝也不才，有分族於周，承王命以為過賓於陳，而司事莫至，是蔑先王之官也。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《國語》〈周語中〉，記錄先秦秦漢經典思想與歷史實踐之精華。\\n【詞義與名物】文中包含關鍵詞彙如：「周之、秩官、有之曰、敵國賓至」，展現古代漢語精練優雅之語法結構。\\n【思想與篇章】本篇體現了修德立身、順應天道與治國安民的深遠哲理，具有極高的學術考證與思想啟發價值。"}},{"id":"guo-yu_ch-2_p-18","chapterId":"guo-yu_ch-2","order":18,"canonicalText":"「先王之令有之曰：『天道賞善而罰淫，故凡我造國，無從非彝，無即慆淫，各守爾典，以承天休。』今陳侯不念胤續之常，棄其伉儷妃嬪，而帥其卿佐以淫於夏氏，不亦嬻姓矣乎？陳，我大姬之後也。棄袞冕而南冠以出，不亦簡彝乎？是又犯先王之令也。］","sentenceIds":["guo-yu_ch-2_p-18_s-1","guo-yu_ch-2_p-18_s-2","guo-yu_ch-2_p-18_s-3","guo-yu_ch-2_p-18_s-4","guo-yu_ch-2_p-18_s-5","guo-yu_ch-2_p-18_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guo-yu/zh"}],"readingAid":{"translation":"先王之令有之說：天道賞善而罰淫，故凡我造國，無從非彝，無即慆淫，各守爾典，以承天休；今陳侯不念胤續之常，棄其伉儷妃嬪，而帥其卿佐以淫於夏氏，不亦嬻姓矣乎；陳，我大姬之後也；棄袞冕而南冠以出，不亦簡彝乎；是又犯先王之令也；］。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【題解與背景】\\n本段選自《國語》〈周語中〉，為該經典著作之精華章節，呈現先秦兩漢時期深刻的思想觀點與歷史實踐。\\n【詞義與名物】\\n文中經典語句「「先王之令有之曰：『天道賞善而罰淫，……」詞意凝練，包含古漢語重要名詞概念與語法句式。\\n【思想與史事脈絡】\\n全段旨在大致闡發道德修養、因時制宜與實踐致用之根本原則，對後世國學研究具備極高的參考價值。"}},{"id":"guo-yu_ch-2_p-19","chapterId":"guo-yu_ch-2","order":19,"canonicalText":"「昔先王之教，懋帥其德也，猶恐殞越。若廢其教而棄其制，蔑其官而犯其令，將何以守國？居大國之間，而無此四者，其能久乎？」","sentenceIds":["guo-yu_ch-2_p-19_s-1","guo-yu_ch-2_p-19_s-2","guo-yu_ch-2_p-19_s-3","guo-yu_ch-2_p-19_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guo-yu/zh"}],"readingAid":{"translation":"昔先王之教，懋帥其德也，猶恐殞越；若廢其教而棄其制，蔑其官而犯其令，將憑藉什麼守國；居大國之間，而無此四者，其能久乎。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《國語》〈周語中〉，屬於典籍核心篇章，記錄古代思想家之智慧結晶。\\n【詞義與名物】文中字句對仗工整，包含「「昔先王之教」等關鍵文言名物與語法結構。\\n【思想與篇章】本段旨在闡述立身處世、修德行道與治國理政之根本哲理，具備深刻的思想啟發價值。"}},{"id":"guo-yu_ch-2_p-20","chapterId":"guo-yu_ch-2","order":20,"canonicalText":"六年，單子如楚。八年，陳侯殺於夏氏。九年，楚子入陳。","sentenceIds":["guo-yu_ch-2_p-20_s-1","guo-yu_ch-2_p-20_s-2","guo-yu_ch-2_p-20_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guo-yu/zh"}],"readingAid":{"translation":"六年，單子如楚；八年，陳侯殺於夏氏；九年，楚子入陳。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《國語》〈周語中〉，記錄先秦秦漢經典思想與歷史實踐之精華。\\n【詞義與名物】文中包含關鍵詞彙如：「六年、單子如楚、八年、陳侯殺於」，展現古代漢語精練優雅之語法結構。\\n【思想與篇章】本篇體現了修德立身、順應天道與治國安民的深遠哲理，具有極高的學術考證與思想啟發價值。"}},{"id":"guo-yu_ch-2_p-21","chapterId":"guo-yu_ch-2","order":21,"canonicalText":"定王八年，使劉康公聘於魯，發幣於大夫。季文子、孟獻子皆儉，叔孫宣子、東門子家皆侈。","sentenceIds":["guo-yu_ch-2_p-21_s-1","guo-yu_ch-2_p-21_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guo-yu/zh"}],"readingAid":{"translation":"定王八年，使劉康公聘於魯，發幣於大夫；季文子、孟獻子皆儉，叔孫宣子、東門子家皆侈。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【題解與背景】\\n本段選自《國語》〈周語中〉，為該經典著作之精華章節，呈現先秦兩漢時期深刻的思想觀點與歷史實踐。\\n【詞義與名物】\\n文中經典語句「定王八年，使劉康公聘於魯，發幣於大夫……」詞意凝練，包含古漢語重要名詞概念與語法句式。\\n【思想與史事脈絡】\\n全段旨在大致闡發道德修養、因時制宜與實踐致用之根本原則，對後世國學研究具備極高的參考價值。"}},{"id":"guo-yu_ch-2_p-22","chapterId":"guo-yu_ch-2","order":22,"canonicalText":"歸，王問魯大夫孰賢？對曰：「季、孟其長處魯乎！叔孫、東門其亡乎！若家不亡，身必不免。」王曰：「何故？」對曰：「臣聞之：為臣必臣，為君必君，寬肅宣惠，君也；敬恪恭儉，臣也。寬所以保本也，肅所以濟時也，宣所以教施也，惠所以和民也。本有保則必固，時動而濟則無敗功，教施而宣則遍，惠以和民則阜。若本固而功成，施遍而民阜，乃可以長保民矣，其何事不徹？敬所以承命也，恪所以守業也，恭所以給事也，儉所以足用也。以敬承命則不違，以恪守業則不懈，以恭給事則寬於死，以儉足用則遠於憂。若承命不違，守業不懈，寬於死而遠於憂，則可以上下無隙矣，其何任不堪？上任事而徹，下能堪其任，所以為令聞長世也。今夫二子者儉，其能足用矣，用足則族可以庇。二子者侈，侈則不恤匱，匱而不恤，憂必及之，若是則必廣其身。且夫人臣而侈，國家弗堪，亡之道也。」王曰：「幾何？」對曰：「東門之位不若叔孫，而泰侈焉，不可以事二君。叔孫之位不若季、孟，而亦泰侈焉，不可以事三君。若皆蚤世猶可，若登年以載其毒，必亡。」","sentenceIds":["guo-yu_ch-2_p-22_s-1","guo-yu_ch-2_p-22_s-2","guo-yu_ch-2_p-22_s-3","guo-yu_ch-2_p-22_s-4","guo-yu_ch-2_p-22_s-5","guo-yu_ch-2_p-22_s-6","guo-yu_ch-2_p-22_s-7","guo-yu_ch-2_p-22_s-8","guo-yu_ch-2_p-22_s-9","guo-yu_ch-2_p-22_s-10","guo-yu_ch-2_p-22_s-11","guo-yu_ch-2_p-22_s-12","guo-yu_ch-2_p-22_s-13","guo-yu_ch-2_p-22_s-14","guo-yu_ch-2_p-22_s-15","guo-yu_ch-2_p-22_s-16","guo-yu_ch-2_p-22_s-17","guo-yu_ch-2_p-22_s-18","guo-yu_ch-2_p-22_s-19","guo-yu_ch-2_p-22_s-20","guo-yu_ch-2_p-22_s-21","guo-yu_ch-2_p-22_s-22"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guo-yu/zh"}],"readingAid":{"translation":"歸，王問魯大夫孰賢；回答說：季、孟其長處魯乎；叔孫、東門其亡乎；若家不亡，身必不免；王說：何故；回答說：臣聞之：為臣必臣，為君必君，寬肅宣惠，君也；敬恪恭儉，臣也；寬所以保本也，肅所以濟時也，宣所以教施也，惠所以和民也；本有保則必固，時動而濟則無敗功，教施而宣則遍，惠以和民則阜。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《國語》〈周語中〉，記錄先秦秦漢經典思想與歷史實踐之精華。\\n【詞義與名物】文中包含關鍵詞彙如：「王問魯大、夫孰賢、對曰、孟其長處」，展現古代漢語精練優雅之語法結構。\\n【思想與篇章】本篇體現了修德立身、順應天道與治國安民的深遠哲理，具有極高的學術考證與思想啟發價值。"}},{"id":"guo-yu_ch-2_p-23","chapterId":"guo-yu_ch-2","order":23,"canonicalText":"十六年，魯宣公卒。赴者未及，東門氏來告亂，子家奔齊。簡王十一年，魯叔孫宣伯亦奔齊，成公未歿二年。","sentenceIds":["guo-yu_ch-2_p-23_s-1","guo-yu_ch-2_p-23_s-2","guo-yu_ch-2_p-23_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guo-yu/zh"}],"readingAid":{"translation":"十六年，魯宣公去世；赴者未及，東門氏來告亂，子家奔齊；簡王十一年，魯叔孫宣伯亦奔齊，成公未歿二年。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【題解與背景】\\n本段選自《國語》〈周語中〉，為該經典著作之精華章節，呈現先秦兩漢時期深刻的思想觀點與歷史實踐。\\n【詞義與名物】\\n文中經典語句「十六年，魯宣公卒。赴者未及，東門氏來……」詞意凝練，包含古漢語重要名詞概念與語法句式。\\n【思想與史事脈絡】\\n全段旨在大致闡發道德修養、因時制宜與實踐致用之根本原則，對後世國學研究具備極高的參考價值。"}},{"id":"guo-yu_ch-2_p-24","chapterId":"guo-yu_ch-2","order":24,"canonicalText":"簡王八年，魯成公來朝，使叔孫僑如先聘且告。見王孫說，與之語。說言於王曰：「魯叔孫之來也，必有異焉。其享覲之幣薄而言諂，殆請之也，若請之，必欲賜也。魯執政唯強，故不歡焉而後遣之，且其狀方上而銳下，宜觸冒人。王其勿賜。若貪陵之人來而盈其願，是不賞善也，且財不給。故聖人之施捨也議之，其喜怒取與亦議之。是以不主寬惠，亦不主猛毅，主德義而已。」王曰：「諾。」使私問諸魯，請之也。王遂不賜，禮如行人。及魯侯至，仲孫蔑為介，王孫說與之語，說讓。說以語王，王厚賄之。","sentenceIds":["guo-yu_ch-2_p-24_s-1","guo-yu_ch-2_p-24_s-2","guo-yu_ch-2_p-24_s-3","guo-yu_ch-2_p-24_s-4","guo-yu_ch-2_p-24_s-5","guo-yu_ch-2_p-24_s-6","guo-yu_ch-2_p-24_s-7","guo-yu_ch-2_p-24_s-8","guo-yu_ch-2_p-24_s-9","guo-yu_ch-2_p-24_s-10","guo-yu_ch-2_p-24_s-11","guo-yu_ch-2_p-24_s-12","guo-yu_ch-2_p-24_s-13","guo-yu_ch-2_p-24_s-14"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guo-yu/zh"}],"readingAid":{"translation":"簡王八年，魯成公來朝，使叔孫僑如先聘且告；見王孫說，與之語；說言於王說：魯叔孫之來也，必有異焉；其享覲之幣薄而言諂，殆請之也，若請之，必欲賜也；魯執政唯強，故不歡焉而後遣之，且其狀方上而銳下，宜觸冒人；王其勿賜；若貪陵之人來而盈其願，是不賞善也，且財不給；故聖人之施捨也議之，其喜怒取與亦議之。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《國語》〈周語中〉，記錄先秦秦漢經典思想與歷史實踐之精華。\\n【詞義與名物】文中包含關鍵詞彙如：「簡王八年、魯成公來、使叔孫僑、如先聘且」，展現古代漢語精練優雅之語法結構。\\n【思想與篇章】本篇體現了修德立身、順應天道與治國安民的深遠哲理，具有極高的學術考證與思想啟發價值。"}},{"id":"guo-yu_ch-2_p-25","chapterId":"guo-yu_ch-2","order":25,"canonicalText":"晉既克楚於鄢，使郤至告慶於周。未將事，王叔簡公飲之酒，交酬好貨皆厚，飲酒宴語相說也。","sentenceIds":["guo-yu_ch-2_p-25_s-1","guo-yu_ch-2_p-25_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guo-yu/zh"}],"readingAid":{"translation":"晉既克楚於鄢，使郤至告慶於周；未將事，王叔簡公飲之酒，交酬好貨皆厚，飲酒宴語相說也。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【題解與背景】\\n本段選自《國語》〈周語中〉，為該經典著作之精華章節，呈現先秦兩漢時期深刻的思想觀點與歷史實踐。\\n【詞義與名物】\\n文中經典語句「晉既克楚於鄢，使郤至告慶於周。未將事……」詞意凝練，包含古漢語重要名詞概念與語法句式。\\n【思想與史事脈絡】\\n全段旨在大致闡發道德修養、因時制宜與實踐致用之根本原則，對後世國學研究具備極高的參考價值。"}},{"id":"guo-yu_ch-2_p-26","chapterId":"guo-yu_ch-2","order":26,"canonicalText":"明日，王孫子譽諸朝，郤至見邵桓公，與之語。邵公以告單襄公曰：「王叔子譽溫季，以為必相晉國，相晉國，必大得諸侯，勸二三君子必先導焉，可以樹。今夫子見我，以晉國之克也，為己實謀之，曰：『微我，晉不戰矣！楚有五敗，晉不知乘，我則強之。背宋之盟，一也；德薄而以地賂諸侯，二也；棄壯之良而用幼弱，三也；建立卿士而不用其言，四也；夷、鄭從之，三陳而不整，五也。罪不由晉，晉得其民，四軍之帥，旅力方剛；卒伍治整，諸侯與之。是有五勝也：有辭，一也；得民，二也；軍帥強御，三也；行列治整，四也；諸侯輯睦，五也。有一勝猶足用也，有五勝以伐五敗，而避之者，非人也。不可以不戰。欒、範不欲，我則強之。戰而勝，是吾力也。且夫戰也微謀，吾有三伐；勇而有禮，反之以仁。吾三逐楚君之卒，勇也；見其君必下而趨，禮也；能獲鄭伯而赦之，仁也。若是而知晉國之政，楚、越必朝。』","sentenceIds":["guo-yu_ch-2_p-26_s-1","guo-yu_ch-2_p-26_s-2","guo-yu_ch-2_p-26_s-3","guo-yu_ch-2_p-26_s-4","guo-yu_ch-2_p-26_s-5","guo-yu_ch-2_p-26_s-6","guo-yu_ch-2_p-26_s-7","guo-yu_ch-2_p-26_s-8","guo-yu_ch-2_p-26_s-9","guo-yu_ch-2_p-26_s-10","guo-yu_ch-2_p-26_s-11","guo-yu_ch-2_p-26_s-12","guo-yu_ch-2_p-26_s-13","guo-yu_ch-2_p-26_s-14","guo-yu_ch-2_p-26_s-15","guo-yu_ch-2_p-26_s-16","guo-yu_ch-2_p-26_s-17","guo-yu_ch-2_p-26_s-18","guo-yu_ch-2_p-26_s-19","guo-yu_ch-2_p-26_s-20","guo-yu_ch-2_p-26_s-21","guo-yu_ch-2_p-26_s-22","guo-yu_ch-2_p-26_s-23","guo-yu_ch-2_p-26_s-24","guo-yu_ch-2_p-26_s-25","guo-yu_ch-2_p-26_s-26","guo-yu_ch-2_p-26_s-27"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guo-yu/zh"}],"readingAid":{"translation":"明日，王孫子譽諸朝，郤至見邵桓公，與之語；邵公以告單襄公說：王叔子譽溫季，以為必相晉國，相晉國，必大得諸侯，勸二三君子必先導焉，可以樹；今夫子見我，以晉國之克也，為己實謀之，說：微我，晉不戰矣；楚有五敗，晉不知乘，我則強之；背宋之盟，一也；德薄而以地賂諸侯，二也；棄壯之良而用幼弱，三也；建立卿士而不用其言，四也；夷、鄭從之，三陳而不整，五也；罪不由晉，晉得其民，四軍之帥，旅力方剛；去世伍治整，諸侯與之；是有五勝也：有辭，一也；得民，二也；軍帥強御，三也；行列治整，四也；諸侯輯睦，五也；有一勝猶足用也，有五勝以伐五敗，而避之者，非人也。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《國語》〈周語中〉，記錄先秦秦漢經典思想與歷史實踐之精華。\\n【詞義與名物】文中包含關鍵詞彙如：「明日、王孫子譽、諸朝、郤至見邵」，展現古代漢語精練優雅之語法結構。\\n【思想與篇章】本篇體現了修德立身、順應天道與治國安民的深遠哲理，具有極高的學術考證與思想啟發價值。"}},{"id":"guo-yu_ch-2_p-27","chapterId":"guo-yu_ch-2","order":27,"canonicalText":"「吾曰：『子則賢矣。抑晉國之舉也，不失其次，吾懼政之未及子也。』謂我曰：『夫何次之有？昔先大夫荀伯自下軍之佐以政，趙宣子未有軍行而以政，今欒伯自下軍往。是三子也，吾又過於四之無不及。若佐新軍而升為政，不亦可乎？將必求之。』是其言也，君以為奚若？」","sentenceIds":["guo-yu_ch-2_p-27_s-1","guo-yu_ch-2_p-27_s-2","guo-yu_ch-2_p-27_s-3","guo-yu_ch-2_p-27_s-4","guo-yu_ch-2_p-27_s-5","guo-yu_ch-2_p-27_s-6","guo-yu_ch-2_p-27_s-7","guo-yu_ch-2_p-27_s-8","guo-yu_ch-2_p-27_s-9"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guo-yu/zh"}],"readingAid":{"translation":"吾說：子則賢矣；抑晉國之舉也，不失其次，吾懼政之未及子也；謂我說：夫何次之有；昔先大夫荀伯自下軍之佐以政，趙宣子未有軍行而以政，今欒伯自下軍往；是三子也，吾又過於四之無不及；若佐新軍而升為政，不亦可乎；將必求之；是其言也，君以為奚若。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【題解與背景】\\n本段選自《國語》〈周語中〉，為該經典著作之精華章節，呈現先秦兩漢時期深刻的思想觀點與歷史實踐。\\n【詞義與名物】\\n文中經典語句「「吾曰：『子則賢矣。抑晉國之舉也，不……」詞意凝練，包含古漢語重要名詞概念與語法句式。\\n【思想與史事脈絡】\\n全段旨在大致闡發道德修養、因時制宜與實踐致用之根本原則，對後世國學研究具備極高的參考價值。"}},{"id":"guo-yu_ch-2_p-28","chapterId":"guo-yu_ch-2","order":28,"canonicalText":"襄公曰：「人有言曰：『兵在其頸。』其郤至之謂乎！君子不自稱也，非以讓也，惡其蓋人也。夫人性，陵上者也，不可蓋也。求蓋人，其抑下滋甚，故聖人貴讓。且諺曰：『獸惡其網，民惡其上。』《》曰：『民可近也，而不可上也。』《》曰：『愷悌君子，求福不回。』在禮，敵必三讓，是則聖人知民之不可加也。故王天下者必先諸民，然後庇焉，則能長利。今郤至在七人之下而欲上之，是求蓋七人也，其亦有七怨。怨在小醜，猶不可堪，而況在侈卿乎？其何以待之？","sentenceIds":["guo-yu_ch-2_p-28_s-1","guo-yu_ch-2_p-28_s-2","guo-yu_ch-2_p-28_s-3","guo-yu_ch-2_p-28_s-4","guo-yu_ch-2_p-28_s-5","guo-yu_ch-2_p-28_s-6","guo-yu_ch-2_p-28_s-7","guo-yu_ch-2_p-28_s-8","guo-yu_ch-2_p-28_s-9","guo-yu_ch-2_p-28_s-10","guo-yu_ch-2_p-28_s-11","guo-yu_ch-2_p-28_s-12","guo-yu_ch-2_p-28_s-13"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guo-yu/zh"}],"readingAid":{"translation":"襄公說：人有言說：兵在其頸；其郤至之謂乎；君子不自稱也，非以讓也，惡其蓋人也；夫人性，陵上者也，不可蓋也；求蓋人，其抑下滋甚，故聖人貴讓；且諺說：獸惡其網，民惡其上；《》說：民可近也，而不可上也；《》說：愷悌君子，求福不回。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《國語》〈周語中〉，記錄先秦秦漢經典思想與歷史實踐之精華。\\n【詞義與名物】文中包含關鍵詞彙如：「襄公曰、人有言曰、兵在其頸、其郤至之」，展現古代漢語精練優雅之語法結構。\\n【思想與篇章】本篇體現了修德立身、順應天道與治國安民的深遠哲理，具有極高的學術考證與思想啟發價值。"}},{"id":"guo-yu_ch-2_p-29","chapterId":"guo-yu_ch-2","order":29,"canonicalText":"「晉之克也，天有惡於楚也，故儆之以晉。而郤至佻天之功以為己力，不亦難乎？佻天不祥，乘人不義，不祥則天棄之，不義則民叛之。且郤至何三伐之有？夫仁、禮、勇，皆民之為也。以義死用謂之勇，奉義順則謂之禮，畜義豐功謂之仁。奸仁為佻，奸禮為羞，奸勇為賊。夫戰，盡敵為上，守和同順義為上。故制戎以果毅，制朝以序成。叛戰而擅舍鄭君，賊也；棄毅行容，羞也；叛國即讎，佻也。有三奸以求替其上，遠於得政矣。以吾觀之，兵在其頸，不可久也。雖吾王叔，未能違難。在《太誓》曰：『民之所欲，天必從之。』王叔欲郤至，能勿從乎？」","sentenceIds":["guo-yu_ch-2_p-29_s-1","guo-yu_ch-2_p-29_s-2","guo-yu_ch-2_p-29_s-3","guo-yu_ch-2_p-29_s-4","guo-yu_ch-2_p-29_s-5","guo-yu_ch-2_p-29_s-6","guo-yu_ch-2_p-29_s-7","guo-yu_ch-2_p-29_s-8","guo-yu_ch-2_p-29_s-9","guo-yu_ch-2_p-29_s-10","guo-yu_ch-2_p-29_s-11","guo-yu_ch-2_p-29_s-12","guo-yu_ch-2_p-29_s-13","guo-yu_ch-2_p-29_s-14","guo-yu_ch-2_p-29_s-15","guo-yu_ch-2_p-29_s-16","guo-yu_ch-2_p-29_s-17","guo-yu_ch-2_p-29_s-18"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guo-yu/zh"}],"readingAid":{"translation":"晉之克也，天有惡於楚也，故儆之以晉；而郤至佻天之功以為己力，不亦難乎；佻天不祥，乘人不義，不祥則天棄之，不義則民叛之；且郤至何三伐之有；夫仁、禮、勇，皆民之為也；以義死用謂之勇，奉義順則謂之禮，畜義豐功謂之仁；奸仁為佻，奸禮為羞，奸勇為賊；夫戰，盡敵為上，守和同順義為上。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《國語》〈周語中〉，記錄先秦秦漢經典思想與歷史實踐之精華。\\n【詞義與名物】文中包含關鍵詞彙如：「晉之克也、天有惡於、楚也、故儆之以」，展現古代漢語精練優雅之語法結構。\\n【思想與篇章】本篇體現了修德立身、順應天道與治國安民的深遠哲理，具有極高的學術考證與思想啟發價值。"}},{"id":"guo-yu_ch-2_p-30","chapterId":"guo-yu_ch-2","order":30,"canonicalText":"郤至歸，明年死難。及伯輿之獄，王叔陳生奔晉。","sentenceIds":["guo-yu_ch-2_p-30_s-1","guo-yu_ch-2_p-30_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guo-yu/zh"}],"readingAid":{"translation":"郤至歸，明年死難；及伯輿之獄，王叔陳生奔晉。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【題解與背景】\\n本段選自《國語》〈周語中〉，為該經典著作之精華章節，呈現先秦兩漢時期深刻的思想觀點與歷史實踐。\\n【詞義與名物】\\n文中經典語句「郤至歸，明年死難。及伯輿之獄，王叔陳……」詞意凝練，包含古漢語重要名詞概念與語法句式。\\n【思想與史事脈絡】\\n全段旨在大致闡發道德修養、因時制宜與實踐致用之根本原則，對後世國學研究具備極高的參考價值。"}}],"sentences":[{"id":"guo-yu_ch-1_p-1_s-1","passageId":"guo-yu_ch-1_p-1","order":1,"canonicalText":"穆王將徵犬戎，祭公謀父諫曰：「不可。","chunks":[["穆王將徵犬戎，祭公謀父諫曰：「不可。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-1_s-2","passageId":"guo-yu_ch-1_p-1","order":2,"canonicalText":"先王耀德不觀兵。","chunks":[["先王耀德不觀兵。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-1_s-3","passageId":"guo-yu_ch-1_p-1","order":3,"canonicalText":"夫兵戢而時動，動則威，觀則玩，玩則無震。","chunks":[["夫兵戢而時動，動則威，觀則玩，玩則無震。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-1_s-4","passageId":"guo-yu_ch-1_p-1","order":4,"canonicalText":"是故周文公之《》曰：『』先王之於民也，懋正其德而厚其性，阜其財求而利其器用，明利害之鄉，以文修之，使務利而避害，懷德而畏威，故能保世以滋大。","chunks":[["是故周文公之《》曰：『』先王之於民也，懋正其德而厚其性，阜其財求而利其器用，明利害之鄉，以文修之，使務利而避害，懷德而畏威，故能保世以滋大。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-2_s-1","passageId":"guo-yu_ch-1_p-2","order":1,"canonicalText":"「昔我先王世后稷，以服事虞、夏。","chunks":[["「昔我先王世后稷，以服事虞、夏。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-2_s-2","passageId":"guo-yu_ch-1_p-2","order":2,"canonicalText":"及夏之衰也，棄稷不務，我先王不窋用失其官，而自竄於戎、狄之間，不敢怠業，時序其德，纂修其緒，修其訓典，朝夕恪勤，守以敦篤，奉以忠信，奕世載德，不忝前人。","chunks":[["及夏之衰也，棄稷不務，我先王不窋用失其官，而自竄於戎、狄之間，不敢怠業，時序其德，纂修其緒，修其訓典，朝夕恪勤，守以敦篤，奉以忠信，奕世載德，不忝前人。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-2_s-3","passageId":"guo-yu_ch-1_p-2","order":3,"canonicalText":"至於武王，昭前之光明而加之以慈和，事神保民，莫弗欣喜。","chunks":[["至於武王，昭前之光明而加之以慈和，事神保民，莫弗欣喜。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-2_s-4","passageId":"guo-yu_ch-1_p-2","order":4,"canonicalText":"商王帝辛，大惡於民。","chunks":[["商王帝辛，大惡於民。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-2_s-5","passageId":"guo-yu_ch-1_p-2","order":5,"canonicalText":"庶民不忍，欣戴武王，以致戎於商牧。","chunks":[["庶民不忍，欣戴武王，以致戎於商牧。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-2_s-6","passageId":"guo-yu_ch-1_p-2","order":6,"canonicalText":"是先王非務武也，勤恤民隱而除其害也。","chunks":[["是先王非務武也，勤恤民隱而除其害也。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-3_s-1","passageId":"guo-yu_ch-1_p-3","order":1,"canonicalText":"「夫先王之制：邦內甸服，邦外侯服，侯、衛賓服，蠻、夷要服，戎、狄荒服。","chunks":[["「夫先王之制：邦內甸服，邦外侯服，侯、衛賓服，蠻、夷要服，戎、狄荒服。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-3_s-2","passageId":"guo-yu_ch-1_p-3","order":2,"canonicalText":"甸服者祭，侯服者祀，賓服者享，要服者貢，荒服者王。","chunks":[["甸服者祭，侯服者祀，賓服者享，要服者貢，荒服者王。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-3_s-3","passageId":"guo-yu_ch-1_p-3","order":3,"canonicalText":"日祭、月祀、時享、歲貢、終王，先王之訓也。","chunks":[["日祭、月祀、時享、歲貢、終王，先王之訓也。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-3_s-4","passageId":"guo-yu_ch-1_p-3","order":4,"canonicalText":"有不祭則修意，有不祀則修言，有不享則修文，有不貢則脩名，有不王則修德，序成而有不至則修刑。","chunks":[["有不祭則修意，有不祀則修言，有不享則修文，有不貢則脩名，有不王則修德，序成而有不至則修刑。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-3_s-5","passageId":"guo-yu_ch-1_p-3","order":5,"canonicalText":"於是乎有刑不祭，伐不祀，徵不享，讓不貢，告不王。","chunks":[["於是乎有刑不祭，伐不祀，徵不享，讓不貢，告不王。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-3_s-6","passageId":"guo-yu_ch-1_p-3","order":6,"canonicalText":"於是乎有刑罰之闢，有攻伐之兵，有征討之備，有威讓之令，有文告之辭。","chunks":[["於是乎有刑罰之闢，有攻伐之兵，有征討之備，有威讓之令，有文告之辭。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-3_s-7","passageId":"guo-yu_ch-1_p-3","order":7,"canonicalText":"布令陳辭而又不至，則增修於德而無勤民於遠，是以近無不聽，遠無不服。","chunks":[["布令陳辭而又不至，則增修於德而無勤民於遠，是以近無不聽，遠無不服。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-4_s-1","passageId":"guo-yu_ch-1_p-4","order":1,"canonicalText":"「今自大畢、伯士之終也，犬戎氏以其職來王。","chunks":[["「今自大畢、伯士之終也，犬戎氏以其職來王。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-4_s-2","passageId":"guo-yu_ch-1_p-4","order":2,"canonicalText":"天子曰：『予必以不享徵之，且觀之兵。","chunks":[["天子曰：『予必以不享徵之，且觀之兵。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-4_s-3","passageId":"guo-yu_ch-1_p-4","order":3,"canonicalText":"』其無乃廢先王之訓而王幾頓乎！","chunks":[["』其無乃廢先王之訓而王幾頓乎！","zh-Hant"]]},{"id":"guo-yu_ch-1_p-4_s-4","passageId":"guo-yu_ch-1_p-4","order":4,"canonicalText":"吾聞夫犬戎樹惇，帥舊德而守終純固，其有以御我矣！","chunks":[["吾聞夫犬戎樹惇，帥舊德而守終純固，其有以御我矣！","zh-Hant"]]},{"id":"guo-yu_ch-1_p-4_s-5","passageId":"guo-yu_ch-1_p-4","order":5,"canonicalText":"」王不聽，遂徵之，得四白狼，四白鹿以歸。","chunks":[["」王不聽，遂徵之，得四白狼，四白鹿以歸。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-4_s-6","passageId":"guo-yu_ch-1_p-4","order":6,"canonicalText":"自是荒服者不至。","chunks":[["自是荒服者不至。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-5_s-1","passageId":"guo-yu_ch-1_p-5","order":1,"canonicalText":"恭王遊於涇上，密康公從，有三女奔之。","chunks":[["恭王遊於涇上，密康公從，有三女奔之。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-5_s-2","passageId":"guo-yu_ch-1_p-5","order":2,"canonicalText":"其母曰：「必致之於王。","chunks":[["其母曰：「必致之於王。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-5_s-3","passageId":"guo-yu_ch-1_p-5","order":3,"canonicalText":"夫獸三為羣，人三為眾，女三為粲。","chunks":[["夫獸三為羣，人三為眾，女三為粲。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-5_s-4","passageId":"guo-yu_ch-1_p-5","order":4,"canonicalText":"王田不取羣，公行下眾，王御不參一族。","chunks":[["王田不取羣，公行下眾，王御不參一族。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-5_s-5","passageId":"guo-yu_ch-1_p-5","order":5,"canonicalText":"夫粲，美之物也。","chunks":[["夫粲，美之物也。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-5_s-6","passageId":"guo-yu_ch-1_p-5","order":6,"canonicalText":"眾以美物歸女，而何德以堪之？","chunks":[["眾以美物歸女，而何德以堪之？","zh-Hant"]]},{"id":"guo-yu_ch-1_p-5_s-7","passageId":"guo-yu_ch-1_p-5","order":7,"canonicalText":"王猶不堪，況爾小醜乎？","chunks":[["王猶不堪，況爾小醜乎？","zh-Hant"]]},{"id":"guo-yu_ch-1_p-5_s-8","passageId":"guo-yu_ch-1_p-5","order":8,"canonicalText":"小醜備物，終必亡。","chunks":[["小醜備物，終必亡。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-5_s-9","passageId":"guo-yu_ch-1_p-5","order":9,"canonicalText":"」康公不獻。","chunks":[["」康公不獻。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-5_s-10","passageId":"guo-yu_ch-1_p-5","order":10,"canonicalText":"一年，王滅密。","chunks":[["一年，王滅密。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-6_s-1","passageId":"guo-yu_ch-1_p-6","order":1,"canonicalText":"厲王虐，國人謗王。","chunks":[["厲王虐，國人謗王。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-6_s-2","passageId":"guo-yu_ch-1_p-6","order":2,"canonicalText":"邵公告曰：「民不堪命矣！","chunks":[["邵公告曰：「民不堪命矣！","zh-Hant"]]},{"id":"guo-yu_ch-1_p-6_s-3","passageId":"guo-yu_ch-1_p-6","order":3,"canonicalText":"」王怒，得衛巫，使監謗者，以告，則殺之。","chunks":[["」王怒，得衛巫，使監謗者，以告，則殺之。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-6_s-4","passageId":"guo-yu_ch-1_p-6","order":4,"canonicalText":"國人莫敢言，道路以目。","chunks":[["國人莫敢言，道路以目。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-6_s-5","passageId":"guo-yu_ch-1_p-6","order":5,"canonicalText":"王喜，告邵公曰：「吾能弭謗矣，乃不敢言。","chunks":[["王喜，告邵公曰：「吾能弭謗矣，乃不敢言。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-6_s-6","passageId":"guo-yu_ch-1_p-6","order":6,"canonicalText":"」邵公曰：「是障之也，防民之口，甚於防川。","chunks":[["」邵公曰：「是障之也，防民之口，甚於防川。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-6_s-7","passageId":"guo-yu_ch-1_p-6","order":7,"canonicalText":"川壅而潰，傷人必多，民亦如之。","chunks":[["川壅而潰，傷人必多，民亦如之。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-6_s-8","passageId":"guo-yu_ch-1_p-6","order":8,"canonicalText":"是故為川者決之使導，為民者宣之使言。","chunks":[["是故為川者決之使導，為民者宣之使言。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-6_s-9","passageId":"guo-yu_ch-1_p-6","order":9,"canonicalText":"故天子聽政，使公卿至於列士獻詩，瞽獻曲，史獻書，師箴，瞍賦，矇誦，百工諫，庶人傳語，近臣盡規，親戚補察，瞽、史教誨，耆、艾修之，而後王斟酌焉，是以事行而不悖。","chunks":[["故天子聽政，使公卿至於列士獻詩，瞽獻曲，史獻書，師箴，瞍賦，矇誦，百工諫，庶人傳語，近臣盡規，親戚補察，瞽、史教誨，耆、艾修之，而後王斟酌焉，是以事行而不悖。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-6_s-10","passageId":"guo-yu_ch-1_p-6","order":10,"canonicalText":"民之有口，猶土之有山川也，財用於是乎出，猶其原隰之有衍沃也，衣食於是乎生。","chunks":[["民之有口，猶土之有山川也，財用於是乎出，猶其原隰之有衍沃也，衣食於是乎生。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-6_s-11","passageId":"guo-yu_ch-1_p-6","order":11,"canonicalText":"口之宣言也，善敗於是乎興，行善而備敗，其所以阜財用、衣食者也。","chunks":[["口之宣言也，善敗於是乎興，行善而備敗，其所以阜財用、衣食者也。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-6_s-12","passageId":"guo-yu_ch-1_p-6","order":12,"canonicalText":"夫民慮之於心而宣之於口，成而行之，胡可壅也？","chunks":[["夫民慮之於心而宣之於口，成而行之，胡可壅也？","zh-Hant"]]},{"id":"guo-yu_ch-1_p-6_s-13","passageId":"guo-yu_ch-1_p-6","order":13,"canonicalText":"若壅其口，其與能幾何？","chunks":[["若壅其口，其與能幾何？","zh-Hant"]]},{"id":"guo-yu_ch-1_p-6_s-14","passageId":"guo-yu_ch-1_p-6","order":14,"canonicalText":"」王不聽，於是國莫敢出言，三年，乃流王於彘。","chunks":[["」王不聽，於是國莫敢出言，三年，乃流王於彘。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-7_s-1","passageId":"guo-yu_ch-1_p-7","order":1,"canonicalText":"厲王說榮夷公，芮良夫曰：「王室其將卑乎！","chunks":[["厲王說榮夷公，芮良夫曰：「王室其將卑乎！","zh-Hant"]]},{"id":"guo-yu_ch-1_p-7_s-2","passageId":"guo-yu_ch-1_p-7","order":2,"canonicalText":"夫榮公好專利而不知大難。","chunks":[["夫榮公好專利而不知大難。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-7_s-3","passageId":"guo-yu_ch-1_p-7","order":3,"canonicalText":"夫利，百物之所生也，天地之所載也，而或專之，其害多矣。","chunks":[["夫利，百物之所生也，天地之所載也，而或專之，其害多矣。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-7_s-4","passageId":"guo-yu_ch-1_p-7","order":4,"canonicalText":"天地百物，皆將取焉，胡可專也？","chunks":[["天地百物，皆將取焉，胡可專也？","zh-Hant"]]},{"id":"guo-yu_ch-1_p-7_s-5","passageId":"guo-yu_ch-1_p-7","order":5,"canonicalText":"所怒甚多，而不備大難，以是教王，王能久乎？","chunks":[["所怒甚多，而不備大難，以是教王，王能久乎？","zh-Hant"]]},{"id":"guo-yu_ch-1_p-7_s-6","passageId":"guo-yu_ch-1_p-7","order":6,"canonicalText":"夫王人者，將導利而布之上下者也，使神人百物無不得其極，猶曰怵惕，懼怨之來也。","chunks":[["夫王人者，將導利而布之上下者也，使神人百物無不得其極，猶曰怵惕，懼怨之來也。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-7_s-7","passageId":"guo-yu_ch-1_p-7","order":7,"canonicalText":"故《》曰：『思文后稷，克配彼天。","chunks":[["故《》曰：『思文后稷，克配彼天。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-7_s-8","passageId":"guo-yu_ch-1_p-7","order":8,"canonicalText":"立我蒸民，莫匪爾極。","chunks":[["立我蒸民，莫匪爾極。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-7_s-9","passageId":"guo-yu_ch-1_p-7","order":9,"canonicalText":"』《》曰：『陳錫載周。","chunks":[["』《》曰：『陳錫載周。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-7_s-10","passageId":"guo-yu_ch-1_p-7","order":10,"canonicalText":"』是不布利而懼難乎？","chunks":[["』是不布利而懼難乎？","zh-Hant"]]},{"id":"guo-yu_ch-1_p-7_s-11","passageId":"guo-yu_ch-1_p-7","order":11,"canonicalText":"故能載周，以至於今。","chunks":[["故能載周，以至於今。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-7_s-12","passageId":"guo-yu_ch-1_p-7","order":12,"canonicalText":"今王學專利，其可乎？","chunks":[["今王學專利，其可乎？","zh-Hant"]]},{"id":"guo-yu_ch-1_p-7_s-13","passageId":"guo-yu_ch-1_p-7","order":13,"canonicalText":"匹夫專利，猶謂之盜，王而行之，其歸鮮矣。","chunks":[["匹夫專利，猶謂之盜，王而行之，其歸鮮矣。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-7_s-14","passageId":"guo-yu_ch-1_p-7","order":14,"canonicalText":"榮公若用，周必敗。","chunks":[["榮公若用，周必敗。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-7_s-15","passageId":"guo-yu_ch-1_p-7","order":15,"canonicalText":"既，榮公為卿士，諸侯不享，王流於彘。","chunks":[["既，榮公為卿士，諸侯不享，王流於彘。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-8_s-1","passageId":"guo-yu_ch-1_p-8","order":1,"canonicalText":"彘之亂，宣王在邵公之宮，國人圍之，邵公曰：「昔吾驟諫王，王不從，是以及此難。","chunks":[["彘之亂，宣王在邵公之宮，國人圍之，邵公曰：「昔吾驟諫王，王不從，是以及此難。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-8_s-2","passageId":"guo-yu_ch-1_p-8","order":2,"canonicalText":"今殺王子，王其以我為懟而怒乎！","chunks":[["今殺王子，王其以我為懟而怒乎！","zh-Hant"]]},{"id":"guo-yu_ch-1_p-8_s-3","passageId":"guo-yu_ch-1_p-8","order":3,"canonicalText":"夫事君者險而不懟，怨而不怒，況事王乎？","chunks":[["夫事君者險而不懟，怨而不怒，況事王乎？","zh-Hant"]]},{"id":"guo-yu_ch-1_p-8_s-4","passageId":"guo-yu_ch-1_p-8","order":4,"canonicalText":"」乃以其子代宣王，宣王長而立之。","chunks":[["」乃以其子代宣王，宣王長而立之。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-9_s-1","passageId":"guo-yu_ch-1_p-9","order":1,"canonicalText":"宣王即位，不籍千畝。","chunks":[["宣王即位，不籍千畝。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-9_s-2","passageId":"guo-yu_ch-1_p-9","order":2,"canonicalText":"虢文公諫曰：「不可。","chunks":[["虢文公諫曰：「不可。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-9_s-3","passageId":"guo-yu_ch-1_p-9","order":3,"canonicalText":"夫民之大事在農，上帝之粢盛於是乎出，民之蕃庶於是乎生，事之供給於是乎在，和協輯睦於是乎興，財用蕃殖於是乎始，敦庬純固於是乎成，是故稷為大官。","chunks":[["夫民之大事在農，上帝之粢盛於是乎出，民之蕃庶於是乎生，事之供給於是乎在，和協輯睦於是乎興，財用蕃殖於是乎始，敦庬純固於是乎成，是故稷為大官。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-9_s-4","passageId":"guo-yu_ch-1_p-9","order":4,"canonicalText":"古者，太史順時覛土，陽癉憤盈，土氣震發，農祥晨正，日月底於天廟，土乃脈發。","chunks":[["古者，太史順時覛土，陽癉憤盈，土氣震發，農祥晨正，日月底於天廟，土乃脈發。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-10_s-1","passageId":"guo-yu_ch-1_p-10","order":1,"canonicalText":"「先時九日，太史告稷曰：『自今至於初吉，陽氣俱蒸，土膏其動。","chunks":[["「先時九日，太史告稷曰：『自今至於初吉，陽氣俱蒸，土膏其動。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-10_s-2","passageId":"guo-yu_ch-1_p-10","order":2,"canonicalText":"弗震弗渝，脈其滿眚，穀乃不殖。","chunks":[["弗震弗渝，脈其滿眚，穀乃不殖。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-10_s-3","passageId":"guo-yu_ch-1_p-10","order":3,"canonicalText":"』稷以告王曰：『史帥陽官以命我司事曰：「距今九日，土其俱動，王其祗祓，監農不易。","chunks":[["』稷以告王曰：『史帥陽官以命我司事曰：「距今九日，土其俱動，王其祗祓，監農不易。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-10_s-4","passageId":"guo-yu_ch-1_p-10","order":4,"canonicalText":"」』王乃使司徒鹹戒公卿、百吏、庶民，司空除壇於籍，命農大夫鹹戒農用。","chunks":[["」』王乃使司徒鹹戒公卿、百吏、庶民，司空除壇於籍，命農大夫鹹戒農用。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-11_s-1","passageId":"guo-yu_ch-1_p-11","order":1,"canonicalText":"「先時五日，瞽告有協風至，王即齋宮，百官御事，各即其齋三日。","chunks":[["「先時五日，瞽告有協風至，王即齋宮，百官御事，各即其齋三日。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-11_s-2","passageId":"guo-yu_ch-1_p-11","order":2,"canonicalText":"王乃淳濯饗醴，及期，鬱人薦鬯，犧人薦醴，王祼鬯，饗醴乃行，百吏、庶民畢從。","chunks":[["王乃淳濯饗醴，及期，鬱人薦鬯，犧人薦醴，王祼鬯，饗醴乃行，百吏、庶民畢從。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-11_s-3","passageId":"guo-yu_ch-1_p-11","order":3,"canonicalText":"及籍，后稷監之，膳夫、農正陳籍禮，太史贊王，王敬從之。","chunks":[["及籍，后稷監之，膳夫、農正陳籍禮，太史贊王，王敬從之。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-11_s-4","passageId":"guo-yu_ch-1_p-11","order":4,"canonicalText":"王耕一墢，班三之，庶民終於千畝，其后稷省功，太史監之；","chunks":[["王耕一墢，班三之，庶民終於千畝，其后稷省功，太史監之；","zh-Hant"]]},{"id":"guo-yu_ch-1_p-11_s-5","passageId":"guo-yu_ch-1_p-11","order":5,"canonicalText":"司徒省民，太師監之；","chunks":[["司徒省民，太師監之；","zh-Hant"]]},{"id":"guo-yu_ch-1_p-11_s-6","passageId":"guo-yu_ch-1_p-11","order":6,"canonicalText":"畢，宰夫陳饗，膳宰監之。","chunks":[["畢，宰夫陳饗，膳宰監之。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-11_s-7","passageId":"guo-yu_ch-1_p-11","order":7,"canonicalText":"膳夫贊王，王歆大牢，班嘗之，庶人終食。","chunks":[["膳夫贊王，王歆大牢，班嘗之，庶人終食。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-12_s-1","passageId":"guo-yu_ch-1_p-12","order":1,"canonicalText":"「是日也，瞽帥、音官以風土。","chunks":[["「是日也，瞽帥、音官以風土。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-12_s-2","passageId":"guo-yu_ch-1_p-12","order":2,"canonicalText":"廩於籍東南，鍾而藏之，而時布之於農。","chunks":[["廩於籍東南，鍾而藏之，而時布之於農。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-12_s-3","passageId":"guo-yu_ch-1_p-12","order":3,"canonicalText":"稷則遍誡百姓，紀農協功，曰：『陰陽分佈，震雷出滯。","chunks":[["稷則遍誡百姓，紀農協功，曰：『陰陽分佈，震雷出滯。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-12_s-4","passageId":"guo-yu_ch-1_p-12","order":4,"canonicalText":"』土不備墾，闢在司寇。","chunks":[["』土不備墾，闢在司寇。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-12_s-5","passageId":"guo-yu_ch-1_p-12","order":5,"canonicalText":"乃命其旅曰：『徇，農師一之，農正再之，后稷三之，司空四之，司徒五之，太保六之，太師七之，太史八之，宗伯九之，王則大徇，耨獲亦如之。","chunks":[["乃命其旅曰：『徇，農師一之，農正再之，后稷三之，司空四之，司徒五之，太保六之，太師七之，太史八之，宗伯九之，王則大徇，耨獲亦如之。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-12_s-6","passageId":"guo-yu_ch-1_p-12","order":6,"canonicalText":"』民用莫不震動，恪恭於農，修其疆畔，日服其鎛，不解於時，財用不乏，民用和同。","chunks":[["』民用莫不震動，恪恭於農，修其疆畔，日服其鎛，不解於時，財用不乏，民用和同。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-13_s-1","passageId":"guo-yu_ch-1_p-13","order":1,"canonicalText":"「是時也，王事唯農是務，無有求利於其官，以幹農功，三時務農而一時講武，故徵則有威，守則有財。","chunks":[["「是時也，王事唯農是務，無有求利於其官，以幹農功，三時務農而一時講武，故徵則有威，守則有財。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-13_s-2","passageId":"guo-yu_ch-1_p-13","order":2,"canonicalText":"若是，乃能媚於神而和於民矣，則享祀時至而佈施優裕也。","chunks":[["若是，乃能媚於神而和於民矣，則享祀時至而佈施優裕也。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-13_s-3","passageId":"guo-yu_ch-1_p-13","order":3,"canonicalText":"今天子欲修先王之緒而棄其大功，匱神乏祀而困民之財，將何以求福用民？","chunks":[["今天子欲修先王之緒而棄其大功，匱神乏祀而困民之財，將何以求福用民？","zh-Hant"]]},{"id":"guo-yu_ch-1_p-13_s-4","passageId":"guo-yu_ch-1_p-13","order":4,"canonicalText":"」王不聽。","chunks":[["」王不聽。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-13_s-5","passageId":"guo-yu_ch-1_p-13","order":5,"canonicalText":"三十九年，戰於千畝，王師敗績於姜氏之戎。","chunks":[["三十九年，戰於千畝，王師敗績於姜氏之戎。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-14_s-1","passageId":"guo-yu_ch-1_p-14","order":1,"canonicalText":"魯武公以括與戲見王，王立戲，樊仲山父諫曰：「不可立也！","chunks":[["魯武公以括與戲見王，王立戲，樊仲山父諫曰：「不可立也！","zh-Hant"]]},{"id":"guo-yu_ch-1_p-14_s-2","passageId":"guo-yu_ch-1_p-14","order":2,"canonicalText":"不順必犯，犯王命必誅，故出令不可不順也。","chunks":[["不順必犯，犯王命必誅，故出令不可不順也。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-14_s-3","passageId":"guo-yu_ch-1_p-14","order":3,"canonicalText":"令之不行，政之不立。","chunks":[["令之不行，政之不立。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-14_s-4","passageId":"guo-yu_ch-1_p-14","order":4,"canonicalText":"行而不順，民將棄上。","chunks":[["行而不順，民將棄上。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-14_s-5","passageId":"guo-yu_ch-1_p-14","order":5,"canonicalText":"夫下事上，少事長，所以為順也。","chunks":[["夫下事上，少事長，所以為順也。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-14_s-6","passageId":"guo-yu_ch-1_p-14","order":6,"canonicalText":"今天子立諸侯而建其少，是教逆也。","chunks":[["今天子立諸侯而建其少，是教逆也。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-14_s-7","passageId":"guo-yu_ch-1_p-14","order":7,"canonicalText":"若魯從之而諸侯效之，王命將有所壅，若不從而誅之，是自誅王命也。","chunks":[["若魯從之而諸侯效之，王命將有所壅，若不從而誅之，是自誅王命也。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-14_s-8","passageId":"guo-yu_ch-1_p-14","order":8,"canonicalText":"是事也，誅亦失，不誅亦失，天子其圖之！","chunks":[["是事也，誅亦失，不誅亦失，天子其圖之！","zh-Hant"]]},{"id":"guo-yu_ch-1_p-14_s-9","passageId":"guo-yu_ch-1_p-14","order":9,"canonicalText":"」王卒立之。","chunks":[["」王卒立之。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-14_s-10","passageId":"guo-yu_ch-1_p-14","order":10,"canonicalText":"魯侯歸而卒，及魯人殺懿公而立伯御。","chunks":[["魯侯歸而卒，及魯人殺懿公而立伯御。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-15_s-1","passageId":"guo-yu_ch-1_p-15","order":1,"canonicalText":"三十二年春，宣王伐魯，立孝公，諸侯從是而不睦。","chunks":[["三十二年春，宣王伐魯，立孝公，諸侯從是而不睦。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-15_s-2","passageId":"guo-yu_ch-1_p-15","order":2,"canonicalText":"宣王欲得國子之能導訓諸侯者，樊穆仲曰：「魯侯孝。","chunks":[["宣王欲得國子之能導訓諸侯者，樊穆仲曰：「魯侯孝。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-15_s-3","passageId":"guo-yu_ch-1_p-15","order":3,"canonicalText":"」王曰：「何以知之？","chunks":[["」王曰：「何以知之？","zh-Hant"]]},{"id":"guo-yu_ch-1_p-15_s-4","passageId":"guo-yu_ch-1_p-15","order":4,"canonicalText":"」對曰：「肅恭明神而敬事耇老，賦事行刑，必問於遺訓而諮於故實，不幹所問，不犯所諮。","chunks":[["」對曰：「肅恭明神而敬事耇老，賦事行刑，必問於遺訓而諮於故實，不幹所問，不犯所諮。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-15_s-5","passageId":"guo-yu_ch-1_p-15","order":5,"canonicalText":"」王曰：「然則能訓治其民矣。","chunks":[["」王曰：「然則能訓治其民矣。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-15_s-6","passageId":"guo-yu_ch-1_p-15","order":6,"canonicalText":"」乃命魯孝公於夷宮。","chunks":[["」乃命魯孝公於夷宮。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-16_s-1","passageId":"guo-yu_ch-1_p-16","order":1,"canonicalText":"宣王既喪南國之師，乃料民於太原。","chunks":[["宣王既喪南國之師，乃料民於太原。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-16_s-2","passageId":"guo-yu_ch-1_p-16","order":2,"canonicalText":"仲山父諫曰：「民不可料也！","chunks":[["仲山父諫曰：「民不可料也！","zh-Hant"]]},{"id":"guo-yu_ch-1_p-16_s-3","passageId":"guo-yu_ch-1_p-16","order":3,"canonicalText":"夫古者不料民而知其少多，司民協孤終，司商協民姓，司徒協旅，司寇協奸，牧協職，工協革，場協入，廩協出，是則少多、死生、出入、往來者皆可知也，於是乎又審之以事，王治農於籍，蒐於農隙，耨獲亦於籍，獮於既烝，狩於畢時，是皆習民數者也，又何料焉？","chunks":[["夫古者不料民而知其少多，司民協孤終，司商協民姓，司徒協旅，司寇協奸，牧協職，工協革，場協入，廩協出，是則少多、死生、出入、往來者皆可知也，於是乎又審之以事，王治農於籍，蒐於農隙，耨獲亦於籍，獮於既烝，狩於畢時，是皆習民數者也，又何料焉？","zh-Hant"]]},{"id":"guo-yu_ch-1_p-16_s-4","passageId":"guo-yu_ch-1_p-16","order":4,"canonicalText":"不謂其少而大料之，是示少而惡事也。","chunks":[["不謂其少而大料之，是示少而惡事也。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-16_s-5","passageId":"guo-yu_ch-1_p-16","order":5,"canonicalText":"臨政示少，諸侯避之。","chunks":[["臨政示少，諸侯避之。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-16_s-6","passageId":"guo-yu_ch-1_p-16","order":6,"canonicalText":"治民惡事，無以賦令。","chunks":[["治民惡事，無以賦令。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-16_s-7","passageId":"guo-yu_ch-1_p-16","order":7,"canonicalText":"且無故而料民，天之所惡也，害於政而妨於後嗣。","chunks":[["且無故而料民，天之所惡也，害於政而妨於後嗣。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-16_s-8","passageId":"guo-yu_ch-1_p-16","order":8,"canonicalText":"」王卒料之，及幽王乃廢滅。","chunks":[["」王卒料之，及幽王乃廢滅。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-17_s-1","passageId":"guo-yu_ch-1_p-17","order":1,"canonicalText":"幽王二年，西周三川皆震。","chunks":[["幽王二年，西周三川皆震。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-17_s-2","passageId":"guo-yu_ch-1_p-17","order":2,"canonicalText":"伯陽父曰：「周將亡矣！","chunks":[["伯陽父曰：「周將亡矣！","zh-Hant"]]},{"id":"guo-yu_ch-1_p-17_s-3","passageId":"guo-yu_ch-1_p-17","order":3,"canonicalText":"夫天地之氣，不失其序；","chunks":[["夫天地之氣，不失其序；","zh-Hant"]]},{"id":"guo-yu_ch-1_p-17_s-4","passageId":"guo-yu_ch-1_p-17","order":4,"canonicalText":"若過其序，民亂之也。","chunks":[["若過其序，民亂之也。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-17_s-5","passageId":"guo-yu_ch-1_p-17","order":5,"canonicalText":"陽伏而不能出，陰迫而不能烝，於是有地震。","chunks":[["陽伏而不能出，陰迫而不能烝，於是有地震。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-17_s-6","passageId":"guo-yu_ch-1_p-17","order":6,"canonicalText":"今三川實震，是陽失其所而鎮陰也。","chunks":[["今三川實震，是陽失其所而鎮陰也。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-17_s-7","passageId":"guo-yu_ch-1_p-17","order":7,"canonicalText":"陽失而在陰，川源必塞；","chunks":[["陽失而在陰，川源必塞；","zh-Hant"]]},{"id":"guo-yu_ch-1_p-17_s-8","passageId":"guo-yu_ch-1_p-17","order":8,"canonicalText":"源塞，國必亡。","chunks":[["源塞，國必亡。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-17_s-9","passageId":"guo-yu_ch-1_p-17","order":9,"canonicalText":"夫水土演而民用也。","chunks":[["夫水土演而民用也。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-17_s-10","passageId":"guo-yu_ch-1_p-17","order":10,"canonicalText":"水土無所演，民乏財用，不亡何待？","chunks":[["水土無所演，民乏財用，不亡何待？","zh-Hant"]]},{"id":"guo-yu_ch-1_p-17_s-11","passageId":"guo-yu_ch-1_p-17","order":11,"canonicalText":"昔伊、洛竭而夏亡，河竭而商亡。","chunks":[["昔伊、洛竭而夏亡，河竭而商亡。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-17_s-12","passageId":"guo-yu_ch-1_p-17","order":12,"canonicalText":"今周德若二代之季矣，其川源又塞，塞必竭。","chunks":[["今周德若二代之季矣，其川源又塞，塞必竭。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-17_s-13","passageId":"guo-yu_ch-1_p-17","order":13,"canonicalText":"夫國必依山川，山崩川竭，亡之徵也。","chunks":[["夫國必依山川，山崩川竭，亡之徵也。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-17_s-14","passageId":"guo-yu_ch-1_p-17","order":14,"canonicalText":"川竭，山必崩。","chunks":[["川竭，山必崩。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-17_s-15","passageId":"guo-yu_ch-1_p-17","order":15,"canonicalText":"若國亡不過十年，數之紀也。","chunks":[["若國亡不過十年，數之紀也。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-17_s-16","passageId":"guo-yu_ch-1_p-17","order":16,"canonicalText":"夫天之所棄，不過其紀。","chunks":[["夫天之所棄，不過其紀。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-17_s-17","passageId":"guo-yu_ch-1_p-17","order":17,"canonicalText":"」是歲也，三川竭，岐山崩。","chunks":[["」是歲也，三川竭，岐山崩。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-17_s-18","passageId":"guo-yu_ch-1_p-17","order":18,"canonicalText":"十一年，幽王乃滅，周乃東遷。","chunks":[["十一年，幽王乃滅，周乃東遷。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-18_s-1","passageId":"guo-yu_ch-1_p-18","order":1,"canonicalText":"惠王三年，邊伯、石速、蒍國出王而立子頹。","chunks":[["惠王三年，邊伯、石速、蒍國出王而立子頹。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-18_s-2","passageId":"guo-yu_ch-1_p-18","order":2,"canonicalText":"王處於鄭三年。","chunks":[["王處於鄭三年。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-18_s-3","passageId":"guo-yu_ch-1_p-18","order":3,"canonicalText":"王子頹飲三大夫酒，子國為客，樂及遍舞。","chunks":[["王子頹飲三大夫酒，子國為客，樂及遍舞。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-18_s-4","passageId":"guo-yu_ch-1_p-18","order":4,"canonicalText":"鄭厲公見虢叔，曰：「吾聞之，司寇行戮，君為之不舉，而況敢樂禍乎！","chunks":[["鄭厲公見虢叔，曰：「吾聞之，司寇行戮，君為之不舉，而況敢樂禍乎！","zh-Hant"]]},{"id":"guo-yu_ch-1_p-18_s-5","passageId":"guo-yu_ch-1_p-18","order":5,"canonicalText":"今吾聞子頹歌舞不息，樂禍也。","chunks":[["今吾聞子頹歌舞不息，樂禍也。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-18_s-6","passageId":"guo-yu_ch-1_p-18","order":6,"canonicalText":"夫出王而代其位，禍孰大焉！","chunks":[["夫出王而代其位，禍孰大焉！","zh-Hant"]]},{"id":"guo-yu_ch-1_p-18_s-7","passageId":"guo-yu_ch-1_p-18","order":7,"canonicalText":"臨禍忘憂，是謂樂禍，禍必及之，盍納王乎？","chunks":[["臨禍忘憂，是謂樂禍，禍必及之，盍納王乎？","zh-Hant"]]},{"id":"guo-yu_ch-1_p-18_s-8","passageId":"guo-yu_ch-1_p-18","order":8,"canonicalText":"」虢叔許諾。","chunks":[["」虢叔許諾。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-18_s-9","passageId":"guo-yu_ch-1_p-18","order":9,"canonicalText":"鄭伯將王自圉門入，虢叔自北門入，殺子頹及三大夫，王乃入也。","chunks":[["鄭伯將王自圉門入，虢叔自北門入，殺子頹及三大夫，王乃入也。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-19_s-1","passageId":"guo-yu_ch-1_p-19","order":1,"canonicalText":"十五年，有神降於莘，王問於內史過，曰：「是何故？","chunks":[["十五年，有神降於莘，王問於內史過，曰：「是何故？","zh-Hant"]]},{"id":"guo-yu_ch-1_p-19_s-2","passageId":"guo-yu_ch-1_p-19","order":2,"canonicalText":"固有之乎？","chunks":[["固有之乎？","zh-Hant"]]},{"id":"guo-yu_ch-1_p-19_s-3","passageId":"guo-yu_ch-1_p-19","order":3,"canonicalText":"」對曰：「有之。","chunks":[["」對曰：「有之。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-19_s-4","passageId":"guo-yu_ch-1_p-19","order":4,"canonicalText":"國之將興，其君齊明、衷正、精潔、惠和，其德足以昭其馨香，其惠足以同其民人。","chunks":[["國之將興，其君齊明、衷正、精潔、惠和，其德足以昭其馨香，其惠足以同其民人。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-19_s-5","passageId":"guo-yu_ch-1_p-19","order":5,"canonicalText":"神饗而民聽，民神無怨，故明神降之，觀其政德而均布福焉。","chunks":[["神饗而民聽，民神無怨，故明神降之，觀其政德而均布福焉。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-19_s-6","passageId":"guo-yu_ch-1_p-19","order":6,"canonicalText":"國之將亡，其君貪冒、辟邪、淫佚、荒怠、粗穢、暴虐；","chunks":[["國之將亡，其君貪冒、辟邪、淫佚、荒怠、粗穢、暴虐；","zh-Hant"]]},{"id":"guo-yu_ch-1_p-19_s-7","passageId":"guo-yu_ch-1_p-19","order":7,"canonicalText":"其政腥臊，馨香不登；","chunks":[["其政腥臊，馨香不登；","zh-Hant"]]},{"id":"guo-yu_ch-1_p-19_s-8","passageId":"guo-yu_ch-1_p-19","order":8,"canonicalText":"其刑矯誣，百姓攜貳。","chunks":[["其刑矯誣，百姓攜貳。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-19_s-9","passageId":"guo-yu_ch-1_p-19","order":9,"canonicalText":"明神不蠲而民有遠志，民神怨痛，無所依懷，故神亦往焉，觀其苛慝而降之禍。","chunks":[["明神不蠲而民有遠志，民神怨痛，無所依懷，故神亦往焉，觀其苛慝而降之禍。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-19_s-10","passageId":"guo-yu_ch-1_p-19","order":10,"canonicalText":"是以或見神以興，亦或以亡。","chunks":[["是以或見神以興，亦或以亡。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-19_s-11","passageId":"guo-yu_ch-1_p-19","order":11,"canonicalText":"昔夏之興也，融降於崇山；","chunks":[["昔夏之興也，融降於崇山；","zh-Hant"]]},{"id":"guo-yu_ch-1_p-19_s-12","passageId":"guo-yu_ch-1_p-19","order":12,"canonicalText":"其亡也，回祿信於耹隧。","chunks":[["其亡也，回祿信於耹隧。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-19_s-13","passageId":"guo-yu_ch-1_p-19","order":13,"canonicalText":"商之興也，檮杌次於丕山，其亡也，夷羊在牧。","chunks":[["商之興也，檮杌次於丕山，其亡也，夷羊在牧。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-19_s-14","passageId":"guo-yu_ch-1_p-19","order":14,"canonicalText":"周之興也，鸑鷟鳴於岐山；","chunks":[["周之興也，鸑鷟鳴於岐山；","zh-Hant"]]},{"id":"guo-yu_ch-1_p-19_s-15","passageId":"guo-yu_ch-1_p-19","order":15,"canonicalText":"其衰也，杜伯射王於鄗。","chunks":[["其衰也，杜伯射王於鄗。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-19_s-16","passageId":"guo-yu_ch-1_p-19","order":16,"canonicalText":"是皆明神之志者也。","chunks":[["是皆明神之志者也。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-19_s-17","passageId":"guo-yu_ch-1_p-19","order":17,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"guo-yu_ch-1_p-20_s-1","passageId":"guo-yu_ch-1_p-20","order":1,"canonicalText":"王曰：「今是何神也？","chunks":[["王曰：「今是何神也？","zh-Hant"]]},{"id":"guo-yu_ch-1_p-20_s-2","passageId":"guo-yu_ch-1_p-20","order":2,"canonicalText":"」對曰：「昔昭王娶於房，曰房後，實有爽德，協于丹朱，丹朱憑身以儀之，生穆王焉。","chunks":[["」對曰：「昔昭王娶於房，曰房後，實有爽德，協于丹朱，丹朱憑身以儀之，生穆王焉。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-20_s-3","passageId":"guo-yu_ch-1_p-20","order":3,"canonicalText":"是實臨照周之子孫而禍福之。","chunks":[["是實臨照周之子孫而禍福之。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-20_s-4","passageId":"guo-yu_ch-1_p-20","order":4,"canonicalText":"夫神壹不遠徙遷，若由是觀之，其丹朱之神乎？","chunks":[["夫神壹不遠徙遷，若由是觀之，其丹朱之神乎？","zh-Hant"]]},{"id":"guo-yu_ch-1_p-20_s-5","passageId":"guo-yu_ch-1_p-20","order":5,"canonicalText":"」王曰：「其誰受之？","chunks":[["」王曰：「其誰受之？","zh-Hant"]]},{"id":"guo-yu_ch-1_p-20_s-6","passageId":"guo-yu_ch-1_p-20","order":6,"canonicalText":"」對曰：「在虢土。","chunks":[["」對曰：「在虢土。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-20_s-7","passageId":"guo-yu_ch-1_p-20","order":7,"canonicalText":"」王曰：「然則何為？","chunks":[["」王曰：「然則何為？","zh-Hant"]]},{"id":"guo-yu_ch-1_p-20_s-8","passageId":"guo-yu_ch-1_p-20","order":8,"canonicalText":"」對曰：「臣聞之：道而得神，是謂逢福；","chunks":[["」對曰：「臣聞之：道而得神，是謂逢福；","zh-Hant"]]},{"id":"guo-yu_ch-1_p-20_s-9","passageId":"guo-yu_ch-1_p-20","order":9,"canonicalText":"淫而得神，是謂貪禍。","chunks":[["淫而得神，是謂貪禍。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-20_s-10","passageId":"guo-yu_ch-1_p-20","order":10,"canonicalText":"今虢少荒，其亡乎？","chunks":[["今虢少荒，其亡乎？","zh-Hant"]]},{"id":"guo-yu_ch-1_p-20_s-11","passageId":"guo-yu_ch-1_p-20","order":11,"canonicalText":"」王曰：「吾其若之何？","chunks":[["」王曰：「吾其若之何？","zh-Hant"]]},{"id":"guo-yu_ch-1_p-20_s-12","passageId":"guo-yu_ch-1_p-20","order":12,"canonicalText":"」對曰：「使太宰以祝，史帥貍姓，奉犧牲、粢盛、玉帛往獻焉，無有祈也。","chunks":[["」對曰：「使太宰以祝，史帥貍姓，奉犧牲、粢盛、玉帛往獻焉，無有祈也。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-20_s-13","passageId":"guo-yu_ch-1_p-20","order":13,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"guo-yu_ch-1_p-21_s-1","passageId":"guo-yu_ch-1_p-21","order":1,"canonicalText":"王曰：「虢其幾何？","chunks":[["王曰：「虢其幾何？","zh-Hant"]]},{"id":"guo-yu_ch-1_p-21_s-2","passageId":"guo-yu_ch-1_p-21","order":2,"canonicalText":"」對曰：「昔堯臨民以五，今其胄見，神之見也，不過其物。","chunks":[["」對曰：「昔堯臨民以五，今其胄見，神之見也，不過其物。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-21_s-3","passageId":"guo-yu_ch-1_p-21","order":3,"canonicalText":"若由是觀之，不過五年。","chunks":[["若由是觀之，不過五年。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-21_s-4","passageId":"guo-yu_ch-1_p-21","order":4,"canonicalText":"」王使太宰忌父帥傅氏及祝、史奉犧牲、玉鬯往獻焉。","chunks":[["」王使太宰忌父帥傅氏及祝、史奉犧牲、玉鬯往獻焉。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-21_s-5","passageId":"guo-yu_ch-1_p-21","order":5,"canonicalText":"內史過從至虢，虢公亦使祝、史請土焉。","chunks":[["內史過從至虢，虢公亦使祝、史請土焉。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-21_s-6","passageId":"guo-yu_ch-1_p-21","order":6,"canonicalText":"內史過歸，以告王曰：「虢必亡矣，不禋於神而求福焉，神必禍之；","chunks":[["內史過歸，以告王曰：「虢必亡矣，不禋於神而求福焉，神必禍之；","zh-Hant"]]},{"id":"guo-yu_ch-1_p-21_s-7","passageId":"guo-yu_ch-1_p-21","order":7,"canonicalText":"不親於民而求用焉，人必違之。","chunks":[["不親於民而求用焉，人必違之。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-21_s-8","passageId":"guo-yu_ch-1_p-21","order":8,"canonicalText":"精意以享，禋也；","chunks":[["精意以享，禋也；","zh-Hant"]]},{"id":"guo-yu_ch-1_p-21_s-9","passageId":"guo-yu_ch-1_p-21","order":9,"canonicalText":"慈保庶民，親也。","chunks":[["慈保庶民，親也。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-21_s-10","passageId":"guo-yu_ch-1_p-21","order":10,"canonicalText":"今虢公動匱百姓以逞其違，離民怒神而求利焉，不亦難乎！","chunks":[["今虢公動匱百姓以逞其違，離民怒神而求利焉，不亦難乎！","zh-Hant"]]},{"id":"guo-yu_ch-1_p-21_s-11","passageId":"guo-yu_ch-1_p-21","order":11,"canonicalText":"」十九年，晉取虢。","chunks":[["」十九年，晉取虢。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-22_s-1","passageId":"guo-yu_ch-1_p-22","order":1,"canonicalText":"襄王使邵公過及內史過賜晉惠公命，呂甥、郤芮相晉侯不敬，晉侯執玉卑，拜不稽首。","chunks":[["襄王使邵公過及內史過賜晉惠公命，呂甥、郤芮相晉侯不敬，晉侯執玉卑，拜不稽首。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-22_s-2","passageId":"guo-yu_ch-1_p-22","order":2,"canonicalText":"內史過歸，以告王曰：「晉不亡，其君必無後。","chunks":[["內史過歸，以告王曰：「晉不亡，其君必無後。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-22_s-3","passageId":"guo-yu_ch-1_p-22","order":3,"canonicalText":"且呂、郤將不免。","chunks":[["且呂、郤將不免。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-22_s-4","passageId":"guo-yu_ch-1_p-22","order":4,"canonicalText":"」王曰：「何故？","chunks":[["」王曰：「何故？","zh-Hant"]]},{"id":"guo-yu_ch-1_p-22_s-5","passageId":"guo-yu_ch-1_p-22","order":5,"canonicalText":"」對曰：「《》有之曰：『眾非元後，何戴？","chunks":[["」對曰：「《》有之曰：『眾非元後，何戴？","zh-Hant"]]},{"id":"guo-yu_ch-1_p-22_s-6","passageId":"guo-yu_ch-1_p-22","order":6,"canonicalText":"後非眾，無與守邦。","chunks":[["後非眾，無與守邦。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-22_s-7","passageId":"guo-yu_ch-1_p-22","order":7,"canonicalText":"』在《》曰：『餘一人有罪，無以萬夫；","chunks":[["』在《》曰：『餘一人有罪，無以萬夫；","zh-Hant"]]},{"id":"guo-yu_ch-1_p-22_s-8","passageId":"guo-yu_ch-1_p-22","order":8,"canonicalText":"萬夫有罪，在餘一人。","chunks":[["萬夫有罪，在餘一人。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-22_s-9","passageId":"guo-yu_ch-1_p-22","order":9,"canonicalText":"』在《》曰：『國之臧，則惟女眾。","chunks":[["』在《》曰：『國之臧，則惟女眾。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-22_s-10","passageId":"guo-yu_ch-1_p-22","order":10,"canonicalText":"國之不臧，則惟餘一人，是有逸罰。","chunks":[["國之不臧，則惟餘一人，是有逸罰。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-22_s-11","passageId":"guo-yu_ch-1_p-22","order":11,"canonicalText":"』如是則長眾使民，不可不慎也。","chunks":[["』如是則長眾使民，不可不慎也。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-22_s-12","passageId":"guo-yu_ch-1_p-22","order":12,"canonicalText":"民之所急在大事，先王知大事之必以眾濟也，是故祓除其心，以和惠民。","chunks":[["民之所急在大事，先王知大事之必以眾濟也，是故祓除其心，以和惠民。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-22_s-13","passageId":"guo-yu_ch-1_p-22","order":13,"canonicalText":"考中度衷以蒞之，昭明物則以訓之，制義庶孚以行之。","chunks":[["考中度衷以蒞之，昭明物則以訓之，制義庶孚以行之。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-22_s-14","passageId":"guo-yu_ch-1_p-22","order":14,"canonicalText":"祓除其心，精也；","chunks":[["祓除其心，精也；","zh-Hant"]]},{"id":"guo-yu_ch-1_p-22_s-15","passageId":"guo-yu_ch-1_p-22","order":15,"canonicalText":"考中度衷，忠也；","chunks":[["考中度衷，忠也；","zh-Hant"]]},{"id":"guo-yu_ch-1_p-22_s-16","passageId":"guo-yu_ch-1_p-22","order":16,"canonicalText":"昭明物則，禮也；","chunks":[["昭明物則，禮也；","zh-Hant"]]},{"id":"guo-yu_ch-1_p-22_s-17","passageId":"guo-yu_ch-1_p-22","order":17,"canonicalText":"制義庶孚，信也。","chunks":[["制義庶孚，信也。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-22_s-18","passageId":"guo-yu_ch-1_p-22","order":18,"canonicalText":"然則長眾使民之道，非精不和，非忠不立，非禮不順，非信不行。","chunks":[["然則長眾使民之道，非精不和，非忠不立，非禮不順，非信不行。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-22_s-19","passageId":"guo-yu_ch-1_p-22","order":19,"canonicalText":"今晉侯即位而背外內之賂，虐其處者，棄其信也；","chunks":[["今晉侯即位而背外內之賂，虐其處者，棄其信也；","zh-Hant"]]},{"id":"guo-yu_ch-1_p-22_s-20","passageId":"guo-yu_ch-1_p-22","order":20,"canonicalText":"不敬王命，棄其禮也；","chunks":[["不敬王命，棄其禮也；","zh-Hant"]]},{"id":"guo-yu_ch-1_p-22_s-21","passageId":"guo-yu_ch-1_p-22","order":21,"canonicalText":"施其所惡，棄其忠也；","chunks":[["施其所惡，棄其忠也；","zh-Hant"]]},{"id":"guo-yu_ch-1_p-22_s-22","passageId":"guo-yu_ch-1_p-22","order":22,"canonicalText":"以惡實心，棄其精也。","chunks":[["以惡實心，棄其精也。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-22_s-23","passageId":"guo-yu_ch-1_p-22","order":23,"canonicalText":"四者皆棄，則遠不至而近不和矣，將何以守國？","chunks":[["四者皆棄，則遠不至而近不和矣，將何以守國？","zh-Hant"]]},{"id":"guo-yu_ch-1_p-23_s-1","passageId":"guo-yu_ch-1_p-23","order":1,"canonicalText":"「古者，先王既有天下，又崇立上帝、明神而敬事之，於是乎有朝日、夕月以教民事君。","chunks":[["「古者，先王既有天下，又崇立上帝、明神而敬事之，於是乎有朝日、夕月以教民事君。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-23_s-2","passageId":"guo-yu_ch-1_p-23","order":2,"canonicalText":"諸侯春秋受職於王以臨其民，大夫、士日恪位著以儆其官，庶人、工、商各守其業以共其上。","chunks":[["諸侯春秋受職於王以臨其民，大夫、士日恪位著以儆其官，庶人、工、商各守其業以共其上。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-23_s-3","passageId":"guo-yu_ch-1_p-23","order":3,"canonicalText":"猶恐其有墜失也，故為車服、旗章以旌之，為贄幣、瑞節以鎮之，為班爵、貴賤以列之，為令聞嘉譽以聲之。","chunks":[["猶恐其有墜失也，故為車服、旗章以旌之，為贄幣、瑞節以鎮之，為班爵、貴賤以列之，為令聞嘉譽以聲之。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-23_s-4","passageId":"guo-yu_ch-1_p-23","order":4,"canonicalText":"猶有散、遷、懈慢而著在刑辟，流在裔土，於是乎有蠻、夷之國，有斧鉞、刀墨之民，而況可以淫縱其身乎？","chunks":[["猶有散、遷、懈慢而著在刑辟，流在裔土，於是乎有蠻、夷之國，有斧鉞、刀墨之民，而況可以淫縱其身乎？","zh-Hant"]]},{"id":"guo-yu_ch-1_p-24_s-1","passageId":"guo-yu_ch-1_p-24","order":1,"canonicalText":"「夫晉侯非嗣也，而得其位，亹亹怵惕，保任戒懼，猶曰未也。","chunks":[["「夫晉侯非嗣也，而得其位，亹亹怵惕，保任戒懼，猶曰未也。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-24_s-2","passageId":"guo-yu_ch-1_p-24","order":2,"canonicalText":"若將廣其心而遠其鄰，陵其民而卑其上，將何以固守？","chunks":[["若將廣其心而遠其鄰，陵其民而卑其上，將何以固守？","zh-Hant"]]},{"id":"guo-yu_ch-1_p-25_s-1","passageId":"guo-yu_ch-1_p-25","order":1,"canonicalText":"「夫執玉卑，替其贄也；","chunks":[["「夫執玉卑，替其贄也；","zh-Hant"]]},{"id":"guo-yu_ch-1_p-25_s-2","passageId":"guo-yu_ch-1_p-25","order":2,"canonicalText":"拜不稽首，誣其王也。","chunks":[["拜不稽首，誣其王也。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-25_s-3","passageId":"guo-yu_ch-1_p-25","order":3,"canonicalText":"替贄無鎮，誣王無民。","chunks":[["替贄無鎮，誣王無民。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-25_s-4","passageId":"guo-yu_ch-1_p-25","order":4,"canonicalText":"夫天事恆象，任重享大者必速及，故晉侯誣王，人亦將誣之；","chunks":[["夫天事恆象，任重享大者必速及，故晉侯誣王，人亦將誣之；","zh-Hant"]]},{"id":"guo-yu_ch-1_p-25_s-5","passageId":"guo-yu_ch-1_p-25","order":5,"canonicalText":"欲替其鎮，人亦將替之。","chunks":[["欲替其鎮，人亦將替之。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-25_s-6","passageId":"guo-yu_ch-1_p-25","order":6,"canonicalText":"大臣享其祿，弗諫而阿之，亦必及焉。","chunks":[["大臣享其祿，弗諫而阿之，亦必及焉。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-25_s-7","passageId":"guo-yu_ch-1_p-25","order":7,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"guo-yu_ch-1_p-26_s-1","passageId":"guo-yu_ch-1_p-26","order":1,"canonicalText":"襄王三年而立晉侯，八年而隕於韓，十六年而晉人殺懷公。","chunks":[["襄王三年而立晉侯，八年而隕於韓，十六年而晉人殺懷公。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-26_s-2","passageId":"guo-yu_ch-1_p-26","order":2,"canonicalText":"懷公無胄，秦人殺子金、子公。","chunks":[["懷公無胄，秦人殺子金、子公。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-27_s-1","passageId":"guo-yu_ch-1_p-27","order":1,"canonicalText":"襄王使太宰文公及內史興賜晉文公命，上卿逆於境，晉侯郊勞，館諸宗廟，饋九牢，設庭燎。","chunks":[["襄王使太宰文公及內史興賜晉文公命，上卿逆於境，晉侯郊勞，館諸宗廟，饋九牢，設庭燎。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-27_s-2","passageId":"guo-yu_ch-1_p-27","order":2,"canonicalText":"及期命於武宮，設桑主，布幾筵，太宰蒞之，晉侯端委以入。","chunks":[["及期命於武宮，設桑主，布幾筵，太宰蒞之，晉侯端委以入。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-27_s-3","passageId":"guo-yu_ch-1_p-27","order":3,"canonicalText":"太宰以王命命冕服，內史贊之，三命而後即冕服。","chunks":[["太宰以王命命冕服，內史贊之，三命而後即冕服。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-27_s-4","passageId":"guo-yu_ch-1_p-27","order":4,"canonicalText":"既畢，賓、饗、贈、餞如公命侯伯之禮，而加之以宴好。","chunks":[["既畢，賓、饗、贈、餞如公命侯伯之禮，而加之以宴好。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-27_s-5","passageId":"guo-yu_ch-1_p-27","order":5,"canonicalText":"內史興歸，以告王曰：「晉，不可不善也。","chunks":[["內史興歸，以告王曰：「晉，不可不善也。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-27_s-6","passageId":"guo-yu_ch-1_p-27","order":6,"canonicalText":"其君必霸，逆王命敬，奉禮義成。","chunks":[["其君必霸，逆王命敬，奉禮義成。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-27_s-7","passageId":"guo-yu_ch-1_p-27","order":7,"canonicalText":"敬王命，順之道也；","chunks":[["敬王命，順之道也；","zh-Hant"]]},{"id":"guo-yu_ch-1_p-27_s-8","passageId":"guo-yu_ch-1_p-27","order":8,"canonicalText":"成禮義，德之則也。","chunks":[["成禮義，德之則也。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-27_s-9","passageId":"guo-yu_ch-1_p-27","order":9,"canonicalText":"則德以導諸侯，諸侯必歸之。","chunks":[["則德以導諸侯，諸侯必歸之。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-27_s-10","passageId":"guo-yu_ch-1_p-27","order":10,"canonicalText":"且禮所以觀忠、信、仁、義也，忠所以分也，仁所以行也，信所以守也，義所以節也。","chunks":[["且禮所以觀忠、信、仁、義也，忠所以分也，仁所以行也，信所以守也，義所以節也。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-27_s-11","passageId":"guo-yu_ch-1_p-27","order":11,"canonicalText":"忠分則均，仁行則報，信守則固，義節則度。","chunks":[["忠分則均，仁行則報，信守則固，義節則度。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-27_s-12","passageId":"guo-yu_ch-1_p-27","order":12,"canonicalText":"分均無怨，行報無匱，守固不偷，節度不攜。","chunks":[["分均無怨，行報無匱，守固不偷，節度不攜。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-27_s-13","passageId":"guo-yu_ch-1_p-27","order":13,"canonicalText":"若民不怨而財不匱，令不偷而動不攜，其何事不濟！","chunks":[["若民不怨而財不匱，令不偷而動不攜，其何事不濟！","zh-Hant"]]},{"id":"guo-yu_ch-1_p-27_s-14","passageId":"guo-yu_ch-1_p-27","order":14,"canonicalText":"中能應外，忠也；","chunks":[["中能應外，忠也；","zh-Hant"]]},{"id":"guo-yu_ch-1_p-27_s-15","passageId":"guo-yu_ch-1_p-27","order":15,"canonicalText":"施三服義，仁也；","chunks":[["施三服義，仁也；","zh-Hant"]]},{"id":"guo-yu_ch-1_p-27_s-16","passageId":"guo-yu_ch-1_p-27","order":16,"canonicalText":"守節不淫，信也，行禮不疚，義也。","chunks":[["守節不淫，信也，行禮不疚，義也。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-27_s-17","passageId":"guo-yu_ch-1_p-27","order":17,"canonicalText":"臣入晉境，四者不失，臣故曰：『晉侯其能禮矣，王其善之！","chunks":[["臣入晉境，四者不失，臣故曰：『晉侯其能禮矣，王其善之！","zh-Hant"]]},{"id":"guo-yu_ch-1_p-27_s-18","passageId":"guo-yu_ch-1_p-27","order":18,"canonicalText":"』樹於有禮，艾人必豐。","chunks":[["』樹於有禮，艾人必豐。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-27_s-19","passageId":"guo-yu_ch-1_p-27","order":19,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"guo-yu_ch-1_p-28_s-1","passageId":"guo-yu_ch-1_p-28","order":1,"canonicalText":"王從之，使於晉者，道相逮也。","chunks":[["王從之，使於晉者，道相逮也。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-28_s-2","passageId":"guo-yu_ch-1_p-28","order":2,"canonicalText":"及惠後之難，王出在鄭，晉侯納之。","chunks":[["及惠後之難，王出在鄭，晉侯納之。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-29_s-1","passageId":"guo-yu_ch-1_p-29","order":1,"canonicalText":"襄王十六年，立晉文公。","chunks":[["襄王十六年，立晉文公。","zh-Hant"]]},{"id":"guo-yu_ch-1_p-29_s-2","passageId":"guo-yu_ch-1_p-29","order":2,"canonicalText":"二十一年，以諸侯朝王于衡雍，且獻楚捷，遂為踐土之盟，於是乎始霸。","chunks":[["二十一年，以諸侯朝王于衡雍，且獻楚捷，遂為踐土之盟，於是乎始霸。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-1_s-1","passageId":"guo-yu_ch-2_p-1","order":1,"canonicalText":"襄王十三年，鄭人伐滑。","chunks":[["襄王十三年，鄭人伐滑。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-1_s-2","passageId":"guo-yu_ch-2_p-1","order":2,"canonicalText":"王使遊孫伯請滑，鄭人執之。","chunks":[["王使遊孫伯請滑，鄭人執之。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-1_s-3","passageId":"guo-yu_ch-2_p-1","order":3,"canonicalText":"王怒，將以狄伐鄭。","chunks":[["王怒，將以狄伐鄭。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-1_s-4","passageId":"guo-yu_ch-2_p-1","order":4,"canonicalText":"富辰諫曰：「不可。","chunks":[["富辰諫曰：「不可。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-1_s-5","passageId":"guo-yu_ch-2_p-1","order":5,"canonicalText":"古人有言曰：『兄弟讒鬩、侮人百里。","chunks":[["古人有言曰：『兄弟讒鬩、侮人百里。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-1_s-6","passageId":"guo-yu_ch-2_p-1","order":6,"canonicalText":"』周文公之詩曰：『兄弟鬩於墻，外禦其侮。","chunks":[["』周文公之詩曰：『兄弟鬩於墻，外禦其侮。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-1_s-7","passageId":"guo-yu_ch-2_p-1","order":7,"canonicalText":"』若是則鬩乃內侮，而雖鬩不敗親也。","chunks":[["』若是則鬩乃內侮，而雖鬩不敗親也。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-1_s-8","passageId":"guo-yu_ch-2_p-1","order":8,"canonicalText":"鄭在天子，兄弟也。","chunks":[["鄭在天子，兄弟也。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-1_s-9","passageId":"guo-yu_ch-2_p-1","order":9,"canonicalText":"鄭武、莊有大勛力於平、桓；","chunks":[["鄭武、莊有大勛力於平、桓；","zh-Hant"]]},{"id":"guo-yu_ch-2_p-1_s-10","passageId":"guo-yu_ch-2_p-1","order":10,"canonicalText":"我周之東遷，晉、鄭是依；","chunks":[["我周之東遷，晉、鄭是依；","zh-Hant"]]},{"id":"guo-yu_ch-2_p-1_s-11","passageId":"guo-yu_ch-2_p-1","order":11,"canonicalText":"子頹之亂，又鄭之繇定。","chunks":[["子頹之亂，又鄭之繇定。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-1_s-12","passageId":"guo-yu_ch-2_p-1","order":12,"canonicalText":"今以小忿棄之，是以小怨置大德也，無乃不可乎！","chunks":[["今以小忿棄之，是以小怨置大德也，無乃不可乎！","zh-Hant"]]},{"id":"guo-yu_ch-2_p-1_s-13","passageId":"guo-yu_ch-2_p-1","order":13,"canonicalText":"且夫兄弟之怨，不徵於他，徵於他，利乃外矣。","chunks":[["且夫兄弟之怨，不徵於他，徵於他，利乃外矣。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-1_s-14","passageId":"guo-yu_ch-2_p-1","order":14,"canonicalText":"章怨外利，不義；","chunks":[["章怨外利，不義；","zh-Hant"]]},{"id":"guo-yu_ch-2_p-1_s-15","passageId":"guo-yu_ch-2_p-1","order":15,"canonicalText":"棄親即狄，不祥；","chunks":[["棄親即狄，不祥；","zh-Hant"]]},{"id":"guo-yu_ch-2_p-1_s-16","passageId":"guo-yu_ch-2_p-1","order":16,"canonicalText":"以怨報德，不仁。","chunks":[["以怨報德，不仁。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-1_s-17","passageId":"guo-yu_ch-2_p-1","order":17,"canonicalText":"夫義所以生利也，祥所以事神也，仁所以保民也。","chunks":[["夫義所以生利也，祥所以事神也，仁所以保民也。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-1_s-18","passageId":"guo-yu_ch-2_p-1","order":18,"canonicalText":"不義則利不阜，不祥則福不降，不仁則民不至。","chunks":[["不義則利不阜，不祥則福不降，不仁則民不至。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-1_s-19","passageId":"guo-yu_ch-2_p-1","order":19,"canonicalText":"古之明王不失此三德者，故能光有天下，而和寧百姓，令聞不忘。","chunks":[["古之明王不失此三德者，故能光有天下，而和寧百姓，令聞不忘。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-1_s-20","passageId":"guo-yu_ch-2_p-1","order":20,"canonicalText":"王其不可以棄之。","chunks":[["王其不可以棄之。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-1_s-21","passageId":"guo-yu_ch-2_p-1","order":21,"canonicalText":"」王不聽。","chunks":[["」王不聽。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-1_s-22","passageId":"guo-yu_ch-2_p-1","order":22,"canonicalText":"十七年，王降狄師以伐鄭。","chunks":[["十七年，王降狄師以伐鄭。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-2_s-1","passageId":"guo-yu_ch-2_p-2","order":1,"canonicalText":"王德狄人，將以其女為後。","chunks":[["王德狄人，將以其女為後。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-2_s-2","passageId":"guo-yu_ch-2_p-2","order":2,"canonicalText":"富辰諫曰：「不可。","chunks":[["富辰諫曰：「不可。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-2_s-3","passageId":"guo-yu_ch-2_p-2","order":3,"canonicalText":"夫婚姻，禍福之階也。","chunks":[["夫婚姻，禍福之階也。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-2_s-4","passageId":"guo-yu_ch-2_p-2","order":4,"canonicalText":"由之利內則福，利外則取禍。","chunks":[["由之利內則福，利外則取禍。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-2_s-5","passageId":"guo-yu_ch-2_p-2","order":5,"canonicalText":"今王外利矣，其無乃階禍乎？","chunks":[["今王外利矣，其無乃階禍乎？","zh-Hant"]]},{"id":"guo-yu_ch-2_p-2_s-6","passageId":"guo-yu_ch-2_p-2","order":6,"canonicalText":"昔摯、疇之國也由大任，杞、繒由大姒，齊、許、申、呂由大姜，陳由大姬，是皆能內利親親者也。","chunks":[["昔摯、疇之國也由大任，杞、繒由大姒，齊、許、申、呂由大姜，陳由大姬，是皆能內利親親者也。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-2_s-7","passageId":"guo-yu_ch-2_p-2","order":7,"canonicalText":"昔鄢之亡也由仲任，密須由伯姞，鄶由叔妘，聃由鄭姬，息由陳媯，鄧由楚曼，羅由季姬，盧由荊媯，是皆外利離親者也。","chunks":[["昔鄢之亡也由仲任，密須由伯姞，鄶由叔妘，聃由鄭姬，息由陳媯，鄧由楚曼，羅由季姬，盧由荊媯，是皆外利離親者也。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-2_s-8","passageId":"guo-yu_ch-2_p-2","order":8,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"guo-yu_ch-2_p-3_s-1","passageId":"guo-yu_ch-2_p-3","order":1,"canonicalText":"王曰：「利何如而內，何如而外？","chunks":[["王曰：「利何如而內，何如而外？","zh-Hant"]]},{"id":"guo-yu_ch-2_p-3_s-2","passageId":"guo-yu_ch-2_p-3","order":2,"canonicalText":"」對曰：「尊貴、明賢、庸勛、長老、愛親、禮新、親舊。","chunks":[["」對曰：「尊貴、明賢、庸勛、長老、愛親、禮新、親舊。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-3_s-3","passageId":"guo-yu_ch-2_p-3","order":3,"canonicalText":"然則民莫不審固其心力以役上令，官不易方，而財不匱竭，求無不至，動無不濟。","chunks":[["然則民莫不審固其心力以役上令，官不易方，而財不匱竭，求無不至，動無不濟。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-3_s-4","passageId":"guo-yu_ch-2_p-3","order":4,"canonicalText":"百姓兆民，夫人奉利而歸諸上，是利之內也，若七德離判，民乃攜貳，各以利退，上求不暨，是其外利也。","chunks":[["百姓兆民，夫人奉利而歸諸上，是利之內也，若七德離判，民乃攜貳，各以利退，上求不暨，是其外利也。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-3_s-5","passageId":"guo-yu_ch-2_p-3","order":5,"canonicalText":"夫狄無列於王室，鄭伯南也，王而卑之，是不尊貴也。","chunks":[["夫狄無列於王室，鄭伯南也，王而卑之，是不尊貴也。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-3_s-6","passageId":"guo-yu_ch-2_p-3","order":6,"canonicalText":"狄，豺狼之德也，鄭未失周典，王而蔑之，是不明賢也。","chunks":[["狄，豺狼之德也，鄭未失周典，王而蔑之，是不明賢也。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-3_s-7","passageId":"guo-yu_ch-2_p-3","order":7,"canonicalText":"平、桓、莊、惠皆受鄭勞，王而棄之，是不庸勛也。","chunks":[["平、桓、莊、惠皆受鄭勞，王而棄之，是不庸勛也。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-3_s-8","passageId":"guo-yu_ch-2_p-3","order":8,"canonicalText":"鄭伯捷之齒長矣，王而弱之，是不長老也。","chunks":[["鄭伯捷之齒長矣，王而弱之，是不長老也。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-3_s-9","passageId":"guo-yu_ch-2_p-3","order":9,"canonicalText":"狄，隗姓也，鄭出自宣王，王而虐之，是不愛親也。","chunks":[["狄，隗姓也，鄭出自宣王，王而虐之，是不愛親也。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-3_s-10","passageId":"guo-yu_ch-2_p-3","order":10,"canonicalText":"夫禮，新不間舊，王以狄女間姜、任，非禮且棄舊也。","chunks":[["夫禮，新不間舊，王以狄女間姜、任，非禮且棄舊也。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-3_s-11","passageId":"guo-yu_ch-2_p-3","order":11,"canonicalText":"王一舉而棄七德，臣故曰利外矣。","chunks":[["王一舉而棄七德，臣故曰利外矣。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-3_s-12","passageId":"guo-yu_ch-2_p-3","order":12,"canonicalText":"《》有之曰：『必有忍也，若能有濟也。","chunks":[["《》有之曰：『必有忍也，若能有濟也。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-3_s-13","passageId":"guo-yu_ch-2_p-3","order":13,"canonicalText":"』王不忍小忿而棄鄭，又登叔隗以階狄。","chunks":[["』王不忍小忿而棄鄭，又登叔隗以階狄。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-3_s-14","passageId":"guo-yu_ch-2_p-3","order":14,"canonicalText":"狄，封豕豺狼也，不可厭也。","chunks":[["狄，封豕豺狼也，不可厭也。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-3_s-15","passageId":"guo-yu_ch-2_p-3","order":15,"canonicalText":"」王不聽。","chunks":[["」王不聽。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-4_s-1","passageId":"guo-yu_ch-2_p-4","order":1,"canonicalText":"十八年，王黜狄後。","chunks":[["十八年，王黜狄後。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-4_s-2","passageId":"guo-yu_ch-2_p-4","order":2,"canonicalText":"狄人來誅殺譚伯。","chunks":[["狄人來誅殺譚伯。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-4_s-3","passageId":"guo-yu_ch-2_p-4","order":3,"canonicalText":"富辰曰：「昔吾驟諫王，王弗從，以及此難。","chunks":[["富辰曰：「昔吾驟諫王，王弗從，以及此難。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-4_s-4","passageId":"guo-yu_ch-2_p-4","order":4,"canonicalText":"若我不出，王其以我為懟乎！","chunks":[["若我不出，王其以我為懟乎！","zh-Hant"]]},{"id":"guo-yu_ch-2_p-4_s-5","passageId":"guo-yu_ch-2_p-4","order":5,"canonicalText":"」乃以其屬死之。","chunks":[["」乃以其屬死之。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-5_s-1","passageId":"guo-yu_ch-2_p-5","order":1,"canonicalText":"初，惠後欲立王子帶，故以其黨啟狄人。","chunks":[["初，惠後欲立王子帶，故以其黨啟狄人。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-5_s-2","passageId":"guo-yu_ch-2_p-5","order":2,"canonicalText":"狄人遂入，周王乃出居於鄭，晉文公納之。","chunks":[["狄人遂入，周王乃出居於鄭，晉文公納之。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-6_s-1","passageId":"guo-yu_ch-2_p-6","order":1,"canonicalText":"晉文公既定襄王於郟，王勞之以地，辭，請隧焉。","chunks":[["晉文公既定襄王於郟，王勞之以地，辭，請隧焉。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-6_s-2","passageId":"guo-yu_ch-2_p-6","order":2,"canonicalText":"王不許，曰：「昔我先王之有天下也，規方千里以為甸服，以供上帝山川百神之祀，以備百姓兆民之用，以待不庭不虞之患。","chunks":[["王不許，曰：「昔我先王之有天下也，規方千里以為甸服，以供上帝山川百神之祀，以備百姓兆民之用，以待不庭不虞之患。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-6_s-3","passageId":"guo-yu_ch-2_p-6","order":3,"canonicalText":"其餘以均分公侯伯子男，使各有寧宇，以順及天地，無逢其災害，先王豈有賴焉。","chunks":[["其餘以均分公侯伯子男，使各有寧宇，以順及天地，無逢其災害，先王豈有賴焉。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-6_s-4","passageId":"guo-yu_ch-2_p-6","order":4,"canonicalText":"內官不過九御，外官不過九品，足以供給神祇而已，豈敢厭縱其耳目心腹以亂百度？","chunks":[["內官不過九御，外官不過九品，足以供給神祇而已，豈敢厭縱其耳目心腹以亂百度？","zh-Hant"]]},{"id":"guo-yu_ch-2_p-6_s-5","passageId":"guo-yu_ch-2_p-6","order":5,"canonicalText":"亦唯是死生之服物採章，以臨長百姓而輕重布之，王何異之有？","chunks":[["亦唯是死生之服物採章，以臨長百姓而輕重布之，王何異之有？","zh-Hant"]]},{"id":"guo-yu_ch-2_p-6_s-6","passageId":"guo-yu_ch-2_p-6","order":6,"canonicalText":"今天降禍災於周室，餘一人僅亦守府，又不佞以勤叔父，而班先王之大物以賞私德，其叔父實應且憎，以非餘一人，餘一人豈敢有愛？","chunks":[["今天降禍災於周室，餘一人僅亦守府，又不佞以勤叔父，而班先王之大物以賞私德，其叔父實應且憎，以非餘一人，餘一人豈敢有愛？","zh-Hant"]]},{"id":"guo-yu_ch-2_p-6_s-7","passageId":"guo-yu_ch-2_p-6","order":7,"canonicalText":"先民有言曰：『改玉改行。","chunks":[["先民有言曰：『改玉改行。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-6_s-8","passageId":"guo-yu_ch-2_p-6","order":8,"canonicalText":"』叔父若能光裕大德，更姓改物，以創制天下，自顯庸也，而縮取備物以鎮撫百姓，餘一人其流闢旅於裔土，何辭之有與？","chunks":[["』叔父若能光裕大德，更姓改物，以創制天下，自顯庸也，而縮取備物以鎮撫百姓，餘一人其流闢旅於裔土，何辭之有與？","zh-Hant"]]},{"id":"guo-yu_ch-2_p-6_s-9","passageId":"guo-yu_ch-2_p-6","order":9,"canonicalText":"若由是姬姓也，尚將列為公侯，以復先王之職，大物其未可改也。","chunks":[["若由是姬姓也，尚將列為公侯，以復先王之職，大物其未可改也。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-6_s-10","passageId":"guo-yu_ch-2_p-6","order":10,"canonicalText":"叔父其懋昭明德，物將自至，餘何敢以私勞變前之大章，以忝天下，其若先王與百姓何？","chunks":[["叔父其懋昭明德，物將自至，餘何敢以私勞變前之大章，以忝天下，其若先王與百姓何？","zh-Hant"]]},{"id":"guo-yu_ch-2_p-6_s-11","passageId":"guo-yu_ch-2_p-6","order":11,"canonicalText":"何政令之為也？","chunks":[["何政令之為也？","zh-Hant"]]},{"id":"guo-yu_ch-2_p-6_s-12","passageId":"guo-yu_ch-2_p-6","order":12,"canonicalText":"若不然，叔父有地而隧焉，餘安能知之？","chunks":[["若不然，叔父有地而隧焉，餘安能知之？","zh-Hant"]]},{"id":"guo-yu_ch-2_p-6_s-13","passageId":"guo-yu_ch-2_p-6","order":13,"canonicalText":"」文公遂不敢請，受地而還。","chunks":[["」文公遂不敢請，受地而還。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-7_s-1","passageId":"guo-yu_ch-2_p-7","order":1,"canonicalText":"王至自鄭，以陽樊賜晉文公。","chunks":[["王至自鄭，以陽樊賜晉文公。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-7_s-2","passageId":"guo-yu_ch-2_p-7","order":2,"canonicalText":"陽人不服，晉侯圍之。","chunks":[["陽人不服，晉侯圍之。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-7_s-3","passageId":"guo-yu_ch-2_p-7","order":3,"canonicalText":"倉葛呼曰：「王以晉君為能德，故勞之以陽樊，陽樊懷我王德，是以未從於晉。","chunks":[["倉葛呼曰：「王以晉君為能德，故勞之以陽樊，陽樊懷我王德，是以未從於晉。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-7_s-4","passageId":"guo-yu_ch-2_p-7","order":4,"canonicalText":"謂君其何德之布以懷柔之，使無有遠志？","chunks":[["謂君其何德之布以懷柔之，使無有遠志？","zh-Hant"]]},{"id":"guo-yu_ch-2_p-7_s-5","passageId":"guo-yu_ch-2_p-7","order":5,"canonicalText":"今將大泯其宗祊，而蔑殺其民人，宜吾不敢服也！","chunks":[["今將大泯其宗祊，而蔑殺其民人，宜吾不敢服也！","zh-Hant"]]},{"id":"guo-yu_ch-2_p-7_s-6","passageId":"guo-yu_ch-2_p-7","order":6,"canonicalText":"夫三軍之所尋，將蠻、夷、戎、狄之驕逸不虔，於是乎致武。","chunks":[["夫三軍之所尋，將蠻、夷、戎、狄之驕逸不虔，於是乎致武。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-7_s-7","passageId":"guo-yu_ch-2_p-7","order":7,"canonicalText":"此羸者陽也，未狎君政，故未承命。","chunks":[["此羸者陽也，未狎君政，故未承命。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-7_s-8","passageId":"guo-yu_ch-2_p-7","order":8,"canonicalText":"君若惠及之，唯官是徵，其敢逆命，何足以辱師！","chunks":[["君若惠及之，唯官是徵，其敢逆命，何足以辱師！","zh-Hant"]]},{"id":"guo-yu_ch-2_p-7_s-9","passageId":"guo-yu_ch-2_p-7","order":9,"canonicalText":"君之武震，無乃玩而頓乎？","chunks":[["君之武震，無乃玩而頓乎？","zh-Hant"]]},{"id":"guo-yu_ch-2_p-7_s-10","passageId":"guo-yu_ch-2_p-7","order":10,"canonicalText":"臣聞之曰：『武不可覿，文不可匿。","chunks":[["臣聞之曰：『武不可覿，文不可匿。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-7_s-11","passageId":"guo-yu_ch-2_p-7","order":11,"canonicalText":"覿武無烈，匿文不昭。","chunks":[["覿武無烈，匿文不昭。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-7_s-12","passageId":"guo-yu_ch-2_p-7","order":12,"canonicalText":"』陽不承獲甸，而祗以覿武，臣是以懼。","chunks":[["』陽不承獲甸，而祗以覿武，臣是以懼。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-7_s-13","passageId":"guo-yu_ch-2_p-7","order":13,"canonicalText":"不然，其敢自愛也？","chunks":[["不然，其敢自愛也？","zh-Hant"]]},{"id":"guo-yu_ch-2_p-7_s-14","passageId":"guo-yu_ch-2_p-7","order":14,"canonicalText":"且夫陽，豈有裔民哉？","chunks":[["且夫陽，豈有裔民哉？","zh-Hant"]]},{"id":"guo-yu_ch-2_p-7_s-15","passageId":"guo-yu_ch-2_p-7","order":15,"canonicalText":"夫亦皆天子之父兄甥舅也，若之何其虐之也？","chunks":[["夫亦皆天子之父兄甥舅也，若之何其虐之也？","zh-Hant"]]},{"id":"guo-yu_ch-2_p-7_s-16","passageId":"guo-yu_ch-2_p-7","order":16,"canonicalText":"」晉侯聞之，曰：「是君子之言也。","chunks":[["」晉侯聞之，曰：「是君子之言也。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-7_s-17","passageId":"guo-yu_ch-2_p-7","order":17,"canonicalText":"」乃出陽民。","chunks":[["」乃出陽民。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-8_s-1","passageId":"guo-yu_ch-2_p-8","order":1,"canonicalText":"溫之會，晉人執衛成公歸之於周。","chunks":[["溫之會，晉人執衛成公歸之於周。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-8_s-2","passageId":"guo-yu_ch-2_p-8","order":2,"canonicalText":"晉侯請殺之，王曰：「不可。","chunks":[["晉侯請殺之，王曰：「不可。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-8_s-3","passageId":"guo-yu_ch-2_p-8","order":3,"canonicalText":"夫政自上下者也，上作政，而下行之不逆，故上下無怨。","chunks":[["夫政自上下者也，上作政，而下行之不逆，故上下無怨。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-8_s-4","passageId":"guo-yu_ch-2_p-8","order":4,"canonicalText":"今叔父作政而不行，無乃不可乎？","chunks":[["今叔父作政而不行，無乃不可乎？","zh-Hant"]]},{"id":"guo-yu_ch-2_p-8_s-5","passageId":"guo-yu_ch-2_p-8","order":5,"canonicalText":"夫君臣無獄，今元咺雖直，不可聽也。","chunks":[["夫君臣無獄，今元咺雖直，不可聽也。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-8_s-6","passageId":"guo-yu_ch-2_p-8","order":6,"canonicalText":"君臣皆獄，父子將獄，是無上下也。","chunks":[["君臣皆獄，父子將獄，是無上下也。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-8_s-7","passageId":"guo-yu_ch-2_p-8","order":7,"canonicalText":"而叔父聽之，一逆矣。","chunks":[["而叔父聽之，一逆矣。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-8_s-8","passageId":"guo-yu_ch-2_p-8","order":8,"canonicalText":"又為臣殺其君，其安庸刑？","chunks":[["又為臣殺其君，其安庸刑？","zh-Hant"]]},{"id":"guo-yu_ch-2_p-8_s-9","passageId":"guo-yu_ch-2_p-8","order":9,"canonicalText":"布刑而不庸，再逆矣。","chunks":[["布刑而不庸，再逆矣。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-8_s-10","passageId":"guo-yu_ch-2_p-8","order":10,"canonicalText":"一合諸侯，而有再逆政，餘懼其無後。","chunks":[["一合諸侯，而有再逆政，餘懼其無後。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-8_s-11","passageId":"guo-yu_ch-2_p-8","order":11,"canonicalText":"不然，餘何私於衛侯？","chunks":[["不然，餘何私於衛侯？","zh-Hant"]]},{"id":"guo-yu_ch-2_p-8_s-12","passageId":"guo-yu_ch-2_p-8","order":12,"canonicalText":"」晉人乃歸衛侯。","chunks":[["」晉人乃歸衛侯。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-9_s-1","passageId":"guo-yu_ch-2_p-9","order":1,"canonicalText":"二十四年，秦師將襲鄭，過周北門。","chunks":[["二十四年，秦師將襲鄭，過周北門。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-9_s-2","passageId":"guo-yu_ch-2_p-9","order":2,"canonicalText":"左右皆免冑而下拜，超乘者三百乘。","chunks":[["左右皆免冑而下拜，超乘者三百乘。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-9_s-3","passageId":"guo-yu_ch-2_p-9","order":3,"canonicalText":"王孫滿觀之，言於王曰：「秦師必有謫。","chunks":[["王孫滿觀之，言於王曰：「秦師必有謫。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-9_s-4","passageId":"guo-yu_ch-2_p-9","order":4,"canonicalText":"」王曰：「何故？","chunks":[["」王曰：「何故？","zh-Hant"]]},{"id":"guo-yu_ch-2_p-9_s-5","passageId":"guo-yu_ch-2_p-9","order":5,"canonicalText":"」對曰：「師輕而驕，輕則寡謀，驕則無禮。","chunks":[["」對曰：「師輕而驕，輕則寡謀，驕則無禮。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-9_s-6","passageId":"guo-yu_ch-2_p-9","order":6,"canonicalText":"無禮則脫，寡謀自陷。","chunks":[["無禮則脫，寡謀自陷。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-9_s-7","passageId":"guo-yu_ch-2_p-9","order":7,"canonicalText":"入險而脫，能無敗乎？","chunks":[["入險而脫，能無敗乎？","zh-Hant"]]},{"id":"guo-yu_ch-2_p-9_s-8","passageId":"guo-yu_ch-2_p-9","order":8,"canonicalText":"秦師無謫，是道廢也。","chunks":[["秦師無謫，是道廢也。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-9_s-9","passageId":"guo-yu_ch-2_p-9","order":9,"canonicalText":"」是行也，秦師還，晉人敗諸崤，獲其三帥丙、術、視。","chunks":[["」是行也，秦師還，晉人敗諸崤，獲其三帥丙、術、視。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-10_s-1","passageId":"guo-yu_ch-2_p-10","order":1,"canonicalText":"晉侯使隨會聘於周，定王享之餚烝，原公相禮。","chunks":[["晉侯使隨會聘於周，定王享之餚烝，原公相禮。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-10_s-2","passageId":"guo-yu_ch-2_p-10","order":2,"canonicalText":"範子私於原公，曰：「吾聞王室之禮無毀折，今此何禮也？","chunks":[["範子私於原公，曰：「吾聞王室之禮無毀折，今此何禮也？","zh-Hant"]]},{"id":"guo-yu_ch-2_p-10_s-3","passageId":"guo-yu_ch-2_p-10","order":3,"canonicalText":"」王見其語，召原公而問之，原公以告。","chunks":[["」王見其語，召原公而問之，原公以告。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-11_s-1","passageId":"guo-yu_ch-2_p-11","order":1,"canonicalText":"王召士季，曰：「子弗聞乎，禘郊之事，則有全烝；","chunks":[["王召士季，曰：「子弗聞乎，禘郊之事，則有全烝；","zh-Hant"]]},{"id":"guo-yu_ch-2_p-11_s-2","passageId":"guo-yu_ch-2_p-11","order":2,"canonicalText":"王公立飫，則有房烝；","chunks":[["王公立飫，則有房烝；","zh-Hant"]]},{"id":"guo-yu_ch-2_p-11_s-3","passageId":"guo-yu_ch-2_p-11","order":3,"canonicalText":"親戚宴饗，則有餚烝。","chunks":[["親戚宴饗，則有餚烝。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-11_s-4","passageId":"guo-yu_ch-2_p-11","order":4,"canonicalText":"今女非他也，而叔父使士季實來修舊德，以獎王室。","chunks":[["今女非他也，而叔父使士季實來修舊德，以獎王室。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-11_s-5","passageId":"guo-yu_ch-2_p-11","order":5,"canonicalText":"唯是先王之宴禮，欲以貽女。","chunks":[["唯是先王之宴禮，欲以貽女。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-11_s-6","passageId":"guo-yu_ch-2_p-11","order":6,"canonicalText":"餘一人敢設飫禘焉，忠非親禮，而幹舊職，以亂前好？","chunks":[["餘一人敢設飫禘焉，忠非親禮，而幹舊職，以亂前好？","zh-Hant"]]},{"id":"guo-yu_ch-2_p-11_s-7","passageId":"guo-yu_ch-2_p-11","order":7,"canonicalText":"且唯戎、狄則有體薦。","chunks":[["且唯戎、狄則有體薦。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-11_s-8","passageId":"guo-yu_ch-2_p-11","order":8,"canonicalText":"夫戎、狄，冒沒輕儳，貪而不讓。","chunks":[["夫戎、狄，冒沒輕儳，貪而不讓。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-11_s-9","passageId":"guo-yu_ch-2_p-11","order":9,"canonicalText":"其血氣不治，若禽獸焉。","chunks":[["其血氣不治，若禽獸焉。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-11_s-10","passageId":"guo-yu_ch-2_p-11","order":10,"canonicalText":"其適來班貢，不俟馨香嘉味，故坐諸門外，而使舌人體委與之。","chunks":[["其適來班貢，不俟馨香嘉味，故坐諸門外，而使舌人體委與之。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-11_s-11","passageId":"guo-yu_ch-2_p-11","order":11,"canonicalText":"女今我王室之一二兄弟，以時相見，將和協典禮，以示民訓則，無亦擇其柔嘉，選其馨香，潔其酒醴，品其百籩，修其簠簋，奉其犧象，出其樽彝，陳其鼎俎，凈其巾羃，敬其祓除，體解節折而共飲食之。","chunks":[["女今我王室之一二兄弟，以時相見，將和協典禮，以示民訓則，無亦擇其柔嘉，選其馨香，潔其酒醴，品其百籩，修其簠簋，奉其犧象，出其樽彝，陳其鼎俎，凈其巾羃，敬其祓除，體解節折而共飲食之。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-11_s-12","passageId":"guo-yu_ch-2_p-11","order":12,"canonicalText":"於是乎有折俎加豆，酬幣宴貨，以示容合好，胡有孑然其郊戎、狄也？","chunks":[["於是乎有折俎加豆，酬幣宴貨，以示容合好，胡有孑然其郊戎、狄也？","zh-Hant"]]},{"id":"guo-yu_ch-2_p-12_s-1","passageId":"guo-yu_ch-2_p-12","order":1,"canonicalText":"「夫王公諸侯之有飫也，將以講事成章，建大德、昭大物也，故立成禮烝而已。","chunks":[["「夫王公諸侯之有飫也，將以講事成章，建大德、昭大物也，故立成禮烝而已。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-12_s-2","passageId":"guo-yu_ch-2_p-12","order":2,"canonicalText":"飫以顯物，宴以合好，故歲飫不倦，時宴不淫，月會、旬修，日完不忘。","chunks":[["飫以顯物，宴以合好，故歲飫不倦，時宴不淫，月會、旬修，日完不忘。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-12_s-3","passageId":"guo-yu_ch-2_p-12","order":3,"canonicalText":"服物昭庸，採飾顯明，文章比象，周旋序順，容貌有崇，威儀有則，五味實氣，五色精心，五聲昭德，五義紀宜，飲食可饗，和同可觀，財用可嘉，則順而德建。","chunks":[["服物昭庸，採飾顯明，文章比象，周旋序順，容貌有崇，威儀有則，五味實氣，五色精心，五聲昭德，五義紀宜，飲食可饗，和同可觀，財用可嘉，則順而德建。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-12_s-4","passageId":"guo-yu_ch-2_p-12","order":4,"canonicalText":"古之善禮者，將焉用全烝？","chunks":[["古之善禮者，將焉用全烝？","zh-Hant"]]},{"id":"guo-yu_ch-2_p-12_s-5","passageId":"guo-yu_ch-2_p-12","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"guo-yu_ch-2_p-13_s-1","passageId":"guo-yu_ch-2_p-13","order":1,"canonicalText":"武子遂不敢對而退。","chunks":[["武子遂不敢對而退。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-13_s-2","passageId":"guo-yu_ch-2_p-13","order":2,"canonicalText":"歸乃講聚三代之典禮，於是乎修執秩以為晉法。","chunks":[["歸乃講聚三代之典禮，於是乎修執秩以為晉法。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-14_s-1","passageId":"guo-yu_ch-2_p-14","order":1,"canonicalText":"定王使單襄公聘於宋。","chunks":[["定王使單襄公聘於宋。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-14_s-2","passageId":"guo-yu_ch-2_p-14","order":2,"canonicalText":"遂假道於陳，以聘於楚。","chunks":[["遂假道於陳，以聘於楚。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-14_s-3","passageId":"guo-yu_ch-2_p-14","order":3,"canonicalText":"火朝覿矣，道茀不可行，候不在疆，司空不視途，澤不陂，川不梁，野有庾積，場功未畢，道無列樹，墾田若蓺，膳宰不致餼，司裏不授館，國無寄寓，縣無施捨，民將築臺於夏氏。","chunks":[["火朝覿矣，道茀不可行，候不在疆，司空不視途，澤不陂，川不梁，野有庾積，場功未畢，道無列樹，墾田若蓺，膳宰不致餼，司裏不授館，國無寄寓，縣無施捨，民將築臺於夏氏。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-14_s-4","passageId":"guo-yu_ch-2_p-14","order":4,"canonicalText":"及陳，陳靈公與孔寧、儀行父南冠以如夏氏，留賓不見。","chunks":[["及陳，陳靈公與孔寧、儀行父南冠以如夏氏，留賓不見。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-15_s-1","passageId":"guo-yu_ch-2_p-15","order":1,"canonicalText":"單子歸，告王曰：「陳侯不有大咎，國必亡。","chunks":[["單子歸，告王曰：「陳侯不有大咎，國必亡。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-15_s-2","passageId":"guo-yu_ch-2_p-15","order":2,"canonicalText":"」王曰：「何故？","chunks":[["」王曰：「何故？","zh-Hant"]]},{"id":"guo-yu_ch-2_p-15_s-3","passageId":"guo-yu_ch-2_p-15","order":3,"canonicalText":"」對曰：「夫辰角見而雨畢，天根見而水涸，本見而草木節解，駟見而隕霜，火見而清風戒寒。","chunks":[["」對曰：「夫辰角見而雨畢，天根見而水涸，本見而草木節解，駟見而隕霜，火見而清風戒寒。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-15_s-4","passageId":"guo-yu_ch-2_p-15","order":4,"canonicalText":"故先王之教曰：『雨畢而除道，水涸而成梁，草木節解而備藏，隕霜而冬裘具，清風至而修城郭宮室。","chunks":[["故先王之教曰：『雨畢而除道，水涸而成梁，草木節解而備藏，隕霜而冬裘具，清風至而修城郭宮室。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-15_s-5","passageId":"guo-yu_ch-2_p-15","order":5,"canonicalText":"』故《夏令》曰：『九月除道，十月成梁。","chunks":[["』故《夏令》曰：『九月除道，十月成梁。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-15_s-6","passageId":"guo-yu_ch-2_p-15","order":6,"canonicalText":"』其時儆曰：「收而場功，待而畚梮，營室之中，土功其始，火之初見，期於司裏。","chunks":[["』其時儆曰：「收而場功，待而畚梮，營室之中，土功其始，火之初見，期於司裏。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-15_s-7","passageId":"guo-yu_ch-2_p-15","order":7,"canonicalText":"『此先王所以不用財賄，而廣施德於天下者也。","chunks":[["『此先王所以不用財賄，而廣施德於天下者也。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-15_s-8","passageId":"guo-yu_ch-2_p-15","order":8,"canonicalText":"今陳國火朝覿矣，而道路若塞，野場若棄，澤不陂障，川無舟梁，是廢先王之教也。","chunks":[["今陳國火朝覿矣，而道路若塞，野場若棄，澤不陂障，川無舟梁，是廢先王之教也。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-15_s-9","passageId":"guo-yu_ch-2_p-15","order":9,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"guo-yu_ch-2_p-16_s-1","passageId":"guo-yu_ch-2_p-16","order":1,"canonicalText":"「《周制》有之曰：『列樹以表道，立鄙食以守路，國有郊牧，疆有寓望，藪有圃草，囿有林池，所以御災也。","chunks":[["「《周制》有之曰：『列樹以表道，立鄙食以守路，國有郊牧，疆有寓望，藪有圃草，囿有林池，所以御災也。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-16_s-2","passageId":"guo-yu_ch-2_p-16","order":2,"canonicalText":"其餘無非穀土，民無懸耜，野無奧草。","chunks":[["其餘無非穀土，民無懸耜，野無奧草。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-16_s-3","passageId":"guo-yu_ch-2_p-16","order":3,"canonicalText":"不奪民時，不蔑民功。","chunks":[["不奪民時，不蔑民功。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-16_s-4","passageId":"guo-yu_ch-2_p-16","order":4,"canonicalText":"有優無匱，有逸無罷。","chunks":[["有優無匱，有逸無罷。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-16_s-5","passageId":"guo-yu_ch-2_p-16","order":5,"canonicalText":"國有班事，縣有序民。","chunks":[["國有班事，縣有序民。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-16_s-6","passageId":"guo-yu_ch-2_p-16","order":6,"canonicalText":"』今陳國道路不可知，田在草間，功成而不收，民罷於逸樂，是棄先王之法制也。","chunks":[["』今陳國道路不可知，田在草間，功成而不收，民罷於逸樂，是棄先王之法制也。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-17_s-1","passageId":"guo-yu_ch-2_p-17","order":1,"canonicalText":"「周之《秩官》有之曰：『敵國賓至，關尹以告，行理以節逆之，候人為導，卿出郊勞，門尹除門，宗祝執祀，司裏授館，司徒具徒，司空視途，司寇詰奸，虞人入材，甸人積薪，火師監燎，水師監濯，膳宰致饔，廩人獻餼，司馬陳芻，工人展車，百官以物至，賓入如歸。","chunks":[["「周之《秩官》有之曰：『敵國賓至，關尹以告，行理以節逆之，候人為導，卿出郊勞，門尹除門，宗祝執祀，司裏授館，司徒具徒，司空視途，司寇詰奸，虞人入材，甸人積薪，火師監燎，水師監濯，膳宰致饔，廩人獻餼，司馬陳芻，工人展車，百官以物至，賓入如歸。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-17_s-2","passageId":"guo-yu_ch-2_p-17","order":2,"canonicalText":"是故小大莫不懷愛。","chunks":[["是故小大莫不懷愛。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-17_s-3","passageId":"guo-yu_ch-2_p-17","order":3,"canonicalText":"其貴國之賓至，則以班加一等，益虔。","chunks":[["其貴國之賓至，則以班加一等，益虔。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-17_s-4","passageId":"guo-yu_ch-2_p-17","order":4,"canonicalText":"至於王吏，則皆官正蒞事，上卿監之。","chunks":[["至於王吏，則皆官正蒞事，上卿監之。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-17_s-5","passageId":"guo-yu_ch-2_p-17","order":5,"canonicalText":"若王巡守，則君親監之。","chunks":[["若王巡守，則君親監之。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-17_s-6","passageId":"guo-yu_ch-2_p-17","order":6,"canonicalText":"』今雖朝也不才，有分族於周，承王命以為過賓於陳，而司事莫至，是蔑先王之官也。","chunks":[["』今雖朝也不才，有分族於周，承王命以為過賓於陳，而司事莫至，是蔑先王之官也。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-18_s-1","passageId":"guo-yu_ch-2_p-18","order":1,"canonicalText":"「先王之令有之曰：『天道賞善而罰淫，故凡我造國，無從非彝，無即慆淫，各守爾典，以承天休。","chunks":[["「先王之令有之曰：『天道賞善而罰淫，故凡我造國，無從非彝，無即慆淫，各守爾典，以承天休。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-18_s-2","passageId":"guo-yu_ch-2_p-18","order":2,"canonicalText":"』今陳侯不念胤續之常，棄其伉儷妃嬪，而帥其卿佐以淫於夏氏，不亦嬻姓矣乎？","chunks":[["』今陳侯不念胤續之常，棄其伉儷妃嬪，而帥其卿佐以淫於夏氏，不亦嬻姓矣乎？","zh-Hant"]]},{"id":"guo-yu_ch-2_p-18_s-3","passageId":"guo-yu_ch-2_p-18","order":3,"canonicalText":"陳，我大姬之後也。","chunks":[["陳，我大姬之後也。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-18_s-4","passageId":"guo-yu_ch-2_p-18","order":4,"canonicalText":"棄袞冕而南冠以出，不亦簡彝乎？","chunks":[["棄袞冕而南冠以出，不亦簡彝乎？","zh-Hant"]]},{"id":"guo-yu_ch-2_p-18_s-5","passageId":"guo-yu_ch-2_p-18","order":5,"canonicalText":"是又犯先王之令也。","chunks":[["是又犯先王之令也。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-18_s-6","passageId":"guo-yu_ch-2_p-18","order":6,"canonicalText":"］","chunks":[["］","zh-Hant"]]},{"id":"guo-yu_ch-2_p-19_s-1","passageId":"guo-yu_ch-2_p-19","order":1,"canonicalText":"「昔先王之教，懋帥其德也，猶恐殞越。","chunks":[["「昔先王之教，懋帥其德也，猶恐殞越。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-19_s-2","passageId":"guo-yu_ch-2_p-19","order":2,"canonicalText":"若廢其教而棄其制，蔑其官而犯其令，將何以守國？","chunks":[["若廢其教而棄其制，蔑其官而犯其令，將何以守國？","zh-Hant"]]},{"id":"guo-yu_ch-2_p-19_s-3","passageId":"guo-yu_ch-2_p-19","order":3,"canonicalText":"居大國之間，而無此四者，其能久乎？","chunks":[["居大國之間，而無此四者，其能久乎？","zh-Hant"]]},{"id":"guo-yu_ch-2_p-19_s-4","passageId":"guo-yu_ch-2_p-19","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"guo-yu_ch-2_p-20_s-1","passageId":"guo-yu_ch-2_p-20","order":1,"canonicalText":"六年，單子如楚。","chunks":[["六年，單子如楚。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-20_s-2","passageId":"guo-yu_ch-2_p-20","order":2,"canonicalText":"八年，陳侯殺於夏氏。","chunks":[["八年，陳侯殺於夏氏。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-20_s-3","passageId":"guo-yu_ch-2_p-20","order":3,"canonicalText":"九年，楚子入陳。","chunks":[["九年，楚子入陳。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-21_s-1","passageId":"guo-yu_ch-2_p-21","order":1,"canonicalText":"定王八年，使劉康公聘於魯，發幣於大夫。","chunks":[["定王八年，使劉康公聘於魯，發幣於大夫。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-21_s-2","passageId":"guo-yu_ch-2_p-21","order":2,"canonicalText":"季文子、孟獻子皆儉，叔孫宣子、東門子家皆侈。","chunks":[["季文子、孟獻子皆儉，叔孫宣子、東門子家皆侈。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-22_s-1","passageId":"guo-yu_ch-2_p-22","order":1,"canonicalText":"歸，王問魯大夫孰賢？","chunks":[["歸，王問魯大夫孰賢？","zh-Hant"]]},{"id":"guo-yu_ch-2_p-22_s-2","passageId":"guo-yu_ch-2_p-22","order":2,"canonicalText":"對曰：「季、孟其長處魯乎！","chunks":[["對曰：「季、孟其長處魯乎！","zh-Hant"]]},{"id":"guo-yu_ch-2_p-22_s-3","passageId":"guo-yu_ch-2_p-22","order":3,"canonicalText":"叔孫、東門其亡乎！","chunks":[["叔孫、東門其亡乎！","zh-Hant"]]},{"id":"guo-yu_ch-2_p-22_s-4","passageId":"guo-yu_ch-2_p-22","order":4,"canonicalText":"若家不亡，身必不免。","chunks":[["若家不亡，身必不免。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-22_s-5","passageId":"guo-yu_ch-2_p-22","order":5,"canonicalText":"」王曰：「何故？","chunks":[["」王曰：「何故？","zh-Hant"]]},{"id":"guo-yu_ch-2_p-22_s-6","passageId":"guo-yu_ch-2_p-22","order":6,"canonicalText":"」對曰：「臣聞之：為臣必臣，為君必君，寬肅宣惠，君也；","chunks":[["」對曰：「臣聞之：為臣必臣，為君必君，寬肅宣惠，君也；","zh-Hant"]]},{"id":"guo-yu_ch-2_p-22_s-7","passageId":"guo-yu_ch-2_p-22","order":7,"canonicalText":"敬恪恭儉，臣也。","chunks":[["敬恪恭儉，臣也。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-22_s-8","passageId":"guo-yu_ch-2_p-22","order":8,"canonicalText":"寬所以保本也，肅所以濟時也，宣所以教施也，惠所以和民也。","chunks":[["寬所以保本也，肅所以濟時也，宣所以教施也，惠所以和民也。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-22_s-9","passageId":"guo-yu_ch-2_p-22","order":9,"canonicalText":"本有保則必固，時動而濟則無敗功，教施而宣則遍，惠以和民則阜。","chunks":[["本有保則必固，時動而濟則無敗功，教施而宣則遍，惠以和民則阜。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-22_s-10","passageId":"guo-yu_ch-2_p-22","order":10,"canonicalText":"若本固而功成，施遍而民阜，乃可以長保民矣，其何事不徹？","chunks":[["若本固而功成，施遍而民阜，乃可以長保民矣，其何事不徹？","zh-Hant"]]},{"id":"guo-yu_ch-2_p-22_s-11","passageId":"guo-yu_ch-2_p-22","order":11,"canonicalText":"敬所以承命也，恪所以守業也，恭所以給事也，儉所以足用也。","chunks":[["敬所以承命也，恪所以守業也，恭所以給事也，儉所以足用也。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-22_s-12","passageId":"guo-yu_ch-2_p-22","order":12,"canonicalText":"以敬承命則不違，以恪守業則不懈，以恭給事則寬於死，以儉足用則遠於憂。","chunks":[["以敬承命則不違，以恪守業則不懈，以恭給事則寬於死，以儉足用則遠於憂。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-22_s-13","passageId":"guo-yu_ch-2_p-22","order":13,"canonicalText":"若承命不違，守業不懈，寬於死而遠於憂，則可以上下無隙矣，其何任不堪？","chunks":[["若承命不違，守業不懈，寬於死而遠於憂，則可以上下無隙矣，其何任不堪？","zh-Hant"]]},{"id":"guo-yu_ch-2_p-22_s-14","passageId":"guo-yu_ch-2_p-22","order":14,"canonicalText":"上任事而徹，下能堪其任，所以為令聞長世也。","chunks":[["上任事而徹，下能堪其任，所以為令聞長世也。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-22_s-15","passageId":"guo-yu_ch-2_p-22","order":15,"canonicalText":"今夫二子者儉，其能足用矣，用足則族可以庇。","chunks":[["今夫二子者儉，其能足用矣，用足則族可以庇。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-22_s-16","passageId":"guo-yu_ch-2_p-22","order":16,"canonicalText":"二子者侈，侈則不恤匱，匱而不恤，憂必及之，若是則必廣其身。","chunks":[["二子者侈，侈則不恤匱，匱而不恤，憂必及之，若是則必廣其身。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-22_s-17","passageId":"guo-yu_ch-2_p-22","order":17,"canonicalText":"且夫人臣而侈，國家弗堪，亡之道也。","chunks":[["且夫人臣而侈，國家弗堪，亡之道也。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-22_s-18","passageId":"guo-yu_ch-2_p-22","order":18,"canonicalText":"」王曰：「幾何？","chunks":[["」王曰：「幾何？","zh-Hant"]]},{"id":"guo-yu_ch-2_p-22_s-19","passageId":"guo-yu_ch-2_p-22","order":19,"canonicalText":"」對曰：「東門之位不若叔孫，而泰侈焉，不可以事二君。","chunks":[["」對曰：「東門之位不若叔孫，而泰侈焉，不可以事二君。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-22_s-20","passageId":"guo-yu_ch-2_p-22","order":20,"canonicalText":"叔孫之位不若季、孟，而亦泰侈焉，不可以事三君。","chunks":[["叔孫之位不若季、孟，而亦泰侈焉，不可以事三君。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-22_s-21","passageId":"guo-yu_ch-2_p-22","order":21,"canonicalText":"若皆蚤世猶可，若登年以載其毒，必亡。","chunks":[["若皆蚤世猶可，若登年以載其毒，必亡。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-22_s-22","passageId":"guo-yu_ch-2_p-22","order":22,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"guo-yu_ch-2_p-23_s-1","passageId":"guo-yu_ch-2_p-23","order":1,"canonicalText":"十六年，魯宣公卒。","chunks":[["十六年，魯宣公卒。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-23_s-2","passageId":"guo-yu_ch-2_p-23","order":2,"canonicalText":"赴者未及，東門氏來告亂，子家奔齊。","chunks":[["赴者未及，東門氏來告亂，子家奔齊。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-23_s-3","passageId":"guo-yu_ch-2_p-23","order":3,"canonicalText":"簡王十一年，魯叔孫宣伯亦奔齊，成公未歿二年。","chunks":[["簡王十一年，魯叔孫宣伯亦奔齊，成公未歿二年。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-24_s-1","passageId":"guo-yu_ch-2_p-24","order":1,"canonicalText":"簡王八年，魯成公來朝，使叔孫僑如先聘且告。","chunks":[["簡王八年，魯成公來朝，使叔孫僑如先聘且告。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-24_s-2","passageId":"guo-yu_ch-2_p-24","order":2,"canonicalText":"見王孫說，與之語。","chunks":[["見王孫說，與之語。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-24_s-3","passageId":"guo-yu_ch-2_p-24","order":3,"canonicalText":"說言於王曰：「魯叔孫之來也，必有異焉。","chunks":[["說言於王曰：「魯叔孫之來也，必有異焉。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-24_s-4","passageId":"guo-yu_ch-2_p-24","order":4,"canonicalText":"其享覲之幣薄而言諂，殆請之也，若請之，必欲賜也。","chunks":[["其享覲之幣薄而言諂，殆請之也，若請之，必欲賜也。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-24_s-5","passageId":"guo-yu_ch-2_p-24","order":5,"canonicalText":"魯執政唯強，故不歡焉而後遣之，且其狀方上而銳下，宜觸冒人。","chunks":[["魯執政唯強，故不歡焉而後遣之，且其狀方上而銳下，宜觸冒人。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-24_s-6","passageId":"guo-yu_ch-2_p-24","order":6,"canonicalText":"王其勿賜。","chunks":[["王其勿賜。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-24_s-7","passageId":"guo-yu_ch-2_p-24","order":7,"canonicalText":"若貪陵之人來而盈其願，是不賞善也，且財不給。","chunks":[["若貪陵之人來而盈其願，是不賞善也，且財不給。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-24_s-8","passageId":"guo-yu_ch-2_p-24","order":8,"canonicalText":"故聖人之施捨也議之，其喜怒取與亦議之。","chunks":[["故聖人之施捨也議之，其喜怒取與亦議之。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-24_s-9","passageId":"guo-yu_ch-2_p-24","order":9,"canonicalText":"是以不主寬惠，亦不主猛毅，主德義而已。","chunks":[["是以不主寬惠，亦不主猛毅，主德義而已。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-24_s-10","passageId":"guo-yu_ch-2_p-24","order":10,"canonicalText":"」王曰：「諾。","chunks":[["」王曰：「諾。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-24_s-11","passageId":"guo-yu_ch-2_p-24","order":11,"canonicalText":"」使私問諸魯，請之也。","chunks":[["」使私問諸魯，請之也。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-24_s-12","passageId":"guo-yu_ch-2_p-24","order":12,"canonicalText":"王遂不賜，禮如行人。","chunks":[["王遂不賜，禮如行人。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-24_s-13","passageId":"guo-yu_ch-2_p-24","order":13,"canonicalText":"及魯侯至，仲孫蔑為介，王孫說與之語，說讓。","chunks":[["及魯侯至，仲孫蔑為介，王孫說與之語，說讓。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-24_s-14","passageId":"guo-yu_ch-2_p-24","order":14,"canonicalText":"說以語王，王厚賄之。","chunks":[["說以語王，王厚賄之。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-25_s-1","passageId":"guo-yu_ch-2_p-25","order":1,"canonicalText":"晉既克楚於鄢，使郤至告慶於周。","chunks":[["晉既克楚於鄢，使郤至告慶於周。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-25_s-2","passageId":"guo-yu_ch-2_p-25","order":2,"canonicalText":"未將事，王叔簡公飲之酒，交酬好貨皆厚，飲酒宴語相說也。","chunks":[["未將事，王叔簡公飲之酒，交酬好貨皆厚，飲酒宴語相說也。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-26_s-1","passageId":"guo-yu_ch-2_p-26","order":1,"canonicalText":"明日，王孫子譽諸朝，郤至見邵桓公，與之語。","chunks":[["明日，王孫子譽諸朝，郤至見邵桓公，與之語。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-26_s-2","passageId":"guo-yu_ch-2_p-26","order":2,"canonicalText":"邵公以告單襄公曰：「王叔子譽溫季，以為必相晉國，相晉國，必大得諸侯，勸二三君子必先導焉，可以樹。","chunks":[["邵公以告單襄公曰：「王叔子譽溫季，以為必相晉國，相晉國，必大得諸侯，勸二三君子必先導焉，可以樹。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-26_s-3","passageId":"guo-yu_ch-2_p-26","order":3,"canonicalText":"今夫子見我，以晉國之克也，為己實謀之，曰：『微我，晉不戰矣！","chunks":[["今夫子見我，以晉國之克也，為己實謀之，曰：『微我，晉不戰矣！","zh-Hant"]]},{"id":"guo-yu_ch-2_p-26_s-4","passageId":"guo-yu_ch-2_p-26","order":4,"canonicalText":"楚有五敗，晉不知乘，我則強之。","chunks":[["楚有五敗，晉不知乘，我則強之。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-26_s-5","passageId":"guo-yu_ch-2_p-26","order":5,"canonicalText":"背宋之盟，一也；","chunks":[["背宋之盟，一也；","zh-Hant"]]},{"id":"guo-yu_ch-2_p-26_s-6","passageId":"guo-yu_ch-2_p-26","order":6,"canonicalText":"德薄而以地賂諸侯，二也；","chunks":[["德薄而以地賂諸侯，二也；","zh-Hant"]]},{"id":"guo-yu_ch-2_p-26_s-7","passageId":"guo-yu_ch-2_p-26","order":7,"canonicalText":"棄壯之良而用幼弱，三也；","chunks":[["棄壯之良而用幼弱，三也；","zh-Hant"]]},{"id":"guo-yu_ch-2_p-26_s-8","passageId":"guo-yu_ch-2_p-26","order":8,"canonicalText":"建立卿士而不用其言，四也；","chunks":[["建立卿士而不用其言，四也；","zh-Hant"]]},{"id":"guo-yu_ch-2_p-26_s-9","passageId":"guo-yu_ch-2_p-26","order":9,"canonicalText":"夷、鄭從之，三陳而不整，五也。","chunks":[["夷、鄭從之，三陳而不整，五也。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-26_s-10","passageId":"guo-yu_ch-2_p-26","order":10,"canonicalText":"罪不由晉，晉得其民，四軍之帥，旅力方剛；","chunks":[["罪不由晉，晉得其民，四軍之帥，旅力方剛；","zh-Hant"]]},{"id":"guo-yu_ch-2_p-26_s-11","passageId":"guo-yu_ch-2_p-26","order":11,"canonicalText":"卒伍治整，諸侯與之。","chunks":[["卒伍治整，諸侯與之。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-26_s-12","passageId":"guo-yu_ch-2_p-26","order":12,"canonicalText":"是有五勝也：有辭，一也；","chunks":[["是有五勝也：有辭，一也；","zh-Hant"]]},{"id":"guo-yu_ch-2_p-26_s-13","passageId":"guo-yu_ch-2_p-26","order":13,"canonicalText":"得民，二也；","chunks":[["得民，二也；","zh-Hant"]]},{"id":"guo-yu_ch-2_p-26_s-14","passageId":"guo-yu_ch-2_p-26","order":14,"canonicalText":"軍帥強御，三也；","chunks":[["軍帥強御，三也；","zh-Hant"]]},{"id":"guo-yu_ch-2_p-26_s-15","passageId":"guo-yu_ch-2_p-26","order":15,"canonicalText":"行列治整，四也；","chunks":[["行列治整，四也；","zh-Hant"]]},{"id":"guo-yu_ch-2_p-26_s-16","passageId":"guo-yu_ch-2_p-26","order":16,"canonicalText":"諸侯輯睦，五也。","chunks":[["諸侯輯睦，五也。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-26_s-17","passageId":"guo-yu_ch-2_p-26","order":17,"canonicalText":"有一勝猶足用也，有五勝以伐五敗，而避之者，非人也。","chunks":[["有一勝猶足用也，有五勝以伐五敗，而避之者，非人也。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-26_s-18","passageId":"guo-yu_ch-2_p-26","order":18,"canonicalText":"不可以不戰。","chunks":[["不可以不戰。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-26_s-19","passageId":"guo-yu_ch-2_p-26","order":19,"canonicalText":"欒、範不欲，我則強之。","chunks":[["欒、範不欲，我則強之。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-26_s-20","passageId":"guo-yu_ch-2_p-26","order":20,"canonicalText":"戰而勝，是吾力也。","chunks":[["戰而勝，是吾力也。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-26_s-21","passageId":"guo-yu_ch-2_p-26","order":21,"canonicalText":"且夫戰也微謀，吾有三伐；","chunks":[["且夫戰也微謀，吾有三伐；","zh-Hant"]]},{"id":"guo-yu_ch-2_p-26_s-22","passageId":"guo-yu_ch-2_p-26","order":22,"canonicalText":"勇而有禮，反之以仁。","chunks":[["勇而有禮，反之以仁。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-26_s-23","passageId":"guo-yu_ch-2_p-26","order":23,"canonicalText":"吾三逐楚君之卒，勇也；","chunks":[["吾三逐楚君之卒，勇也；","zh-Hant"]]},{"id":"guo-yu_ch-2_p-26_s-24","passageId":"guo-yu_ch-2_p-26","order":24,"canonicalText":"見其君必下而趨，禮也；","chunks":[["見其君必下而趨，禮也；","zh-Hant"]]},{"id":"guo-yu_ch-2_p-26_s-25","passageId":"guo-yu_ch-2_p-26","order":25,"canonicalText":"能獲鄭伯而赦之，仁也。","chunks":[["能獲鄭伯而赦之，仁也。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-26_s-26","passageId":"guo-yu_ch-2_p-26","order":26,"canonicalText":"若是而知晉國之政，楚、越必朝。","chunks":[["若是而知晉國之政，楚、越必朝。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-26_s-27","passageId":"guo-yu_ch-2_p-26","order":27,"canonicalText":"』","chunks":[["』","zh-Hant"]]},{"id":"guo-yu_ch-2_p-27_s-1","passageId":"guo-yu_ch-2_p-27","order":1,"canonicalText":"「吾曰：『子則賢矣。","chunks":[["「吾曰：『子則賢矣。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-27_s-2","passageId":"guo-yu_ch-2_p-27","order":2,"canonicalText":"抑晉國之舉也，不失其次，吾懼政之未及子也。","chunks":[["抑晉國之舉也，不失其次，吾懼政之未及子也。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-27_s-3","passageId":"guo-yu_ch-2_p-27","order":3,"canonicalText":"』謂我曰：『夫何次之有？","chunks":[["』謂我曰：『夫何次之有？","zh-Hant"]]},{"id":"guo-yu_ch-2_p-27_s-4","passageId":"guo-yu_ch-2_p-27","order":4,"canonicalText":"昔先大夫荀伯自下軍之佐以政，趙宣子未有軍行而以政，今欒伯自下軍往。","chunks":[["昔先大夫荀伯自下軍之佐以政，趙宣子未有軍行而以政，今欒伯自下軍往。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-27_s-5","passageId":"guo-yu_ch-2_p-27","order":5,"canonicalText":"是三子也，吾又過於四之無不及。","chunks":[["是三子也，吾又過於四之無不及。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-27_s-6","passageId":"guo-yu_ch-2_p-27","order":6,"canonicalText":"若佐新軍而升為政，不亦可乎？","chunks":[["若佐新軍而升為政，不亦可乎？","zh-Hant"]]},{"id":"guo-yu_ch-2_p-27_s-7","passageId":"guo-yu_ch-2_p-27","order":7,"canonicalText":"將必求之。","chunks":[["將必求之。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-27_s-8","passageId":"guo-yu_ch-2_p-27","order":8,"canonicalText":"』是其言也，君以為奚若？","chunks":[["』是其言也，君以為奚若？","zh-Hant"]]},{"id":"guo-yu_ch-2_p-27_s-9","passageId":"guo-yu_ch-2_p-27","order":9,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"guo-yu_ch-2_p-28_s-1","passageId":"guo-yu_ch-2_p-28","order":1,"canonicalText":"襄公曰：「人有言曰：『兵在其頸。","chunks":[["襄公曰：「人有言曰：『兵在其頸。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-28_s-2","passageId":"guo-yu_ch-2_p-28","order":2,"canonicalText":"』其郤至之謂乎！","chunks":[["』其郤至之謂乎！","zh-Hant"]]},{"id":"guo-yu_ch-2_p-28_s-3","passageId":"guo-yu_ch-2_p-28","order":3,"canonicalText":"君子不自稱也，非以讓也，惡其蓋人也。","chunks":[["君子不自稱也，非以讓也，惡其蓋人也。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-28_s-4","passageId":"guo-yu_ch-2_p-28","order":4,"canonicalText":"夫人性，陵上者也，不可蓋也。","chunks":[["夫人性，陵上者也，不可蓋也。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-28_s-5","passageId":"guo-yu_ch-2_p-28","order":5,"canonicalText":"求蓋人，其抑下滋甚，故聖人貴讓。","chunks":[["求蓋人，其抑下滋甚，故聖人貴讓。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-28_s-6","passageId":"guo-yu_ch-2_p-28","order":6,"canonicalText":"且諺曰：『獸惡其網，民惡其上。","chunks":[["且諺曰：『獸惡其網，民惡其上。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-28_s-7","passageId":"guo-yu_ch-2_p-28","order":7,"canonicalText":"』《》曰：『民可近也，而不可上也。","chunks":[["』《》曰：『民可近也，而不可上也。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-28_s-8","passageId":"guo-yu_ch-2_p-28","order":8,"canonicalText":"』《》曰：『愷悌君子，求福不回。","chunks":[["』《》曰：『愷悌君子，求福不回。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-28_s-9","passageId":"guo-yu_ch-2_p-28","order":9,"canonicalText":"』在禮，敵必三讓，是則聖人知民之不可加也。","chunks":[["』在禮，敵必三讓，是則聖人知民之不可加也。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-28_s-10","passageId":"guo-yu_ch-2_p-28","order":10,"canonicalText":"故王天下者必先諸民，然後庇焉，則能長利。","chunks":[["故王天下者必先諸民，然後庇焉，則能長利。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-28_s-11","passageId":"guo-yu_ch-2_p-28","order":11,"canonicalText":"今郤至在七人之下而欲上之，是求蓋七人也，其亦有七怨。","chunks":[["今郤至在七人之下而欲上之，是求蓋七人也，其亦有七怨。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-28_s-12","passageId":"guo-yu_ch-2_p-28","order":12,"canonicalText":"怨在小醜，猶不可堪，而況在侈卿乎？","chunks":[["怨在小醜，猶不可堪，而況在侈卿乎？","zh-Hant"]]},{"id":"guo-yu_ch-2_p-28_s-13","passageId":"guo-yu_ch-2_p-28","order":13,"canonicalText":"其何以待之？","chunks":[["其何以待之？","zh-Hant"]]},{"id":"guo-yu_ch-2_p-29_s-1","passageId":"guo-yu_ch-2_p-29","order":1,"canonicalText":"「晉之克也，天有惡於楚也，故儆之以晉。","chunks":[["「晉之克也，天有惡於楚也，故儆之以晉。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-29_s-2","passageId":"guo-yu_ch-2_p-29","order":2,"canonicalText":"而郤至佻天之功以為己力，不亦難乎？","chunks":[["而郤至佻天之功以為己力，不亦難乎？","zh-Hant"]]},{"id":"guo-yu_ch-2_p-29_s-3","passageId":"guo-yu_ch-2_p-29","order":3,"canonicalText":"佻天不祥，乘人不義，不祥則天棄之，不義則民叛之。","chunks":[["佻天不祥，乘人不義，不祥則天棄之，不義則民叛之。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-29_s-4","passageId":"guo-yu_ch-2_p-29","order":4,"canonicalText":"且郤至何三伐之有？","chunks":[["且郤至何三伐之有？","zh-Hant"]]},{"id":"guo-yu_ch-2_p-29_s-5","passageId":"guo-yu_ch-2_p-29","order":5,"canonicalText":"夫仁、禮、勇，皆民之為也。","chunks":[["夫仁、禮、勇，皆民之為也。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-29_s-6","passageId":"guo-yu_ch-2_p-29","order":6,"canonicalText":"以義死用謂之勇，奉義順則謂之禮，畜義豐功謂之仁。","chunks":[["以義死用謂之勇，奉義順則謂之禮，畜義豐功謂之仁。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-29_s-7","passageId":"guo-yu_ch-2_p-29","order":7,"canonicalText":"奸仁為佻，奸禮為羞，奸勇為賊。","chunks":[["奸仁為佻，奸禮為羞，奸勇為賊。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-29_s-8","passageId":"guo-yu_ch-2_p-29","order":8,"canonicalText":"夫戰，盡敵為上，守和同順義為上。","chunks":[["夫戰，盡敵為上，守和同順義為上。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-29_s-9","passageId":"guo-yu_ch-2_p-29","order":9,"canonicalText":"故制戎以果毅，制朝以序成。","chunks":[["故制戎以果毅，制朝以序成。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-29_s-10","passageId":"guo-yu_ch-2_p-29","order":10,"canonicalText":"叛戰而擅舍鄭君，賊也；","chunks":[["叛戰而擅舍鄭君，賊也；","zh-Hant"]]},{"id":"guo-yu_ch-2_p-29_s-11","passageId":"guo-yu_ch-2_p-29","order":11,"canonicalText":"棄毅行容，羞也；","chunks":[["棄毅行容，羞也；","zh-Hant"]]},{"id":"guo-yu_ch-2_p-29_s-12","passageId":"guo-yu_ch-2_p-29","order":12,"canonicalText":"叛國即讎，佻也。","chunks":[["叛國即讎，佻也。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-29_s-13","passageId":"guo-yu_ch-2_p-29","order":13,"canonicalText":"有三奸以求替其上，遠於得政矣。","chunks":[["有三奸以求替其上，遠於得政矣。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-29_s-14","passageId":"guo-yu_ch-2_p-29","order":14,"canonicalText":"以吾觀之，兵在其頸，不可久也。","chunks":[["以吾觀之，兵在其頸，不可久也。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-29_s-15","passageId":"guo-yu_ch-2_p-29","order":15,"canonicalText":"雖吾王叔，未能違難。","chunks":[["雖吾王叔，未能違難。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-29_s-16","passageId":"guo-yu_ch-2_p-29","order":16,"canonicalText":"在《太誓》曰：『民之所欲，天必從之。","chunks":[["在《太誓》曰：『民之所欲，天必從之。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-29_s-17","passageId":"guo-yu_ch-2_p-29","order":17,"canonicalText":"』王叔欲郤至，能勿從乎？","chunks":[["』王叔欲郤至，能勿從乎？","zh-Hant"]]},{"id":"guo-yu_ch-2_p-29_s-18","passageId":"guo-yu_ch-2_p-29","order":18,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"guo-yu_ch-2_p-30_s-1","passageId":"guo-yu_ch-2_p-30","order":1,"canonicalText":"郤至歸，明年死難。","chunks":[["郤至歸，明年死難。","zh-Hant"]]},{"id":"guo-yu_ch-2_p-30_s-2","passageId":"guo-yu_ch-2_p-30","order":2,"canonicalText":"及伯輿之獄，王叔陳生奔晉。","chunks":[["及伯輿之獄，王叔陳生奔晉。","zh-Hant"]]}]}') as WorkBundle
